// =====================================================================
// W18 d1：为什么要分角色 —— 从「一人一视同仁」到四种角色的必要性。
//
// 本机没有 Postgres，权限数据全部用内存结构模拟。
// 本程序要证明一件事：**一维的布尔开关无法同时满足四类真实用户的需求**。
// 这不是「布尔不好」，而是「一个值承载不了四种语义」。
// =====================================================================

package main

import "fmt"

// ---- 「一人一视同仁」的模型：整个系统只有一组全局开关 ----
type FlatPerm struct {
	ViewFinance  bool // 能不能看财务
	EditFinance  bool // 能不能记账
	AdminFamily  bool // 能不能管成员、邀请人
	EditCalendar bool // 能不能改日历
	ExportCSV    bool // 能不能导出
}

// ---- 四类真实用户 ----
type User struct {
	Name  string
	Story string // 他是谁
	Want  []Req  // 他真正需要什么（这是客观需求，不是偏好）
}

type Req struct {
	Perm string // 要动哪个能力
	Need bool   // 需要吗
	Why  string // 为什么需要 / 为什么不需要
}

var users = []User{
	{
		Name:  "张伟",
		Story: "一家之主，房贷水电都在他名下",
		Want: []Req{
			{"ViewFinance", true, "要看全家的账本月花了多少"},
			{"EditFinance", true, "他要记大额支出"},
			{"AdminFamily", true, "只有他能邀请家人、移除成员"},
			{"EditCalendar", true, "全家行程他排"},
			{"ExportCSV", true, "年底要做家庭年度报表"},
		},
	},
	{
		Name:  "李娜",
		Story: "上班的配偶，每天只记自己的午饭和打车",
		Want: []Req{
			{"ViewFinance", true, "她要知道这个月还剩多少预算"},
			{"EditFinance", true, "她的主要动作就是记账"},
			{"AdminFamily", false, "她管不了成员，也不该管"},
			{"EditCalendar", true, "她排自己的就诊和体检"},
			{"ExportCSV", false, "她不做年度报表"},
		},
	},
	{
		Name:  "小满",
		Story: "12 岁，还在长身体，只看得到「明天的安排」",
		Want: []Req{
			{"ViewFinance", false, "她碰不到任何金额，这是隐私也是法律要求"},
			{"EditFinance", false, "儿童默认不能记账"},
			{"AdminFamily", false, "她不是管理员"},
			{"EditCalendar", true, "她要看「今天要做什么」并打勾"},
			{"ExportCSV", false, "导出无意义"},
		},
	},
	{
		Name:  "王姨",
		Story: "来住两周的亲戚，看一眼这个月花销就走",
		Want: []Req{
			{"ViewFinance", true, "她要看，但只看最近三十天"},
			{"EditFinance", false, "她不记账"},
			{"AdminFamily", false, "她不是成员"},
			{"EditCalendar", false, "她只看，不改"},
			{"ExportCSV", false, "访客不可导出，否则能整份带走"},
		},
	},
}

func permsOf(p FlatPerm) map[string]bool {
	return map[string]bool{
		"ViewFinance":  p.ViewFinance,
		"EditFinance":  p.EditFinance,
		"AdminFamily":  p.AdminFamily,
		"EditCalendar": p.EditCalendar,
		"ExportCSV":    p.ExportCSV,
	}
}

// ---- 引入角色：一组有名字的能力集合 ----
type Role struct {
	Code  string
	Label string
	Caps  map[string]bool // 这个角色默认能做什么
	Note  string
}

var roles = []Role{
	{
		Code:  "owner",
		Label: "管理员",
		Caps: map[string]bool{
			"ViewFinance": true, "EditFinance": true, "AdminFamily": true,
			"EditCalendar": true, "ExportCSV": true,
		},
		Note: "唯一能转让家庭、能解散、能移除别人的人",
	},
	{
		Code:  "member",
		Label: "成人成员",
		Caps: map[string]bool{
			"ViewFinance": true, "EditFinance": true, "AdminFamily": false,
			"EditCalendar": true, "ExportCSV": false,
		},
		Note: "能记账、能看全家汇总，但管不了人",
	},
	{
		Code:  "ward",
		Label: "儿童/老人（被记录者）",
		Caps: map[string]bool{
			"ViewFinance": false, "EditFinance": false, "AdminFamily": false,
			"EditCalendar": true, "ExportCSV": false,
		},
		Note: "碰不到钱，只能处理自己的日程",
	},
	{
		Code:  "guest",
		Label: "访客",
		Caps: map[string]bool{
			"ViewFinance": true, "EditFinance": false, "AdminFamily": false,
			"EditCalendar": false, "ExportCSV": false,
		},
		Note: "限时只读，默认 30 天，可随时撤销",
	},
}

func main() {
	fmt.Println("=== 1. 现状：一个「一人一视同仁」的家庭记账 App ===")
	fmt.Println("  全系统只有一组全局开关。所有登录用户看到的东西完全一样。")
	fmt.Println()
	fmt.Println("  这组开关：")
	for _, c := range []struct {
		k string
		v bool
	}{
		{"ViewFinance  看财务", true},
		{"EditFinance  记账", true},
		{"AdminFamily  管成员", true},
		{"EditCalendar 改日历", true},
		{"ExportCSV    导出", true},
	} {
		mark := "✗"
		if c.v {
			mark = "✓"
		}
		fmt.Printf("    %s %s\n", mark, c.k)
	}
	fmt.Println()

	fmt.Println("=== 2. 四类真实用户，以及他们真实的需求 ===")
	for _, u := range users {
		fmt.Printf("  【%s】%s\n", u.Name, u.Story)
		for _, r := range u.Want {
			mark := "·"
			if r.Need {
				mark = "＋"
			}
			fmt.Printf("      %s %-14s %s\n", mark, r.Perm, r.Why)
		}
		fmt.Println()
	}

	fmt.Println("=== 3. 同一个能力，四个人要的东西不一样 ===")
	fmt.Println("  重点看 AdminFamily（管成员 / 邀请人）这一列：")
	fmt.Printf("    %-8s %-12s %s\n", "用户", "需求", "理由")
	for _, u := range users {
		for _, r := range u.Want {
			if r.Perm == "AdminFamily" {
				mark := "不需要"
				if r.Need {
					mark = "需要"
				}
				fmt.Printf("    %-8s %-12s %s\n", u.Name, mark, r.Why)
			}
		}
	}
	fmt.Println()
	fmt.Println("  → 一个布尔值要同时满足「张伟需要」和「李娜不需要」，")
	fmt.Println("    除非你能区分他们是谁。你一旦能区分，就是在做角色。")
	fmt.Println()

	fmt.Println("=== 4. 「全开」和「全关」各错多少格 ===")
	perms := []string{"ViewFinance", "EditFinance", "AdminFamily", "EditCalendar", "ExportCSV"}
	strategies := []struct {
		name string
		p    FlatPerm
	}{
		{"全局一律开（今天的做法）", FlatPerm{true, true, true, true, true}},
		{"全局一律关（矫枉过正）", FlatPerm{}},
	}
	for _, s := range strategies {
		got := permsOf(s.p)
		wrong, tooMany, tooFew := 0, 0, 0
		for _, u := range users {
			for _, r := range u.Want {
				if got[r.Perm] != r.Need {
					wrong++
					if got[r.Perm] {
						tooMany++
					} else {
						tooFew++
					}
				}
			}
		}
		total := len(users) * len(perms)
		fmt.Printf("  %s\n", s.name)
		fmt.Printf("    总格子 %d，错 %d 格（多给 %d，少给 %d），准确率 %.0f%%\n",
			total, wrong, tooMany, tooFew, float64(total-wrong)/float64(total)*100)
	}
	fmt.Println()
	fmt.Println("  「一律开」最危险的那一格：")
	fmt.Println("    小满 ViewFinance=true → 他看到全家的金额。")
	fmt.Println("    这不只是产品体验问题，是**儿童个人信息泄露**。")
	fmt.Println("  「一律关」的问题是李娜记不了账，App 当天就没人用。")
	fmt.Println()

	fmt.Println("=== 5. 换成角色：同一批格，错 0 格 ===")
	fmt.Printf("  %-8s %-7s", "用户", "角色")
	for _, p := range perms {
		fmt.Printf(" %-13s", p)
	}
	fmt.Println()
	assign := map[string]string{"张伟": "owner", "李娜": "member", "小满": "ward", "王姨": "guest"}
	totalCells, wrongCells := 0, 0
	for _, u := range users {
		rc := assign[u.Name]
		caps := map[string]bool{}
		for _, r := range roles {
			if r.Code == rc {
				caps = r.Caps
			}
		}
		fmt.Printf("  %-8s %-7s", u.Name, rc)
		for _, p := range perms {
			want := false
			for _, r := range u.Want {
				if r.Perm == p {
					want = r.Need
				}
			}
			mark := "✗"
			if caps[p] == want {
				mark = "✓"
			} else {
				wrongCells++
			}
			totalCells++
			fmt.Printf(" %s%-12s", mark, yesNo(caps[p]))
		}
		fmt.Println()
	}
	fmt.Println()
	fmt.Printf("  总格子 %d，错 %d 格。\n", totalCells, wrongCells)
	fmt.Println("  这不是运气 —— 角色数量是 4，需求画像也是 4，")
	fmt.Println("  每个画像由 tech-plan §8.1 的业务决策给定，不是拍脑袋调出来的。")
	fmt.Println()

	fmt.Println("=== 6. 角色枚举本体的样子（这就是明天要落表的东西）===")
	for i, r := range roles {
		on := []string{}
		for _, p := range perms {
			if r.Caps[p] {
				on = append(on, p)
			}
		}
		fmt.Printf("  %d. %-7s %-18s 可做 %d/5：%v\n", i+1, r.Code, r.Label, len(on), on)
		fmt.Printf("        %s\n", r.Note)
	}
	fmt.Println()
	fmt.Println("  四级角色固定不变 —— homeos_role 表只会有这 4 行数据，")
	fmt.Println("  它是**代码枚举的镜像**，不是可以随便加行的配置表。")
	fmt.Println()

	fmt.Println("=== 7. 一个常见的误解：「多建几个角色不就完了」 ===")
	bogus := []struct{ what, why string }{
		{"owner_full / owner_readonly", "一个人同时是两个角色会让判定函数出现二义"},
		{"member_teen / member_adult", "年龄是家庭内的关系数据，不是权限维度"},
		{"member_spouse / member_parent", "同一个人可能既是配偶又是家长"},
		{"guest_30d / guest_7d", "时长是 condition，不该撑成两个角色"},
	}
	fmt.Println("  每个人加一个角色，看起来能做，但会立刻爆炸：")
	for _, b := range bogus {
		fmt.Printf("    ❌ %-28s %s\n", b.what, b.why)
	}
	fmt.Println()
	fmt.Println("  4 个角色 × 2 = 8 个；再加 3 个特例 = 24 个；再加 3 个 = 96 个。")
	fmt.Println("  每加一个角色，矩阵格数都翻倍，而**没人能记住 96 格的语义**。")
	fmt.Println("  正确做法：角色少（4 个），差异靠 action 与 condition 表达。")
	fmt.Println()

	fmt.Println("=== 8. 与 JS / 前端对比 ===")
	fmt.Println("  ① 在 TypeScript 里写角色，你会这么写：")
	fmt.Println("       type Role = 'owner' | 'member' | 'ward' | 'guest'")
	fmt.Println("     这是一个**联合类型**，只在编译期存在，接口返回的 JSON 里仍是字符串。")
	fmt.Println("     Go 侧对应的是 `type Role string` + 常量，两边行为一致。")
	fmt.Println("  ② 前端一定要做「按角色显示按钮」，但**原因不是安全，是体验**。")
	fmt.Println("     真正拦住越权请求的必须是服务端：curl 一个不带前端代码的请求，")
	fmt.Println("     你组件里的 if 一行都不会执行。")
	fmt.Println("  ③ 最容易犯的错：前端从接口拿回 role，")
	fmt.Println("     在组件里写 `if (role === 'owner') return <删除按钮 />`。")
	fmt.Println("     这行代码没错，但它不构成任何保护 —— 服务端 handler 没判角色，")
	fmt.Println("     删除接口照样通。")
	fmt.Println("  ④ 所以本阶段讲的每一个「判定」，最终都必须落在")
	fmt.Println("     服务端的一个函数里，而且能被测试直接调用。")
	fmt.Println()

	fmt.Println("=== 9. 本阶段的四个角色，最后确认一次 ===")
	summary := []struct{ role, can, cannot string }{
		{"owner", "全部 5 项 + 转让/解散家庭", "不能移除自己（必须先转让）"},
		{"member", "看全家财务、记账、改日历", "不能管成员与邀请、不能导出"},
		{"ward", "只看/勾选自己的日历", "完全碰不到钱（无读无写）"},
		{"guest", "限时只读财务 + 只读面配置", "不能改、不能导出、可随时撤销"},
	}
	for _, s := range summary {
		fmt.Printf("  %-8s 能：%s\n", s.role, s.can)
		fmt.Printf("  %-8s 不能：%s\n", "", s.cannot)
	}
	fmt.Println()

	fmt.Println("=== 10. 明天 ===")
	fmt.Println("  今天证明了「需要角色」。明天给这四个角色正式下定义：")
	fmt.Println("  每个角色的边界、ward 那种「可以没有账号」的特例、")
	fmt.Println("  以及 guest 那个「默认 30 天」的时效 —— 然后落成枚举。")
}

func yesNo(b bool) string {
	if b {
		return "是"
	}
	return "否"
}

// =====================================================================
// W18 d2：四级角色的正式定义 —— owner / member / ward / guest。
//
// 本机没有 Postgres。下面对应的表结构以 DDL 字符串给出（不假装跑过），
// 角色枚举与能力矩阵是**内存真跑**的，并且会输出完整的四行角色清单。
// 判据要求「每级的权限清单能列出来」，这个清单今天就产出。
// =====================================================================

package main

import (
	"fmt"
	"strings"
)

// ---- 角色枚举：Go 里用自定义 string 类型 + 常量 ----
// 对应 TS 的 `type Role = 'owner' | 'member' | 'ward' | 'guest'`
type Role string

const (
	RoleOwner  Role = "owner"
	RoleMember Role = "member"
	RoleWard   Role = "ward"
	RoleGuest  Role = "guest"
)

// AllRoles 的顺序是固定的：矩阵的列顺序依赖它，别改。
var AllRoles = []Role{RoleOwner, RoleMember, RoleWard, RoleGuest}

func (r Role) Label() string {
	switch r {
	case RoleOwner:
		return "管理员"
	case RoleMember:
		return "成人成员"
	case RoleWard:
		return "儿童/老人"
	case RoleGuest:
		return "访客"
	}
	return "未知"
}

// Valid 用穷举而不是 switch default，能在新增角色时逼你补齐。
func (r Role) Valid() bool {
	switch r {
	case RoleOwner, RoleMember, RoleWard, RoleGuest:
		return true
	}
	return false
}

// ---- 能力项：tech-plan §8.4 矩阵里出现的所有列 ----
type Cap string

const (
	CapViewFinance    Cap = "read:finance"    // 看财务
	CapWriteFinance   Cap = "write:finance"   // 记账
	CapAdminFamily    Cap = "admin:family"    // 管成员、邀请
	CapTransferOwner  Cap = "transfer:owner"  // 转让管理员
	CapDissolveFamily Cap = "dissolve:family" // 解散家庭
	CapReadCalendar   Cap = "read:calendar"   // 读日历
	CapWriteCalendar  Cap = "write:calendar"  // 改日历、勾选待办
	CapConfigModule   Cap = "config:module"   // 面配置（页面布局）
	CapExport         Cap = "export:data"     // 导出 CSV
	CapViewPrivate    Cap = "view:private"    // 看别人私密流水
)

var AllCaps = []Cap{
	CapViewFinance, CapWriteFinance, CapAdminFamily, CapTransferOwner, CapDissolveFamily,
	CapReadCalendar, CapWriteCalendar, CapConfigModule, CapExport, CapViewPrivate,
}

func (c Cap) Label() string {
	m := map[Cap]string{
		CapViewFinance:    "看财务",
		CapWriteFinance:   "记账",
		CapAdminFamily:    "管成员与邀请",
		CapTransferOwner:  "转让管理员",
		CapDissolveFamily: "解散家庭",
		CapReadCalendar:   "读日历",
		CapWriteCalendar:  "改日历与勾选待办",
		CapConfigModule:   "面配置",
		CapExport:         "导出数据",
		CapViewPrivate:    "看他人私密流水",
	}
	return m[c]
}

// ---- 角色定义本体：这就是 homeos_role 表那 4 行的内容 ----
type RoleDef struct {
	Code     Role
	Can      []Cap
	NotCan   []Cap // 明确不能的，写出来是为了让「默认=false」变成显式决策
	KeyLimit string
	Why      string
}

var defs = map[Role]RoleDef{
	RoleOwner: {
		Code: RoleOwner,
		Can: []Cap{CapViewFinance, CapWriteFinance, CapAdminFamily, CapTransferOwner,
			CapDissolveFamily, CapReadCalendar, CapWriteCalendar, CapConfigModule,
			CapExport, CapViewPrivate},
		NotCan:   nil,
		KeyLimit: "不能移除自己",
		Why:      "唯一能转让 / 解散的人，也是家庭里唯一能管成员的人",
	},
	RoleMember: {
		Code: RoleMember,
		Can:  []Cap{CapViewFinance, CapWriteFinance, CapReadCalendar, CapWriteCalendar, CapViewPrivate},
		NotCan: []Cap{CapAdminFamily, CapTransferOwner, CapDissolveFamily,
			CapConfigModule, CapExport},
		KeyLimit: "不能管理成员与邀请",
		Why:      "成人成员的日常操作，但涉及「人的操作」一律不开放",
	},
	RoleWard: {
		Code: RoleWard,
		Can:  []Cap{CapReadCalendar, CapWriteCalendar},
		NotCan: []Cap{CapViewFinance, CapWriteFinance, CapAdminFamily, CapTransferOwner,
			CapDissolveFamily, CapConfigModule, CapExport, CapViewPrivate},
		KeyLimit: "可无账号；由监护人代管",
		Why:      "儿童 / 老人是「被记录者」，隐私上要挡住金额，能力上只留日历",
	},
	RoleGuest: {
		Code: RoleGuest,
		Can:  []Cap{CapViewFinance, CapReadCalendar, CapConfigModule},
		NotCan: []Cap{CapWriteFinance, CapAdminFamily, CapTransferOwner, CapDissolveFamily,
			CapWriteCalendar, CapExport, CapViewPrivate},
		KeyLimit: "限时只读，默认 30 天，可撤销",
		Why:      "临时的外部人，只读 + 会过期，可被 owner 随时踢掉",
	},
}

// Has 是唯一的能力判定入口。**不要在别处再写一遍 switch。**
func Has(r Role, c Cap) bool {
	d, ok := defs[r]
	if !ok {
		return false // 未知角色一律拒绝（fail closed）
	}
	for _, x := range d.Can {
		if x == c {
			return true
		}
	}
	return false
}

// ---- 对应的 DDL：homeos_role / homeos_member 的角色列 ----
const ddl = `-- 角色表：固定 4 行，是代码枚举的镜像，不是随便加行的配置表
CREATE TABLE homeos_role (
    code        VARCHAR(16) PRIMARY KEY,          -- owner/member/ward/guest
    name        VARCHAR(32) NOT NULL,
    permissions JSONB      NOT NULL DEFAULT '{}'::jsonb,
    created_at  TIMESTAMPTZ NOT NULL DEFAULT now(),
    CONSTRAINT homeos_role_code_check CHECK (code IN ('owner','member','ward','guest'))
);

-- 成员表里 role 的取值被同一个 CHECK 锁死
CREATE TABLE homeos_member (
    id           UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    family_id    UUID        NOT NULL,
    user_id      UUID        NULL,   -- 可空！= 无账号的被记录成员（儿童/老人）
    name         VARCHAR(32) NOT NULL,
    relation     VARCHAR(16) NOT NULL,  -- 爸爸/妈妈/奶奶，家庭内称谓的权威字段
    role         VARCHAR(16) NOT NULL,
    avatar       TEXT        NULL,
    status       VARCHAR(16) NOT NULL DEFAULT 'active',
    guardian_id  UUID        NULL,   -- ward 指向监护人 member.id
    version      INTEGER     NOT NULL DEFAULT 1,
    created_at   TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at   TIMESTAMPTZ NOT NULL DEFAULT now(),
    deleted_at   TIMESTAMPTZ,
    CONSTRAINT homeos_member_role_check   CHECK (role IN ('owner','member','ward','guest')),
    CONSTRAINT homeos_member_status_check CHECK (status IN ('active','left','suspended')),
    CONSTRAINT homeos_member_guardian_check
        CHECK (role <> 'ward' OR guardian_id IS NOT NULL)
);
CREATE UNIQUE INDEX homeos_member_family_user_uq
    ON homeos_member (family_id, user_id) WHERE deleted_at IS NULL AND user_id IS NOT NULL;
