// W18 d5：「已退出成员」为什么不是角色 —— 它是展示态。
//
// 本机没有 Postgres，数据用内存 slice 模拟（判定与渲染逻辑真跑）。
// 今天要拆掉一个几乎所有人都会犯的错误：
//   给 homeos_role 表加第五行 role = 'left'（或 'exited'）。
// 程序会真跑一遍：如果它是角色，判定函数会发生什么。
// =====================================================================

package main

import (
	"fmt"
)

type Role string

const (
	RoleOwner  Role = "owner"
	RoleMember Role = "member"
	RoleWard   Role = "ward"
	RoleGuest  Role = "guest"
)

// status 是**另一个字段**，与 role 正交
type Status string

const (
	StatusActive      Status = "active"
	StatusLeft        Status = "left"      // 主动退出，数据留家庭
	StatusSuspended   Status = "suspended" // 被 owner 停用
	StatusDeactivated Status = "deactivated"
)

type Member struct {
	ID         string
	FamilyID   string
	UserID     string
	Name       string
	Relation   string
	Role       Role
	Status     Status
	GuardianID string
	LeftAt     string
	Deleted    bool // 软删（技术性移除，与 status 无关）
}

// ---- 判定：角色提供能力，status 决定这个人还算不算数 ----
type Decision struct {
	Allow bool
	Why   string
}

func authz(m Member, capName string, capGrantedByRole map[Role]map[string]bool) Decision {
	if m.Deleted {
		return Decision{false, "记录已软删（技术性移除），一律拒绝"}
	}
	if m.Status == StatusLeft {
		return Decision{false, "已退出成员：role 不再参与判定"}
	}
	if m.Status == StatusSuspended {
		return Decision{false, "已停用：owner 主动封禁"}
	}
	granted, ok := capGrantedByRole[m.Role][capName]
	if !ok {
		return Decision{false, fmt.Sprintf("角色 %s 没有这项能力", m.Role)}
	}
	if !granted {
		return Decision{false, fmt.Sprintf("角色 %s 明确不提供「%s」", m.Role, capName)}
	}
	return Decision{true, fmt.Sprintf("角色 %s 提供「%s」且状态为 active", m.Role, capName)}
}

func isKnownRole(r Role) bool {
	switch r {
	case RoleOwner, RoleMember, RoleWard, RoleGuest:
		return true
	}
	return false
}

// ---- 展示层：作者名怎么渲染 ----
func displayAuthorName(m Member, lookup func(userID string) string) string {
	if m.Status == StatusLeft {
		return "已退出成员" // ★ 关键：不泄露「是谁退出过」，也不留下空链接
	}
	if m.Name != "" {
		return m.Name
	}
	if m.UserID != "" {
		return lookup(m.UserID)
	}
	return "未知成员"
}

