func AllFour() []Role { return []Role{RoleOwner, RoleMember, RoleWard, RoleGuest} }

func roleMeaning(r Role) string {
	switch r {
	case RoleOwner:
		return "管理员：唯一能转让/解散，且不能移除自己"
	case RoleMember:
		return "成人成员：能记账，不能管人"
	case RoleWard:
		return "儿童/老人：可无账号，监护人代管"
	case RoleGuest:
		return "访客：限时只读，默认 30 天，不可导出"
	}
	return "?"
}

func statusMeaning(s Status) string {
	switch s {
	case StatusActive:
		return "在家庭里，role 正常生效"
	case StatusLeft:
		return "主动退出：数据留家庭，权限全拒，展示为「已退出成员」"
	case StatusSuspended:
		return "被 owner 停用：数据留家庭，权限全拒"
	}
	return "?"
}

func yn(b bool) string {
	if b {
		return "✅"
	}
	return "❌"
}

