	RoleWard   Role = "ward"
	RoleGuest  Role = "guest"
)

var AllRoles = []Role{RoleOwner, RoleMember, RoleWard, RoleGuest}

func (r Role) Label() string {
	switch r {
	case RoleOwner:
		return "管理员"
	case RoleMember:
		return "成人成员"
	case RoleWard:
		return "儿童/老人"
	case RoleGuest:
		return "访客"
	}
	return "未知"
}

// ---------------- 自查工具 ----------------

type Check struct {
	Name   string
	OK     bool
	Detail string
}

type Suite struct {
	checks []Check
}

func (s *Suite) Add(name string, ok bool, detail string) {
	s.checks = append(s.checks, Check{name, ok, detail})
}

func (s *Suite) Report(title string) (pass, fail int) {
	fmt.Printf("  【%s】\n", title)
	for _, c := range s.checks {
		mark := "✅"
		if !c.OK {
			mark = "❌"
		}
		fmt.Printf("    %s %-44s %s\n", mark, c.Name, c.Detail)
		if c.OK {
			pass++
		} else {
			fail++
		}
	}
	fmt.Println()
	return
}

func mustRead(p string) string {
	b, err := os.ReadFile(p)
	if err != nil {
		return ""
	}
	return string(b)
}

// ---------------- 判定函数（P1 的三层之一：角色默认矩阵）----------------

type Caps map[string]bool

func roleCaps(r Role) Caps {
	switch r {
	case RoleOwner:
		return Caps{"view:finance": true, "write:finance": true, "admin:family": true,
			"transfer:owner": true, "dissolve:family": true, "view:calendar": true,
			"write:calendar": true, "config:module": true, "export:data": true, "view:private": true}
	case RoleMember:
		return Caps{"view:finance": true, "write:finance": true, "admin:family": false,
			"transfer:owner": false, "dissolve:family": false, "view:calendar": true,
			"write:calendar": true, "config:module": false, "export:data": false, "view:private": true}
	case RoleWard:
		return Caps{"view:finance": false, "write:finance": false, "admin:family": false,
			"transfer:owner": false, "dissolve:family": false, "view:calendar": true,
			"write:calendar": true, "config:module": false, "export:data": false, "view:private": false}
	case RoleGuest:
		return Caps{"view:finance": true, "write:finance": false, "admin:family": false,
			"transfer:owner": false, "dissolve:family": false, "view:calendar": true,
			"write:calendar": false, "config:module": true, "export:data": false, "view:private": false}
	}
	return Caps{} // fail closed
}

// Can 是唯一入口：未知角色返 false
func Can(r Role, capName string) bool {
	return roleCaps(r)[capName]
}

