func canRemoveSelf() bool { return false }

func canRemove(actor Role, targetMemberID string) bool {
	if !Can(actor, "admin:family") {
		return false
	}
	// 不能移除自己：owner 自己就是 admin:family 的唯一持有者
	return targetMemberID != "m-zhangwei"
}

func yn(b bool) string {
	if b {
		return "✅"
	}
	return "❌"
}

func baseNames(paths []string) []string {
	out := make([]string, 0, len(paths))
	for _, p := range paths {
		out = append(out, filepath.Base(p))
	}
	return out
}

