package main

import "fmt"

type Role string

const (
	RoleOwner  Role = "owner"
	RoleMember Role = "member"
	RoleWard   Role = "ward"
	RoleGuest  Role = "guest"
)

func (r Role) Label() string {
	switch r {
	case RoleOwner:
		return "owner"
	case RoleMember:
		return "member"
	case RoleWard:
		return "ward"
	case RoleGuest:
		return "guest"
	}
	return "unknown"
}

// ---- 一维模型：role → 一张扁平的 bool 表 ----
type OneDimPerm struct {
	CanSeeFinancePage bool
	CanSeeCalendar    bool
	CanSeeMembers     bool
}

func oneDim(r Role) OneDimPerm {
	switch r {
	case RoleOwner:
		return OneDimPerm{true, true, true}
	case RoleMember:
		return OneDimPerm{true, true, false}
	case RoleWard:
		return OneDimPerm{false, true, false}
	case RoleGuest:
		return OneDimPerm{true, true, false}
	}
	return OneDimPerm{}
}

// ---- 真实需求：四个问题 ----
type Question struct {
	Key    string
	Label  string
	Answer map[Role]bool // 这一维上的答案
}

// 问题 1：面级可见 —— 「这个人在导航里能不能看到财务这个面？」
