func main() {
	fmt.Println("=== 1. 一维权限模型长什么样 ===")
	fmt.Println("  最朴素的权限：一张 role → bool 的表。")
	fmt.Println("  「张三能不能看财务？」→ 查表 → true/false。结束。")
	fmt.Println()
	roles := []Role{RoleOwner, RoleMember, RoleWard, RoleGuest}
	fmt.Printf("  %-10s", "能力")
	for _, r := range roles {
		fmt.Printf(" %-9s", r.Label())
	}
	fmt.Println()
	for _, c := range []struct {
		name string
		get  func(OneDimPerm) bool
	}{
		{"看财务页", func(p OneDimPerm) bool { return p.CanSeeFinancePage }},
		{"看日历", func(p OneDimPerm) bool { return p.CanSeeCalendar }},
		{"看成员列表", func(p OneDimPerm) bool { return p.CanSeeMembers }},
	} {
		fmt.Printf("  %-10s", c.name)
		for _, r := range roles {
			fmt.Printf(" %-9s", yn(c.get(oneDim(r))))
		}
		fmt.Println()
	}
	fmt.Println()
	fmt.Println("  这张表看起来很干净。问题是它**只回答了一个问题**：")
	fmt.Println("  「这个人能不能进这个页面？」")
	fmt.Println()

	fmt.Println("=== 2. 真实需求其实是四个不同的问题 ===")
	fmt.Println("  把「权限」拆开问，会得到至少四个独立的问题：")
	fmt.Println()
	fmt.Printf("  %-30s %-9s %-9s %-9s %-9s\n", "问题", "owner", "member", "ward", "guest")
	fmt.Println("  " + dashes(66))
	conflictMap := map[string][]Role{}
	for _, q := range questions {
		fmt.Printf("  %-30s", q.Label)
		for _, r := range roles {
			fmt.Printf(" %-9s", yn(q.Answer[r]))
		}
		fmt.Println()
