		for i := 0; i < len(roles); i++ {
			for j := i + 1; j < len(roles); j++ {
				if q.Answer[roles[i]] != q.Answer[roles[j]] {
					conflictMap[q.Key] = append(conflictMap[q.Key], roles[i], roles[j])
				}
			}
		}
	}
	fmt.Println()

	fmt.Println("=== 3. 关键观察：同一个角色在不同问题上答案不同 ===")
	fmt.Println("  看 guest 这一列：")
