	fmt.Println("=== 4. 一维模型会怎么写错：三个真实的坑 ===")
	fmt.Println()
	bugs := []struct {
		what string
		why  string
	}{
		{
			"把 action 混进一维表：canSeeFinance 兼作 canCreateTransaction",
			"guest 会拿到 canSeeFinance=true → 顺手就能记账。要么他被挡在财务外（产品失败），要么他能记账（越权）。",
		},
		{
			"把 data 混进一维表：canSeeFinance 兼作 canSeeOthersPrivate",
			"member 的 canSeeFinance=true 会让他看到小满的私密开销（她 12 岁，不该被看到），或者全家都看不到私密（功能作废）。",
		},
		{
			"把 condition 混进一维表：canSeeFinance 兼作 canSeeExpiredGuestData",
			"visitor 过期后，如果判定只看角色不看时间，他照样能看。**时间条件没法用角色布尔表达**。",
		},
	}
	for i, b := range bugs {
		fmt.Printf("  坑 %d：%s\n", i+1, b.what)
		fmt.Printf("         %s\n", b.why)
	}
	fmt.Println()
	fmt.Println("  这三个坑的共同点：它们都是**把两个不同的问题塞进一个 bool**。")
	fmt.Println("  解法不是「写得更仔细」，而是**把问题拆开**。")
	fmt.Println()

	fmt.Println("=== 5. 拆成三维（预告，细节明天起逐维讲）===")
	fmt.Println()
	perm := []struct {
		scope   string
		values  string
		input   string
		example string
	}{
		{"module", "某面整体可见/可用", "homeos_family_module 表",
			"member 能看到财务面吗 → 查 FamilyModule"},
		{"data", "当前会话家庭 / 本账本 / 本人 / 指定成员", "token 里的 family_id",
			"李娜能看到谁的流水 → 数据范围过滤"},
		{"action", "read/create/update/delete/export/invite/admin", "角色矩阵",
			"李娜能导出 CSV 吗 → 查 action"},
	}
	for _, p := range perm {
		fmt.Printf("  scope=%-8s 取值：%s\n", p.scope, p.values)
		fmt.Printf("  %-16s 判定输入：%s\n", "", p.input)
		fmt.Printf("  %-16s 举例：%s\n", "", p.example)
	}
	fmt.Println()
	fmt.Println("  外加第四个正交维度 condition（不是 scope，是附加条件）：")
	conds := []struct{ kind, desc, example string }{
		{"时间窗", "访客有效期", "guest 的 expires_at 过了就拒"},
		{"字段", "L3 金额需二次确认", "view:finance 但 view:finance.amount 需确认"},
		{"对象归属", "author == me", "只有作者能改自己的私密流水"},
	}
	for _, c := range conds {
		fmt.Printf("    %-10s %-22s 例：%s\n", c.kind, c.desc, c.example)
	}
	fmt.Println()

	fmt.Println("=== 6. 判定顺序：四个 scope 不能并列 ===")
	fmt.Println("  新手最容易犯的错：把 module/data/action 写成三个并列的 if，")
	fmt.Println("  谁的答案是 true 就放行。这是**或**逻辑，会导致：")
	fmt.Println("    guest 的 module=通过（能看到财务面），于是放行他看明细 → 越权")
	fmt.Println("  正确是**与**逻辑，且有固定顺序：")
	fmt.Println()
	fmt.Println("    判定流程（tech-plan §8.2 的判定顺序）：")
	fmt.Println("      ① 显式拒绝        ← 有 deny 记录就直接拒，不看后面")
	fmt.Println("      ② 角色默认矩阵    ← role + action 的默认能力")
	fmt.Println("      ③ 家庭级覆盖      ← 家庭对这个成员的特殊设置（P1 不做，但位置留着）")
	fmt.Println("      ④ 对象级 ACL      ← 单个资源的特殊授权（P1 不做，规则引擎出生时才有）")
	fmt.Println()
	fmt.Println("  四个 scope 的关系是**串联的闸门**，不是并联的开关：")
	fmt.Println("    module 通过 AND data 通过 AND action 通过 AND condition 通过 = 放行")
	fmt.Println("  任一环拒绝就停在哪一环 —— 调试时你才知道是哪一层拦的。")
	fmt.Println()

	fmt.Println("=== 7. 一维 vs 三维：把今天的场景全跑一遍（真跑）===")
	fmt.Println()
	type probe struct {
		role  Role
		mod   bool // module 判定
		data  bool // data 判定
		act   bool // action 判定
		want  bool // 真实答案
		label string
	}
	probes := []probe{
		{RoleGuest, true, true, false, false, "guest 看财务面 → 只读，不能 create"},
		{RoleMember, true, true, true, true, "member 看自己流水并新建"},
		{RoleMember, true, true, true, false, "member 导出 CSV → 拒（action 不对）"},
		{RoleWard, false, false, false, false, "ward 进财务面 → module 就拒了"},
		{RoleOwner, true, true, true, true, "owner 一切放行"},
		{RoleOwner, true, true, false, false, "owner 但对象不属于本家庭 → data 拒"},
	}
	fmt.Printf("  %-9s %-7s %-7s %-7s %-9s %-9s %s\n", "角色", "module", "data", "action", "串联结果", "真实答案", "场景")
	for _, p := range probes {
		chained := p.mod && p.data && p.act
		mark := "✅"
		if chained != p.want {
			mark = "❌"
		}
		fmt.Printf("  %-9s %-7s %-7s %-7s %-9s %-9s %s\n",
			p.role.Label(), yn(p.mod), yn(p.data), yn(p.act), yn(chained), yn(p.want), p.label+mark)
	}
	fmt.Println()
	fmt.Println("  注意最后两行：owner 也会被拒 —— 只要对象不属于当前会话家庭。")
	fmt.Println("  「角色再高也不能跨家庭」是**串联**结构带来的，不是特判。")
	fmt.Println()

	fmt.Println("=== 8. 与 JS / 前端对比 ===")
	fmt.Println("  ① 前端天然倾向「一维」：一个 isVisible 布尔一路传下去。")
	fmt.Println("     React 里这样写非常自然：")
	fmt.Println("       const canSeeFinance = role === 'owner' || role === 'member'")
	fmt.Println("       {canSeeFinance && <FinanceNav />}")
	fmt.Println("     这是**体验层**的写法，没错。但它一维这件事本身会诱导你")
	fmt.Println("     在服务端也只写一维 —— 那就是漏洞。")
	fmt.Println("  ② 服务端必须至少二维（module × action），因为 handler 知道的是")
	fmt.Println("     「我要执行 read 动作」，而导航菜单知道的是「这个面可不可见」。")
	fmt.Println("     这两个是不同的入口，你不能用同一个 bool。")
	fmt.Println("  ③ JS 里多维判定通常写成对象或数组：")
	fmt.Println("       perm = { module: {...}, action: {...} }")
	fmt.Println("     Go 里对应 struct 或 map，但**判定函数应该是一个**能直接返回 bool 的，")
	fmt.Println("     不要让调用方自己拼多个判断（那样调用方一定会漏一个）。")
	fmt.Println("  ④ 最关键的对比：JS 判错了，最坏是 UI 显示错；Go 判错了，是数据泄露。")
	fmt.Println("     这就是为什么本阶段每一层都要有测试。")
	fmt.Println()

	fmt.Println("=== 9. 明天 ===")
	fmt.Println("  今天把问题拆成三维 + condition。明天起逐维落地：")
	fmt.Println("  · d8 scope=module —— 唯一输入是 homeos_family_module 表")
	fmt.Println("  · d9 scope=data —— 四个取值怎么落到 SQL 的 WHERE")
	fmt.Println("  · d10 scope=action —— 七个动作的完整清单")
	fmt.Println("  · d11 condition —— 时间窗/字段/对象归属")
	fmt.Println("  · d12 收口 —— 写成可测试的判定函数")
}

func yn(b bool) string {
	if b {
		return "✅"
	}
	return "❌"
}

func dashes(n int) string {
	s := make([]byte, n)
	for i := range s {
		s[i] = '-'
	}
	return string(s)
}

// =====================================================================
// W19 d8：scope = module —— 面级可见性，唯一输入是 homeos_family_module。
//
// 本机没有 Postgres。SQL 用 GORM DryRun **真实生成**（GORM 亲手构建，
// 不连库）；面的启用状态用内存 slice 模拟，判定逻辑真跑。
// 今天要讲透的纪律：FamilyModule 是唯一权威源，不能有第二个开关。
// =====================================================================

package main

import (
	"fmt"
	"strings"

	"gorm.io/driver/postgres"
	"gorm.io/gorm"
	"gorm.io/gorm/clause"
	"gorm.io/gorm/logger"
)

// ---- 面（module）的枚举：tech-plan 里的七类命名同源 ----
type ModuleCode string

const (
	ModFinance   ModuleCode = "finance"
	ModCalendar  ModuleCode = "calendar"
	ModMember    ModuleCode = "member"
	ModBudget    ModuleCode = "budget"
	ModAsset     ModuleCode = "asset"
	ModRecurring ModuleCode = "recurring"
)

var AllModules = []ModuleCode{ModFinance, ModCalendar, ModMember, ModBudget, ModAsset, ModRecurring}

// 两个系统级面：identity（登录/家庭）与 notification，**不写此表**
var SystemLevelModules = []ModuleCode{"identity", "notification"}

func (m ModuleCode) Label() string {
	switch m {
	case ModFinance:
		return "财务"
	case ModCalendar:
		return "日历"
	case ModMember:
		return "成员"
	case ModBudget:
		return "预算"
	case ModAsset:
		return "资产"
	case ModRecurring:
		return "周期记账"
	}
	return string(m)
}

// ---- homeos_family_module 的内存镜像 ----
type FamilyModule struct {
	FamilyID  string
	Code      ModuleCode
	Enabled   bool
	EnabledAt string
	EnabledBy string
}

// 两个家庭：fam-001 开了 4 个面，fam-002 只开了 1 个
var modules = []FamilyModule{
	{FamilyID: "fam-001", Code: ModFinance, Enabled: true, EnabledAt: "2026-09-01", EnabledBy: "m-zhangwei"},
	{FamilyID: "fam-001", Code: ModCalendar, Enabled: true, EnabledAt: "2026-09-01", EnabledBy: "m-zhangwei"},
	{FamilyID: "fam-001", Code: ModMember, Enabled: true, EnabledAt: "2026-09-01", EnabledBy: "m-zhangwei"},
	{FamilyID: "fam-001", Code: ModBudget, Enabled: true, EnabledAt: "2026-09-20", EnabledBy: "m-zhangwei"},
	// asset / recurring 无行 = 未启用（不是 enabled=false，是根本没有这行）
	{FamilyID: "fam-002", Code: ModCalendar, Enabled: true, EnabledAt: "2026-10-01", EnabledBy: "m-lina2"},
}

// ---- 判定：唯一输入是这张表 ----
func moduleEnabled(familyID string, code ModuleCode) (bool, string) {
	for _, m := range modules {
		if m.FamilyID == familyID && m.Code == code {
			if m.Enabled {
				return true, "有行且 enabled=true"
			}
			return false, "有行但 enabled=false（曾开启后被关掉）"
		}
	}
	return false, "**无行** = 未启用"
}

func enabledModules(familyID string) []ModuleCode {
	out := []ModuleCode{}
	for _, m := range AllModules {
		if ok, _ := moduleEnabled(familyID, m); ok {
			out = append(out, m)
		}
	}
	return out
}

// ---- 面级可见 = 家庭开了这个面（先过 module），再过角色 ----
// 顺序很重要：先 module 后 role。module 拒了就不用再看角色。
type ModDecision struct {
	Allow bool
	Why   string
}

func checkModule(familyID string, role string, code ModuleCode) ModDecision {
	for _, s := range SystemLevelModules {
		if code == ModuleCode(s) {
			return ModDecision{true, "系统级面：不进 FamilyModule，恒可见（但仍要过角色）"}
		}
	}
	ok, why := moduleEnabled(familyID, code)
	if !ok {
		return ModDecision{false, "面未启用（" + why + "）"}
	}
	// 角色层面：member 及以上都能看面；guest 只能看部分
	roleAllows := map[string][]ModuleCode{
		"owner":  AllModules,
		"member": {ModFinance, ModCalendar, ModMember, ModBudget, ModAsset, ModRecurring},
		"ward":   {ModCalendar, ModMember},
		"guest":  {ModFinance, ModCalendar, ModMember},
	}[role]
	allowed := false
	for _, m := range roleAllows {
		if m == code {
			allowed = true
		}
	}
	if !allowed {
		return ModDecision{false, fmt.Sprintf("面已启用，但角色 %s 无权进入该面", role)}
	}
	return ModDecision{true, "面已启用且角色可进入"}
}

func dryDB() *gorm.DB {
	db, err := gorm.Open(postgres.New(postgres.Config{
		DSN: "postgres://svc_homeos:dev_password@localhost:5432/homecube?sslmode=disable",
	}), &gorm.Config{
		DryRun: true, DisableAutomaticPing: true,
		Logger: logger.Default.LogMode(logger.Silent),
	})
	if err != nil {
		panic(err)
	}
	return db
}

type FamilyModuleRow struct {
	FamilyID  string         `gorm:"column:family_id;type:uuid;primaryKey" json:"family_id"`
	Code      ModuleCode     `gorm:"column:code;type:varchar(32);primaryKey" json:"code"`
	Enabled   bool           `gorm:"column:enabled;not null;default:false" json:"enabled"`
	EnabledAt *string        `gorm:"column:enabled_at" json:"enabled_at"`
	EnabledBy *string        `gorm:"column:enabled_by;type:uuid" json:"enabled_by"`
	Version   int            `gorm:"column:version;not null;default:1" json:"version"`
	DeletedAt gorm.DeletedAt `gorm:"column:deleted_at;index" json:"-"`
}

func (FamilyModuleRow) TableName() string { return "homeos_family_module" }

func flat(s string) string { return strings.Join(strings.Fields(s), " ") }

func main() {
	fmt.Println("=== 1. 面是什么：一个「侧边栏里的一页」 ===")
	fmt.Println("  HomeCube 的侧边栏有 6 个业务面（tech-plan 的分包与路由同源）：")
	for i, m := range AllModules {
		fmt.Printf("    %d. %-10s /api/homeos/%-10s  「%s」\n", i+1, m, m, m.Label())
	}
	fmt.Println()
	fmt.Println("  另有 2 个系统级面，**不写 FamilyModule 表**：")
	fmt.Println("    identity      登录、注册、切家庭")
	fmt.Println("    notification  通知列表、未读红点")
	fmt.Println("  原因：这两个面在「还没选家庭」的时候就要能用，")
	fmt.Println("        而 FamilyModule 是按 family_id 组织的，没有家庭就没有行。")
	fmt.Println("        所以它们是**系统级**，不参与面级判定。")
	fmt.Println()

	fmt.Println("=== 2. 唯一权威源：homeos_family_module ===")
	fmt.Println("  tech-plan §5.2 原文：")
	fmt.Println("    「本家庭启用哪些面的**唯一权威源**。UNIQUE(family_id, code)。")
	fmt.Println("      **无行即未启用**。两个系统级面不写此表」")
	fmt.Println()
	fmt.Println("  DDL：")
	fmt.Println("    CREATE TABLE homeos_family_module (")
	fmt.Println("        family_id  UUID        NOT NULL,")
	fmt.Println("        code       VARCHAR(32) NOT NULL,")
	fmt.Println("        enabled    BOOLEAN     NOT NULL DEFAULT false,")
	fmt.Println("        enabled_at TIMESTAMPTZ NULL,")
	fmt.Println("        enabled_by UUID        NULL,")
	fmt.Println("        version    INTEGER     NOT NULL DEFAULT 1,")
	fmt.Println("        deleted_at TIMESTAMPTZ,")
	fmt.Println("        PRIMARY KEY (family_id, code),")
	fmt.Println("        CONSTRAINT homeos_family_module_code_check")
	fmt.Println("            CHECK (code IN ('finance','calendar','member','budget','asset','recurring'))")
	fmt.Println("    );")
	fmt.Println()
	fmt.Println("  两个设计要点：")
	fmt.Println("  ① PRIMARY KEY (family_id, code) 而不是自增 id + UNIQUE。")
	fmt.Println("     前者天然防重复，插入重复面直接报主键冲突，不需要额外查重。")
	fmt.Println("  ② **无行即未启用**，所以「关闭一个面」有两种做法：")
	fmt.Println("     · 改 enabled=false（保留历史：曾开过、什么时候关的、谁关的）")
	fmt.Println("     · 删掉这行（丢掉历史）")
	fmt.Println("     本项目用前者，因为 enabled_at/enabled_by 有审计价值。")
	fmt.Println("     于是判定函数必须处理三种状态：有行+true / 有行+false / 无行。")
	fmt.Println()

	fmt.Println("=== 3. 当前两个家庭的启用情况（真跑判定）===")
	for _, fam := range []struct{ id, name string }{{"fam-001", "张伟家"}, {"fam-002", "李娜家"}} {
		fmt.Printf("  %s（%s）已启用的面：", fam.id, fam.name)
		list := enabledModules(fam.id)
		if len(list) == 0 {
			fmt.Println("（无）")
		}
		for _, m := range list {
			fmt.Printf(" %s", m.Label())
		}
		fmt.Println()
		fmt.Printf("    未启用的面：")
		for _, m := range AllModules {
			if ok, _ := moduleEnabled(fam.id, m); !ok {
				fmt.Printf(" %s", m.Label())
			}
		}
		fmt.Println()
	}
	fmt.Println()
	fmt.Println("  注意 fam-001 的「资产」和「周期记账」：**根本没有行**。")
	fmt.Println("  这是「未启用」和「启用但关了」的区分 —— 前者没有历史，后者有。")
	fmt.Println()

	fmt.Println("=== 4. 判定顺序：先 module，后 role ===")
	fmt.Println("  为什么是这个顺序？两个原因：")
	fmt.Println("  ① 性能：module 判定只需要 FamilyModule（一个小表，且带 family_id 前缀）")
	fmt.Println("  ② 语义：「这个面没开」比「你没权限」更基础 ——")
	fmt.Println("     一个面都没开的时候，讨论角色是没意义的。")
	fmt.Println()
	probes := []struct {
		fam, role string
		code      ModuleCode
		note      string
	}{
		{"fam-001", "owner", ModFinance, "开着 + 管理员"},
		{"fam-001", "member", ModFinance, "开着 + 成人成员"},
		{"fam-001", "ward", ModFinance, "开着，但 ward 进不去财务面"},
		{"fam-001", "guest", ModFinance, "开着 + 访客能进（只读）"},
		{"fam-001", "member", ModAsset, "**没开** → module 就拒了"},
		{"fam-001", "ward", ModCalendar, "开着 + ward 可进日历"},
		{"fam-002", "member", ModFinance, "没开 → module 拒"},
		{"fam-002", "owner", ModBudget, "没开 → module 拒"},
		{"fam-001", "guest", "identity", "系统级面，恒可见"},
	}
	fmt.Printf("  %-9s %-8s %-11s %-6s %s\n", "家庭", "角色", "面", "结果", "理由")
	for _, p := range probes {
		d := checkModule(p.fam, p.role, p.code)
		fmt.Printf("  %-9s %-8s %-11s %-6s %s\n", p.fam, p.role, string(p.code), yn(d.Allow), d.Why)
	}
	fmt.Println()
	fmt.Println("  第三行值得看：财务面**是开着的**，module 判定通过，")
	fmt.Println("  但 ward 被角色判定挡住。如果顺序反过来（先 role 后 module），")
	fmt.Println("  拒绝理由会变成「角色不允许」，排查时会被误导去查角色表。")
	fmt.Println("  → 顺序不只是性能，它是**错误信息的质量**。")
	fmt.Println()

	fmt.Println("=== 5. DryRun：真实生成的 SQL ===")
	db := dryDB()
	fmt.Println("  ① 列出这个家庭启用了哪些面（首页导航用）")
	st := db.Session(&gorm.Session{DryRun: true}).
		Where("family_id = ? AND enabled = ?", "fam-001", true).
		Order("code asc").
		Find(&[]FamilyModuleRow{})
	fmt.Printf("     %s\n", flat(st.Statement.SQL.String()))
	fmt.Printf("     Vars: %v\n", st.Statement.Vars)
	fmt.Println()
	fmt.Println("  ② 判定单个面（前端点了某个面的入口，服务端再确认一次）")
	st = db.Session(&gorm.Session{DryRun: true}).
		Where("family_id = ? AND code = ?", "fam-001", "finance").
		First(&FamilyModuleRow{})
	fmt.Printf("     %s\n", flat(st.Statement.SQL.String()))
	fmt.Println()
	fmt.Println("  ③ 开启一个面（幂等：ON CONFLICT DO UPDATE）")
	fmt.Printf("     %s\n", flat(db.ToSQL(func(tx *gorm.DB) *gorm.DB {
		return tx.Clauses(onConflict()).Create(&FamilyModuleRow{
			FamilyID: "fam-001", Code: ModAsset, Enabled: true,
			EnabledAt: ptr("2026-10-15 09:00:00"), EnabledBy: ptr("m-zhangwei"), Version: 1,
		})
	})))
	fmt.Println()
	fmt.Println("  注意 ③ 里的 `ON CONFLICT (family_id, code) DO UPDATE`：")
	fmt.Println("  没有它，同一个面被「开启」两次会报主键冲突（500）。")
	fmt.Println("  有它就是 upsert，重试安全。")
	fmt.Println()

	fmt.Println("=== 6. 纪律：不能有第二个面级开关 ===")
	fmt.Println("  错误做法 A：在 homeos_family.feature_flags 里加 \"finance\": true")
	fmt.Println("    → 于是两个地方都能说「财务面开没开」，")
	fmt.Println("      而它们**会不一致**：feature_flags 说开着、FamilyModule 没这行。")
	fmt.Println()
	fmt.Println("  错误做法 B：给每个面加一个 users 表的字段")
	fmt.Println("    → 「张伟看不到资产面，李娜看得到」——")
	fmt.Println("      这是**角色/成员级**的差异，不是家庭级的，")
	fmt.Println("      放进 FamilyModule 就是把两个粒度混在一张表。")
	fmt.Println()
	fmt.Println("  错误做法 C：把 enabled 放全局（不分家庭）")
	fmt.Println("    → 多租户直接崩：family-002 会看到 family-001 的设置。")
	fmt.Println()
	fmt.Println("  正确做法：")
	fmt.Println("    FamilyModule      = 这个**家庭**开了哪些面（唯一权威源）")
	fmt.Println("    角色默认矩阵       = 这个**角色**能进哪些面（d02 的 Caps）")
	fmt.Println("    两者的交集 = 最终可见面")
	fmt.Println("    两者都**不需要**第三个存储。")
	fmt.Println()
	fmt.Println("  顺带说清 feature_flags 该放什么：")
	fmt.Println("    feature_flags 只放**非面开关**的东西，比如：")
	fmt.Println("      { \"ai_category\": false, \"strict_mode\": true, \"beta_report\": false }")
	fmt.Println("    判据很简单：**如果这个开关控制的是「侧边栏里有没有这一页」，")
	fmt.Println("    它就必须去 FamilyModule，绝不能进 feature_flags。**")
	fmt.Println("    （这一点 d16 会专门讲透，因为它是最容易被违反的一条。）")
	fmt.Println()

	fmt.Println("=== 7. 模块可见面列表 = 首页聚合的一部分 ===")
	fmt.Println("  tech-plan §6.5：首页是**单请求** GET /api/homeos/home/summary，")
	fmt.Println("  「首页四区 + 未读红点 + **面矩阵**全部由它带出」。")
	fmt.Println("  所以面矩阵的形状必须是：")
	fmt.Println()
	for _, r := range []string{"owner", "member", "ward", "guest"} {
		var vis []string
		for _, m := range AllModules {
			if d := checkModule("fam-001", r, m); d.Allow {
				vis = append(vis, string(m))
			}
		}
		fmt.Printf("    %-8s visible_modules: [%s]\n", r, strings.Join(vis, ", "))
	}
	fmt.Println()
	fmt.Println("  服务端算好再给前端，而不是让前端拿 enabled 自己过滤。")
	fmt.Println("  两个原因：")
	fmt.Println("  ① 前端没有权威数据，缓存的 feature 可能是旧的")
	fmt.Println("  ② 前端过滤是体验，服务端判定才是安全 —— 两者都要有，但职责不同")
	fmt.Println("  （呼应 d07：JS 判错了最坏是 UI 显示错，Go 判错了是数据泄露）")
	fmt.Println()

	fmt.Println("=== 8. 与 JS / 前端对比 ===")
	fmt.Println("  ① 前端怎么表达「面没开」？最自然是 URL 路由不注册：")
	fmt.Println("       const routes = [")
	fmt.Println("         { path: '/finance', element: <Finance /> },")
	fmt.Println("         // asset 面没开 → 这条路由不生成")
	fmt.Println("       ]")
	fmt.Println("     这个做法本身没错，但**它只能是体验层**。")
	fmt.Println("     攻击者直接 curl /api/finance/accounts 照样通 ——")
	fmt.Println("     因为前端路由压根不在请求路径上。")
	fmt.Println("  ② TypeScript 里怎么表达「面」？")
	fmt.Println("       type ModuleCode = 'finance' | 'calendar' | ...")
	fmt.Println("     Go 侧是 `type ModuleCode string` + 常量，一一对应（铁律 10：七类命名同源）。")
	fmt.Println("  ③ 状态查询的坑：前端常见错误是")
	fmt.Println("       const isOpen = !!family.feature_flags.finance")
	fmt.Println("     这读的是**错误的源**。正确读法是从 summary 响应的 visible_modules 里读，")
	fmt.Println("     因为那是服务端判定后的结果（module ∩ role），不是一个原始开关。")
	fmt.Println("  ④ Go 侧容易踩的坑：把「无行」当成 false 是对的，")
	fmt.Println("     但如果有人写成「查不到就返回 true」，整个模块判定就反了。")
	fmt.Println("     永远 fail closed。")
	fmt.Println()

	fmt.Println("=== 9. 明天 ===")
	fmt.Println("  今天 module 维讲完：判定输入只有 FamilyModule 一张表。")
	fmt.Println("  明天讲 scope=data —— 它回答的是「在这个面里，我能看到**哪些行**」。")
	fmt.Println("  四个取值：当前会话家庭 / 本账本 / 本人 / 指定成员。")
	fmt.Println("  关键：**family_id 从 token 取，不从请求参数取**。")
}

func ptr(s string) *string { return &s }

func onConflict() clause.OnConflict {
	return clause.OnConflict{
		Columns: []clause.Column{{Name: "family_id"}, {Name: "code"}},
		DoUpdates: clause.Assignments(map[string]interface{}{
			"enabled": gorm.Expr("excluded.enabled"),
			"version": gorm.Expr("homeos_family_module.version + 1"),
		}),
	}
}

func yn(b bool) string {
	if b {
		return "✅"
	}
	return "❌"
}

// =====================================================================
// W19 d9：scope = data —— 四个取值怎么落到 SQL 的 WHERE。
//
// 本机没有 Postgres。SQL 用 GORM DryRun **真实生成**；内存 slice 模拟表。
// 今天最重要的两个点：
//   ① 四个取值的语义与 WHERE 形状一一对应
//   ② family_id **只能从 token 取**，绝不能从请求参数取
// =====================================================================

package main

import (
	"fmt"
	"strings"

	"gorm.io/driver/postgres"
	"gorm.io/gorm"
	"gorm.io/gorm/logger"
)

type Txn struct {
	ID          string         `gorm:"column:id;type:uuid;primaryKey"`
	FamilyID    string         `gorm:"column:family_id;type:uuid;not null;index"`
	MemberID    string         `gorm:"column:member_id;type:uuid;not null"`
	LedgerID    string         `gorm:"column:ledger_id;type:uuid"`
	AmountCents int64          `gorm:"column:amount_cents;not null"`
	IsPrivate   bool           `gorm:"column:is_private;not null;default:false"`
	Note        string         `gorm:"column:note;type:varchar(200)"`
	Version     int            `gorm:"column:version;not null;default:1"`
	DeletedAt   gorm.DeletedAt `gorm:"column:deleted_at;index"`
}

func (Txn) TableName() string { return "finance_transaction" }

var txns = []Txn{
	{ID: "txn-01", FamilyID: "fam-001", MemberID: "m-zhangwei", LedgerID: "led-daily", AmountCents: 480000, Note: "房贷"},
	{ID: "txn-02", FamilyID: "fam-001", MemberID: "m-lina", LedgerID: "led-daily", AmountCents: 12800, Note: "超市买菜"},
	{ID: "txn-03", FamilyID: "fam-001", MemberID: "m-zhangwei", LedgerID: "led-daily", AmountCents: 65000, IsPrivate: true, Note: "年终奖入账"},
	{ID: "txn-04", FamilyID: "fam-001", MemberID: "m-xiaoman", LedgerID: "led-kid", AmountCents: 240000, Note: "补习班"},
	{ID: "txn-05", FamilyID: "fam-001", MemberID: "m-lina", LedgerID: "led-kid", AmountCents: 5900, Note: "绘本"},
	{ID: "txn-06", FamilyID: "fam-002", MemberID: "m-lina2", LedgerID: "led-daily", AmountCents: 99900, Note: "别人的账"},
	{ID: "txn-07", FamilyID: "fam-002", MemberID: "m-zhangwei2", LedgerID: "led-daily", AmountCents: 88800, Note: "也别人的"},
}

// ---- scope=data 的四个取值 ----
type DataScope string

const (
	ScopeSessionFamily DataScope = "session_family" // 当前会话家庭
	ScopeThisLedger    DataScope = "this_ledger"    // 本账本
	ScopeSelf          DataScope = "self"           // 本人
	ScopeNamedMember   DataScope = "named_member"   // 指定成员
)

var AllDataScopes = []DataScope{ScopeSessionFamily, ScopeThisLedger, ScopeSelf, ScopeNamedMember}

func (s DataScope) Label() string {
	switch s {
	case ScopeSessionFamily:
		return "当前会话家庭"
	case ScopeThisLedger:
		return "本账本"
	case ScopeSelf:
		return "本人"
	case ScopeNamedMember:
		return "指定成员"
	}
	return "?"
}

func (s DataScope) WhereShape() string {
	switch s {
	case ScopeSessionFamily:
		return "family_id = ?"
	case ScopeThisLedger:
		return "family_id = ? AND ledger_id = ?"
	case ScopeSelf:
		return "family_id = ? AND member_id = ?"
	case ScopeNamedMember:
		return "family_id = ? AND member_id = ?  -- member_id 来自 URL/body"
	}
	return "?"
}

// ---- 会话：family_id 只能从这里来 ----
type Session struct {
	UserID    string
	MemberID  string
	FamilyID  string // ★ 唯一来源
	Role      string
	CanSeeAll bool // owner / member 能看全家；guest 不能看私密
}

// dataScopeFilter 构造内存过滤条件，模拟 WHERE 的效果
func dataScopeFilter(s Session, scope DataScope, arg string) ([]Txn, string) {
	out := []Txn{}
	for _, t := range txns {
		// ★ 第一层无条件：family_id 隔离。任何 scope 都要带它。
		if t.FamilyID != s.FamilyID {
			continue
		}
		switch scope {
		case ScopeSessionFamily, ScopeThisLedger:
			if scope == ScopeThisLedger && t.LedgerID != arg {
				continue
			}
		case ScopeSelf, ScopeNamedMember:
			if t.MemberID != arg {
				continue
			}
		}
		out = append(out, t)
	}
	why := ""
	switch scope {
	case ScopeSessionFamily:
		why = "family_id = 会话里的 fam（不读任何请求参数）"
	case ScopeThisLedger:
		why = "family_id + ledger_id（ledger 来自 URL，但**必须先校验 ledger 属于本家庭**）"
	case ScopeSelf:
		why = "family_id + member_id = 会话里的 mid（不读 body 的 member_id）"
	case ScopeNamedMember:
		why = "family_id + member_id（member_id 来自请求，**必须再查一次它是否属于本家庭**）"
	}
	return out, why
}

func dryDB() *gorm.DB {
	db, err := gorm.Open(postgres.New(postgres.Config{
		DSN: "postgres://svc_finance:dev_password@localhost:5432/homecube?sslmode=disable",
	}), &gorm.Config{
		DryRun: true, DisableAutomaticPing: true,
		Logger: logger.Default.LogMode(logger.Silent),
	})
	if err != nil {
		panic(err)
	}
	return db
}

func flat(s string) string { return strings.Join(strings.Fields(s), " ") }

func main() {
	fmt.Println("=== 1. 四个取值：它们回答的是「哪些行」 ===")
	fmt.Println("  tech-plan §8.2：scope=data 的判定输入是 **token 内的 family_id**。")
	fmt.Println()
	for i, s := range AllDataScopes {
		fmt.Printf("  %d. %-16s %s\n", i+1, s, s.Label())
		fmt.Printf("     WHERE 形状： %s\n", s.WhereShape())
	}
	fmt.Println()
	fmt.Println("  四个取值不是四种「权限等级」，而是四种**过滤条件**。")
	fmt.Println("  它们的共同点是：每一个都**必须**包含 family_id = 会话家庭。")
	fmt.Println("  这就是多租户隔离在 data 维的具体形态。")
	fmt.Println()

	fmt.Println("=== 2. 当前内存表里的数据（两个家庭，7 条流水）===")
	fmt.Printf("  %-8s %-9s %-12s %-10s %-8s %s\n", "id", "family", "member", "ledger", "private", "note")
	for _, t := range txns {
		priv := ""
		if t.IsPrivate {
			priv = "🔒"
		}
		fmt.Printf("  %-8s %-9s %-12s %-10s %-8s %s\n", t.ID, t.FamilyID, t.MemberID, t.LedgerID, priv, t.Note)
	}
	fmt.Println()

	sess := Session{UserID: "u-1002", MemberID: "m-lina", FamilyID: "fam-001", Role: "member", CanSeeAll: true}
	fmt.Println("=== 3. 李娜的会话（fam-001 / m-lina / member）逐个 scope 跑一遍 ===")
	fmt.Println()
	fmt.Printf("  会话：user=%s member=%s family=%s role=%s\n\n",
		sess.UserID, sess.MemberID, sess.FamilyID, sess.Role)

	type probe struct {
		scope DataScope
		arg   string
		note  string
	}
	probes := []probe{
		{ScopeSessionFamily, "", "不带参数"},
		{ScopeThisLedger, "led-daily", "URL 里 ?ledger_id=led-daily"},
		{ScopeThisLedger, "led-kid", "URL 里 ?ledger_id=led-kid"},
		{ScopeSelf, "m-lina", "只看自己（不传参，用会话 mid）"},
		{ScopeNamedMember, "m-xiaoman", "URL 里 ?member_id=m-xiaoman"},
		{ScopeNamedMember, "m-lina2", "URL 里 ?member_id=m-lina2（**别家的人**）"},
	}
	for _, p := range probes {
		rows, why := dataScopeFilter(sess, p.scope, p.arg)
		arg := p.arg
		if arg == "" {
			arg = "（无）"
		}
		fmt.Printf("  scope=%-16s arg=%-14s → %d 条\n", p.scope, arg, len(rows))
		for _, r := range rows {
			priv := ""
			if r.IsPrivate {
				priv = " 🔒私密"
			}
			fmt.Printf("      %-8s %-10s %s%s\n", r.ID, yuan(r.AmountCents), r.Note, priv)
		}
		fmt.Printf("      条件：%s\n", why)
		fmt.Println()
	}
	fmt.Println("  最后两组是今天的关键对比：")
	fmt.Println("    ScopeSelf + m-lina        → 2 条（她自己的）")
	fmt.Println("    ScopeNamedMember + m-lina2 → **0 条**，因为 m-lina2 不在 fam-001。")
	fmt.Println("  这就是「指定成员」这一档的必答题：**参数里的 member_id 要再校验一次归属**。")
	fmt.Println("  只写 `WHERE member_id = ?` 不带 family_id，就是 S3 d19 那个 43% 泄露的原型。")
	fmt.Println()

	fmt.Println("=== 4. 四档的 WHERE 与 SQL（DryRun 真实生成）===")
	db := dryDB()
	for _, c := range []struct {
		label string
		build func() *gorm.DB
		vars  []interface{}
	}{
		{"当前会话家庭", func() *gorm.DB {
			return db.Session(&gorm.Session{DryRun: true}).
				Where("family_id = ?", sess.FamilyID)
		}, nil},
		{"本账本", func() *gorm.DB {
			return db.Session(&gorm.Session{DryRun: true}).
				Where("family_id = ? AND ledger_id = ?", sess.FamilyID, "led-daily")
		}, nil},
		{"本人", func() *gorm.DB {
			return db.Session(&gorm.Session{DryRun: true}).
				Where("family_id = ? AND member_id = ?", sess.FamilyID, sess.MemberID)
		}, nil},
		{"指定成员（危险版：漏 family_id）", func() *gorm.DB {
			return db.Session(&gorm.Session{DryRun: true}).
				Where("member_id = ?", "m-xiaoman")
		}, nil},
	} {
		st := c.build().Find(&[]Txn{})
		fmt.Printf("  %s\n", c.label)
		fmt.Printf("     %s\n", flat(st.Statement.SQL.String()))
		fmt.Printf("     Vars: %v\n", st.Statement.Vars)
	}
	fmt.Println()
	fmt.Println("  最后一条是**反面教材**：它只有 member_id，没有 family_id。")
