	fmt.Println("    · review：grep 得到每一个 store 方法，参数一样")
	fmt.Println("    · 测试：测试也必须构造 session，忘了就是 nil panic 而不是静默全通过")
	fmt.Println()

	fmt.Println("=== 6. 「指定成员」这一档要多一次校验 ===")
	fmt.Println("  ScopeNamedMember 的 member_id 来自客户端（URL 或 body），")
	fmt.Println("  所以它**不能**直接进 WHERE，必须先过一道：")
	fmt.Println()
	fmt.Println("    // 第一步：这个 member 是否属于当前会话家庭？")
	fmt.Println("    var m Member")
	fmt.Println("    err := db.Where(\"id = ? AND family_id = ?\", req.MemberID, session.FamilyID).First(&m).Error")
	fmt.Println("    if errors.Is(err, gorm.ErrRecordNotFound) {")
	fmt.Println("        return ErrNotFound   // ← 404，不是 403（d21 讲）")
	fmt.Println("    }")
	fmt.Println("    // 第二步：确认存在且属于本家庭后，才进 WHERE")
