// yuan 把「分」渲染成「元」。金额一律 *_cents BIGINT，禁浮点（铁律 1），
// 所以这里是整数除法 + 取余，不做任何 float 运算。
func yuan(c int64) string {
	return fmt.Sprintf("%d.%02d 元", c/100, c%100)
}

// =====================================================================
// W19 d10：scope = action —— 七个动作的完整清单与判定。
//
// 本机没有 Postgres。角色矩阵用内存结构模拟，判定函数真跑。
// 七个动作：read / create / update / delete / export / invite / admin
// 关键点：后三个（export / invite / admin）不是普通数据操作，
// 它们有独立的安全含义，不能当 read 的子选项。
// =====================================================================

package main

import (
	"fmt"
	"strings"
)

type Action string

const (
	ActRead   Action = "read"
	ActCreate Action = "create"
	ActUpdate Action = "update"
	ActDelete Action = "delete"
	ActExport Action = "export"
	ActInvite Action = "invite"
	ActAdmin  Action = "admin"
)

var AllActions = []Action{ActRead, ActCreate, ActUpdate, ActDelete, ActExport, ActInvite, ActAdmin}

func (a Action) Label() string {
	m := map[Action]string{
		ActRead: "读", ActCreate: "新建", ActUpdate: "改", ActDelete: "删",
		ActExport: "导出", ActInvite: "邀请", ActAdmin: "管理成员",
	}
	return m[a]
}

// ---- 动作的三个分组：语义不同，判定也不同 ----
// 数据动作（data actions）: read/create/update/delete —— 改的是业务数据
// 外发动作（egress）: export —— 把数据带出系统，撤销后收不回来
// 构变动作（composition）: invite/admin —— 改变家庭的成员构成
var dataActions = []Action{ActRead, ActCreate, ActUpdate, ActDelete}
var egressActions = []Action{ActExport}
var compositionActions = []Action{ActInvite, ActAdmin}

func group(a Action) string {
	for _, x := range dataActions {
		if x == a {
			return "数据"
		}
	}
	for _, x := range egressActions {
		if x == a {
			return "外发"
		}
	}
	for _, x := range compositionActions {
		if x == a {
			return "构变"
		}
	}
	return "?"
}

type Role string

const (
	RoleOwner  Role = "owner"
	RoleMember Role = "member"
	RoleWard   Role = "ward"
	RoleGuest  Role = "guest"
)

func (r Role) Label() string {
	switch r {
	case RoleOwner:
		return "owner"
	case RoleMember:
		return "member"
	case RoleWard:
		return "ward"
	case RoleGuest:
		return "guest"
	}
	return "unknown"
}

// ---- 默认矩阵：role × action → 三种结果 ----
// A = 全部对象；M = 仅自己的；R = 只读；— = 无权限
type Grant string

const (
	GrantAll  Grant = "A"
	GrantMine Grant = "M"
	GrantRead Grant = "R"
	GrantNone Grant = "—"
)

func defaultGrant(role Role, act Action) Grant {
	// key = "role:action"
	m := map[string]Grant{
		"owner:read": GrantAll, "owner:create": GrantAll, "owner:update": GrantAll,
		"owner:delete": GrantAll, "owner:export": GrantAll, "owner:invite": GrantAll,
		"owner:admin": GrantAll,

		"member:read": GrantAll, "member:create": GrantAll, "member:update": GrantMine,
		"member:delete": GrantMine, "member:export": GrantNone, "member:invite": GrantNone,
		"member:admin": GrantNone,

		"ward:read": GrantRead, "ward:create": GrantNone, "ward:update": GrantMine,
		"ward:delete": GrantNone, "ward:export": GrantNone, "ward:invite": GrantNone,
		"ward:admin": GrantNone,

		"guest:read": GrantRead, "guest:create": GrantNone, "guest:update": GrantNone,
		"guest:delete": GrantNone, "guest:export": GrantNone, "guest:invite": GrantNone,
		"guest:admin": GrantNone,
	}
	return m[string(role)+":"+string(act)]
}

// grantAllows 判断 action 在给定 grant 下能不能作用于某个对象
func grantAllows(g Grant, isOwnerOfObject bool) bool {
	switch g {
	case GrantAll:
		return true
	case GrantMine:
		return isOwnerOfObject
	case GrantRead:
		return false // 只读：任何写动作都不行
	case GrantNone:
		return false
	}
	return false
}

type ActionDecision struct {
	Allow bool
	Why   string
}

// checkAction 是唯一入口：默认矩阵 + 对象归属 + 只读动作不可写
func checkAction(role Role, act Action, isOwnerOfObject bool, isWriteAction bool) ActionDecision {
	g := defaultGrant(role, act)
	if g == GrantNone {
		return ActionDecision{false, fmt.Sprintf("矩阵里 %s 对 %s 是「—」", role.Label(), act.Label())}
	}
	if isWriteAction && g == GrantRead {
		return ActionDecision{false, fmt.Sprintf("%s 对 %s 是「R 只读」，写动作一律拒", role.Label(), act.Label())}
	}
	if g == GrantMine && !isOwnerOfObject {
		return ActionDecision{false, "矩阵是「M 仅自己的」，但这个对象不属于我"}
	}
	if g == GrantMine && isOwnerOfObject {
		return ActionDecision{true, "对象是我自己的，放行"}
	}
	return ActionDecision{true, fmt.Sprintf("矩阵是「%s」，放行", string(g))}
}

