func meaning(a Action) string {
	m := map[Action]string{
		ActRead:   "读取列表或单个对象",
		ActCreate: "新建一个对象",
		ActUpdate: "修改已存在的对象",
		ActDelete: "删除对象（业务上多为软删）",
		ActExport: "把数据导出成文件带出系统",
		ActInvite: "邀请新成员加入家庭",
		ActAdmin:  "改成员的角色或移除成员",
	}
	return m[a]
}

func mappingHTTP(a Action) string {
	m := map[Action]string{
		ActRead: "GET", ActCreate: "POST", ActUpdate: "PATCH",
		ActDelete: "DELETE", ActExport: "POST", ActInvite: "POST", ActAdmin: "PATCH",
	}
	return m[a]
}

func yn(b bool) string {
	if b {
		return "✅"
	}
	return "❌"
}

func line(n int) string {
	return strings.Repeat("─", n)
}

// =====================================================================
// W19 d11：condition —— 时间窗、字段、对象归属。
//
// 本机没有 Postgres。数据用内存结构模拟，condition 判定真跑。
// condition 不是第四个 scope，而是**叠加在三维之上的限制**。
// 今天要讲清：为什么矩阵给出「可以」之后，condition 还能把它变成「不行」。
// =====================================================================

package main

import (
	"fmt"
	"strings"
	"time"
)

// 固定「现在」，保证输出确定
var now = time.Date(2026, 10, 15, 9, 0, 0, 0, time.UTC)

type Role string

const (
	RoleOwner  Role = "owner"
	RoleMember Role = "member"
	RoleWard   Role = "ward"
	RoleGuest  Role = "guest"
)

// ---- 对象 ----
type Txn struct {
	ID          string
	FamilyID    string
	AuthorID    string // 谁记的（member.id）
	AmountCents int64
	IsPrivate   bool
	Field       string // L3：金额属于 L3 级敏感字段
	CreatedAt   time.Time
}

// ---- 三类 condition ----

// (1) 时间窗：访客有效期
type TimeWindow struct {
	ExpiresAt time.Time
	RevokedAt *time.Time
}

func (w TimeWindow) Allow(at time.Time) (bool, string) {
	if w.RevokedAt != nil {
		return false, fmt.Sprintf("时间窗：邀请已于 %s 被撤销", w.RevokedAt.Format("2006-01-02"))
	}
	if !at.Before(w.ExpiresAt) {
		return false, fmt.Sprintf("时间窗：已于 %s 到期（当前 %s）",
			w.ExpiresAt.Format("2006-01-02"), at.Format("2006-01-02"))
	}
	return true, fmt.Sprintf("时间窗：有效，剩余 %d 天",
		int(w.ExpiresAt.Sub(at).Hours()/24))
}

// (2) 字段级：L3 金额需二次确认
//
//	不返回 bool，而返回一个「可见性等级」——因为有第三态。
type FieldVisibility string

const (
	FieldHidden  FieldVisibility = "hidden"  // 完全不给
	FieldMasked  FieldVisibility = "masked"  // 给个大概值（看得到存在，看不到金额）
	FieldVisible FieldVisibility = "visible" // 明文
	FieldConfirm FieldVisibility = "confirm" // 可见，但必须二次确认（写审计）
	FieldDenied  FieldVisibility = "denied"  // 可见但点击要理由，且记审计
)

type FieldRule struct {
	Level FieldVisibility
	Why   string
}

// 字段级判定：不是简单的「能看/不能看」
func fieldVisibility(role Role, targetAuthorID, meID string, isL3 bool, hasConfirmed bool) FieldRule {
	if role == RoleOwner {
		if isL3 && !hasConfirmed {
			return FieldRule{FieldConfirm, "owner 看 L3 金额需二次确认（写审计）"}
		}
		return FieldRule{FieldVisible, "owner 全字段明文"}
	}
	if role == RoleMember || role == RoleGuest {
		if isL3 {
			return FieldRule{FieldMasked, "L3 字段对非 owner 返回掩码，不返回精确金额"}
		}
		if targetAuthorID == meID {
			return FieldRule{FieldVisible, "自己的非 L3 字段：明文"}
		}
		return FieldRule{FieldVisible, "他人的非 L3 字段：明文（L2）"}
	}
	if role == RoleWard {
		return FieldRule{FieldHidden, "ward 不接触金额"}
	}
	return FieldRule{FieldHidden, "未知角色 fail closed"}
}

// (3) 对象归属：author == me
func ownership(authorID, meID string, isPrivate bool, role Role) (bool, string) {
	if !isPrivate {
		// 非私密：全家可读，归属判定不适用
		return true, "非私密流水：归属判定不适用"
	}
	if authorID == meID {
		return true, "私密流水但作者是我：可读"
	}
	if role == RoleOwner {
		return true, "私密流水，作者不是我，但我是 owner：可读（管理员例外）"
	}
	return false, "私密流水，作者既不是我也不是 owner：不可读"
}

type Subject struct {
	Role    Role
	MeID    string
	Guest   *TimeWindow
	Confirm bool // 本次请求是否已完成 L3 二次确认
}

// 全量判定：三维 + condition 串联
type Result struct {
	Allow bool
	Trace []string
}

func decide(t Txn, s Subject, at time.Time, act string) Result {
	r := Result{}
	add := func(f string, a ...interface{}) { r.Trace = append(r.Trace, fmt.Sprintf(f, a...)) }

	// ① module（这里已省略 d08 的面级判定，简化为已通过）
	add("[module] 面已启用（finance），通过")

	// ② data：family_id 隔离
	if t.FamilyID != "fam-001" {
		add("[data] family_id 不匹配：拒")
		return Result{false, r.Trace}
	}
	add("[data] family_id 匹配 fam-001，通过")

	// ③ action
	add("[action] 动作 %s，矩阵允许（owner=A）", act)

	// ④ condition：时间窗（只对 guest 生效）
	if s.Guest != nil {
		if ok, why := s.Guest.Allow(at); !ok {
			add("[cond/time] %s → 拒", why)
			return Result{false, r.Trace}
		} else {
			add("[cond/time] %s", why)
		}
	}

	// ④ condition：字段级
	fv := fieldVisibility(s.Role, t.AuthorID, s.MeID, t.Field == "L3", s.Confirm)
	add("[cond/field] 字段等级 %s：%s", fv.Level, fv.Why)
	if fv.Level == FieldHidden {
		return Result{false, r.Trace}
	}

	// ④ condition：对象归属
	if ok, why := ownership(t.AuthorID, s.MeID, t.IsPrivate, s.Role); !ok {
		add("[cond/own] %s → 拒", why)
		return Result{false, r.Trace}
	} else {
		add("[cond/own] %s", why)
	}

	r.Allow = true
	add("→ 放行")
	return r
}

