		{true, "m-zhangwei", "m-lina", RoleMember},
		{true, "m-lina", "m-zhangwei", RoleOwner},
		{true, "m-xiaoman", "m-lina", RoleMember},
		{true, "m-lina", "m-xiaoman", RoleWard},
	}
	for _, c := range ownCases {
		ok, whyMsg := ownership(c.author, c.me, c.priv, c.role)
		p := "否"
		if c.priv {
			p = "是"
		}
		fmt.Printf("  %-10s %-12s %-12s %-10s %-6s %s\n", p, c.author, c.me, c.role, yn(ok), whyMsg)
	}
	fmt.Println()
	fmt.Println("  第 5 行是 owner 例外：私密流水作者不是我，但 owner 能读。")
	fmt.Println("  为什么？因为财务行给 owner 是「A（全部）」，而 S5 判据 2 要求")
	fmt.Println("  「child 读 adult 私有流水 → 被拒」，反过来「owner 读任何人的」是矩阵给的。")
	fmt.Println()
	fmt.Println("  但注意：**owner 能读 ≠ owner 能改**。")
	fmt.Println("  私密流水如果允许 owner 改，作者会失去对自己记录的追溯能力。")
	fmt.Println("  正确设计：owner 可读、不可改；作者可改可删；他人一律 404。")
	fmt.Println("  （这是 W21 d23 会真跑的场景。）")
	fmt.Println()

	fmt.Println("=== 6. 完整判定链：三类 condition 串起来跑（真跑）===")
	fmt.Println()
	sample := []Txn{
		{ID: "txn-A", FamilyID: "fam-001", AuthorID: "m-lina", AmountCents: 12800, Field: "L2", CreatedAt: now},
		{ID: "txn-B", FamilyID: "fam-001", AuthorID: "m-zhangwei", AmountCents: 480000, Field: "L3", CreatedAt: now},
		{ID: "txn-C", FamilyID: "fam-001", AuthorID: "m-lina", AmountCents: 65000, Field: "L3", IsPrivate: true, CreatedAt: now},
		{ID: "txn-D", FamilyID: "fam-002", AuthorID: "m-lina2", AmountCents: 99900, Field: "L2", CreatedAt: now},
	}
	subjects := []struct {
		name string
		s    Subject
	}{
		{"owner 张伟（无 guest 限制）", Subject{Role: RoleOwner, MeID: "m-zhangwei"}},
		{"owner 张伟（看 L3 已确认）", Subject{Role: RoleOwner, MeID: "m-zhangwei", Confirm: true}},
		{"member 李娜", Subject{Role: RoleMember, MeID: "m-lina"}},
		{"ward 小满（无账号）", Subject{Role: RoleWard, MeID: "m-xiaoman"}},
		{"guest 王阿姨（有效期内）", Subject{Role: RoleGuest, MeID: "m-wangyi-guest", Guest: &TimeWindow{ExpiresAt: expires}}},
		{"guest 王阿姨（已过期）", Subject{Role: RoleGuest, MeID: "m-wangyi-guest", Guest: &TimeWindow{ExpiresAt: expires, RevokedAt: ptr(revoked)}}},
	}
	for _, sub := range subjects {
		fmt.Printf("  【%s】\n", sub.name)
		for _, t := range sample {
			r := decide(t, sub.s, now, "read")
			status := "✅ 放行"
			if !r.Allow {
				status = "❌ 拒"
			}
			last := r.Trace[len(r.Trace)-1]
			reason := last
			if r.Allow {
				reason = "四维全通过"
			}
			// 放行时把字段等级也打出来，否则 confirm 与 visible 两种情况看不出差别。
			// 用 "等级 " 前缀切分，避免踩到中文理由里的空格。
			fv := "—"
			for _, line := range r.Trace {
				if strings.HasPrefix(line, "[cond/field] 字段等级 ") {
					fv = strings.TrimPrefix(line, "[cond/field] 字段等级 ")
					fv = fv[:strings.Index(fv, "：")]
				}
			}
			fmt.Printf("    %-6s %-9s %-4s %-8s %s\n", t.ID,
				fmt.Sprintf("%d 元", t.AmountCents/100), fieldOf(t), fv,
				status+"  ← "+reason)
		}
		fmt.Println()
	}
	fmt.Println("  表头：id / 金额 / 字段级 / 字段等级 / 判定")
	fmt.Println()
	fmt.Println("  几个值得停下来看的：")
	fmt.Println("  · owner 看 txn-B（L3 金额）第一次是 confirm，看 txn-C（私密）通过，")
	fmt.Println("    区别在 condition/own 而非 condition/field。")
	fmt.Println("  · member 李娜看 txn-A（自己的 L2）通过；看 txn-B（他人 L3）被 field 拦。")
	fmt.Println("  · guest 有效期内看 txn-A 通过；已过期时全部拒（时间窗在最前）。")
	fmt.Println("  · ward 小满对所有 txn 都拒（field hidden / 无权）。")
	fmt.Println()

	fmt.Println("=== 7. condition 与三维的关系：不是第四维，是过滤器 ===")
	fmt.Println()
	fmt.Println("  一个容易搞混的点：condition 不是和 module/data/action 并列的第四个 scope。")
	fmt.Println("  它是**串联在后面的过滤器**，而且可能不止一个：")
	fmt.Println()
	fmt.Println("    module 通过")
	fmt.Println("      AND data 通过")
	fmt.Println("        AND action 通过")
	fmt.Println("          AND cond_time 通过")
	fmt.Println("            AND cond_field 通过")
	fmt.Println("              AND cond_own 通过")
	fmt.Println("    → 放行")
	fmt.Println()
	fmt.Println("  「不并列」意味着：")
	fmt.Println("  · 不能只判一个 condition 就放行（今天三重都判了）")
	fmt.Println("  · 不能因为「没有 condition」就跳过判定 ——")
	fmt.Println("    它的默认值必须是「通过」还是「拒绝」？")
	fmt.Println("    答案：**没有 condition 时通过**（不存在限制 = 不受限），")
	fmt.Println("    但「condition 存在但判定失败」时必须拒绝。")
	fmt.Println("    区分这两种情况很重要，否则「没有时间窗的访客」会被误拒。")
	fmt.Println()

	fmt.Println("=== 8. 与 JS / 前端对比 ===")
	fmt.Println("  ① 字段级在 TS 里怎么表达：")
	fmt.Println("       type FieldVisibility = 'visible'|'confirm'|'masked'|'hidden'")
	fmt.Println("     这是一个四值联合类型，TS 编译期能查错。")
	fmt.Println("     Go 侧是 `type FieldVisibility string` + 4 个常量。")
	fmt.Println("     差别：TS 的 default 在 switch 里，Go 里我们让 map 查不到返 FieldHidden（fail closed）。")
	fmt.Println("  ② 前端对 confirm 档的体验最难做，因为它涉及**两次请求**：")
	fmt.Println("       第一次拿数据 → 发现字段是 'confirm' → 弹窗 → 用户确认")
	fmt.Println("       带 confirm_token 重新请求 → 拿到 visible")
	fmt.Println("     如果后端把 confirm 当成 visible 直接返，那这层交互就不存在了。")
	fmt.Println("  ③ masked 档前端要决定怎么渲染掩码：")
	fmt.Println("       field === 'masked' ? '¥ ****' : field")
	fmt.Println("     注意**不能用 0 代替掩码**，0 是一个真实值，会污染求和。")
	fmt.Println("     这是一个常见 bug：前端把 masked 当 null/0 累加，报表总额偏小。")
	fmt.Println("  ④ Go 侧 condition 的坑：**condition 判定要能单独测试**。")
	fmt.Println("     如果时间窗判定藏在 handler 里，你没法写「第 31 天访客被拒」这种单测。")
	fmt.Println("     所以每个 condition 都是一个纯函数，输入 (now, 对象, subject)，输出 bool + 理由。")
	fmt.Println("     「理由」这个返回值很关键 —— 审计日志要它，调试要它。")
	fmt.Println()

	fmt.Println("=== 9. 明天 ===")
	fmt.Println("  W19 收口：把今天的三类 condition 加上前三维，")
	fmt.Println("  写成一个可测试的**判定函数**（d12）。")
	fmt.Println("  收口时会第一次出现完整的「三维 + condition」判定入口，")
	fmt.Println("  并且暴露一个新问题：**25 格矩阵（§8.4）和 28 格 action 表")
	fmt.Println("  到底怎么对上** —— 这是 W20 的主题。")
}

func fieldOf(t Txn) string {
	if t.Field == "L3" {
		return "L3"
	}
	return "L2"
}

func yn(b bool) string {
	if b {
		return "✅"
	}
	return "❌"
}

// =====================================================================
// W19 d12：W19 收口 —— 三维 + condition 的判定函数 + 自查。
//
// 本机没有 Postgres。全部为内存逻辑真跑。
// 本天的产出是一个**完整、可单测、带轨迹**的判定函数 Decide()，
// 以及一份机械可判的自查清单（W19 判据）。
// =====================================================================

package main

import (
	"fmt"
	"strings"
	"time"
)

// ============ 类型定义（与 W18-W19 六天一致）============

type Role string

const (
	RoleOwner  Role = "owner"
	RoleMember Role = "member"
	RoleWard   Role = "ward"
	RoleGuest  Role = "guest"
)

type ModuleCode string

const (
	ModFinance ModuleCode = "finance"
	ModAsset   ModuleCode = "asset"
)

type Action string

const (
	ActRead Action = "read"
	// 只声明今天用到的动作；完整七个在 d10
)

type Grant string

const (
	GrantAll  Grant = "A"
	GrantNone Grant = "—"
)

// Session 是鉴权中间件构造出来的东西。family_id 只能来自这里。
type Session struct {
	UserID   string
	MemberID string
	FamilyID string
	Role     Role
	Guest    *GuestWindow
}

type GuestWindow struct {
	ExpiresAt time.Time
	RevokedAt *time.Time
}

type Resource struct {
	FamilyID string
	Module   ModuleCode
	AuthorID string
	MemberID string
	IsL3     bool
	IsPriv   bool
}

// ============ 判定层（按 tech-plan §8.2 的判定顺序）============

// 层 1：module（唯一输入是 FamilyModule）
var familyModules = map[string]map[ModuleCode]bool{
	"fam-001": {ModFinance: true, ModAsset: false},
	"fam-002": {},
}

func checkModule(fam string, role Role, code ModuleCode) (bool, string) {
	m, ok := familyModules[fam]
	if !ok {
		return false, "未知家庭"
	}
	if !m[code] {
		return false, fmt.Sprintf("面 %s 未启用", code)
	}
	roleAllows := map[Role][]ModuleCode{
		RoleOwner:  {ModFinance, ModAsset},
		RoleMember: {ModFinance, ModAsset},
		RoleWard:   {ModAsset},
		RoleGuest:  {ModFinance},
	}[role]
	for _, c := range roleAllows {
		if c == code {
			return true, "面已启用且角色可进入"
		}
	}
	return false, fmt.Sprintf("面已启用，但角色 %s 无权进入", role)
}

// 层 2：data（family_id 隔离，不可绕过）
func checkData(s Session, r Resource) (bool, string) {
	if r.FamilyID != s.FamilyID {
		return false, "资源不属于当前会话家庭"
	}
	return true, "资源属于当前会话家庭"
}

// 层 3：action（角色默认矩阵）
func checkAction(role Role, act Action) (Grant, string) {
	m := map[string]Grant{
		"owner:read":  GrantAll,
		"member:read": GrantAll,
		"ward:read":   GrantNone,
		"guest:read":  GrantNone,
	}[string(role)+":"+string(act)]
	return m, "查角色默认矩阵"
}

// 层 4a：condition 时间窗
func checkTimeWindow(s Session, at time.Time) (bool, string) {
	if s.Guest == nil {
		return true, "非访客，无时间窗限制"
	}
	if s.Guest.RevokedAt != nil {
		return false, "访客邀请已撤销"
	}
	if !at.Before(s.Guest.ExpiresAt) {
		return false, "访客已过期"
	}
	return true, "访客在有效期内"
}

// 层 4b：condition 字段级
func checkField(s Session, r Resource, confirmed bool) (string, bool, string) {
	switch s.Role {
	case RoleOwner:
		if r.IsL3 && !confirmed {
			return "confirm", true, "owner 看 L3 字段需二次确认"
		}
		return "visible", true, "owner 全字段可见"
	case RoleMember:
		if r.IsL3 {
			return "masked", true, "L3 字段对 member 返回掩码"
		}
		return "visible", true, "L2 字段可见"
	case RoleGuest:
		if r.IsL3 {
			return "masked", true, "L3 字段对 guest 返回掩码"
		}
		return "visible", true, "L2 字段可见"
	case RoleWard:
		return "hidden", false, "ward 不接触任何财务字段"
	}
	return "hidden", false, "未知角色 fail closed"
}

// 层 4c：condition 对象归属
func checkOwnership(s Session, r Resource) (bool, string) {
	if !r.IsPriv {
		return true, "非私密资源，不做归属判定"
	}
	if r.AuthorID == s.MemberID {
		return true, "私密资源，作者是我"
	}
	if s.Role == RoleOwner {
		return true, "私密资源，owner 例外可读"
	}
	return false, "私密资源，作者既不是我也不是 owner"
}

// ============ 唯一入口 ============

type Decision struct {
	Allow   bool
	Code    int // 0 成功；40402 不存在/无权限（越权返 404 不返 403）
	Message string
	FieldLv string
	Trace   []string
}

func Decide(s Session, r Resource, act Action, at time.Time, confirmed bool) Decision {
	d := Decision{FieldLv: "visible"}
	tp := func(stage string, ok bool, why string) bool {
		d.Trace = append(d.Trace, fmt.Sprintf("%-12s %s  %s", stage, mark(ok), why))
		return ok
	}

	if ok, why := checkModule(s.FamilyID, s.Role, r.Module); !tp("[module]", ok, why) {
		return deny(d, "资源不存在")
	}
	if ok, why := checkData(s, r); !tp("[data]", ok, why) {
		return deny(d, "资源不存在")
	}
	g, why := checkAction(s.Role, act)
	if !tp("[action]", g != GrantNone, why+" → "+string(g)) {
		return deny(d, "无权限")
	}
	if ok, why := checkTimeWindow(s, at); !tp("[cond/time]", ok, why) {
		return deny(d, "访客身份失效")
	}
	lv, ok, why := checkField(s, r, confirmed)
	d.FieldLv = lv
	if !tp("[cond/field]", ok, why+" → "+lv) {
		return deny(d, "资源不存在")
	}
	if ok, why := checkOwnership(s, r); !tp("[cond/own]", ok, why) {
		return deny(d, "资源不存在")
	}

	d.Allow = true
	d.Code = 0
	d.Message = "ok"
	d.Trace = append(d.Trace, "→ 放行")
	return d
}

func deny(d Decision, msg string) Decision {
	d.Allow = false
	d.Code = 40402
	d.Message = msg
	d.Trace = append(d.Trace, "→ 拒绝（404）")
	return d
}

// ============ 自查 ============

type Check struct {
	Name string
	OK   bool
	Note string
}

func main() {
	fmt.Println("=== 1. 判定函数：唯一入口 Decide() ===")
	fmt.Println("  签名（Go）：")
	fmt.Println("    func Decide(s Session, r Resource, act Action, at time.Time, confirmed bool) Decision")
	fmt.Println()
	fmt.Println("  对应的 TypeScript：")
	fmt.Println("    function decide(s: Session, r: Resource, act: Action,")
	fmt.Println("                 at: Date, confirmed: boolean): Decision")
	fmt.Println()
	fmt.Println("  两个设计决定值得解释：")
	fmt.Println("  ① `at time.Time` 是**必填参数**，不是内部调 time.Now()。")
	fmt.Println("     原因：单测要能测「第 31 天的访客被拒」，不能靠改系统时钟。")
	fmt.Println("     Go 里这不是惯例（通常直接 time.Now()），但权限判定值得这么做。")
	fmt.Println("  ② 返回 Decision 而不是 (bool, error)。")
	fmt.Println("     因为需要同时返回：Allow、错误码、消息、字段等级、判定轨迹。")
	fmt.Println("     bool + error 要塞 5 个信息进去会很难看。")
	fmt.Println("     Go 的多返回值是值语义（不是 JS 的对象引用），")
	fmt.Println("     显式 struct 比 map[string]any 更安全 —— 拼错 key 编译就报错。")
	fmt.Println()

	fmt.Println("=== 2. 一个完整请求走一遍：owner 看别人的私密 L3 流水 ===")
	fmt.Println()
	fixedNow := time.Date(2026, 10, 15, 9, 0, 0, 0, time.UTC)
	s := Session{UserID: "u-1001", MemberID: "m-zhangwei", FamilyID: "fam-001", Role: RoleOwner}
	r := Resource{FamilyID: "fam-001", Module: ModFinance, AuthorID: "m-lina",
		MemberID: "m-lina", IsL3: true, IsPriv: true}
	fmt.Printf("  会话：%s（%s）\n", s.MemberID, s.Role)
	fmt.Printf("  资源：作者 %s，L3=%v，私密=%v\n", r.AuthorID, r.IsL3, r.IsPriv)
	fmt.Println("  动作：read，未二次确认")
	fmt.Println()
	d := Decide(s, r, ActRead, fixedNow, false)
	for _, l := range d.Trace {
		fmt.Println("    " + l)
	}
	fmt.Println()
	fmt.Printf("  结果：Allow=%v Code=%d Message=%q FieldLv=%s\n", d.Allow, d.Code, d.Message, d.FieldLv)
	fmt.Println()
	fmt.Println("  注意 cond/own 那一行：owner 通过了归属判定（owner 例外）。")
	fmt.Println("  但 cond/field 返回的是 confirm —— 意思是：")
	fmt.Println("  「你可以看，但前端要先弹窗确认，确认后带 confirm_token 重来。」")
	fmt.Println("  这两个 condition 互相独立，不要合并成一个判断。")
	fmt.Println()

	fmt.Println("=== 3. 同一个请求，把条件换一换（真跑 6 次）===")
	fmt.Println()
	type variant struct {
		name      string
		sess      Session
		res       Resource
		confirmed bool
		note      string
	}
	expired := fixedNow.AddDate(0, 0, 31)
	revokedAt := fixedNow.AddDate(0, 0, 5)
	otherFamRes := Resource{FamilyID: "fam-002", Module: ModFinance, AuthorID: "m-x2", MemberID: "m-x2"}
	variants := []variant{
		{"① owner 未确认 L3", s, r, false, "cond/field 返回 confirm，仍放行（前端要弹窗）"},
		{"② owner 已确认 L3", s, r, true, "cond/field 返回 visible"},
		{"③ member 读他人私密", Session{MemberID: "m-tiantian", FamilyID: "fam-001", Role: RoleMember}, r, false, "cond/own 拒绝"},
		{"④ guest 已撤销后读", Session{UserID: "u-4", MemberID: "m-g", FamilyID: "fam-001", Role: RoleGuest,
			Guest: &GuestWindow{ExpiresAt: expired, RevokedAt: &revokedAt}}, r, false, "cond/time 拒绝（撤销优先于过期）"},
		{"⑤ guest 过期后读", Session{UserID: "u-4", MemberID: "m-g", FamilyID: "fam-001", Role: RoleGuest,
			Guest: &GuestWindow{ExpiresAt: expired}}, r, false, "cond/time 拒绝（过期）"},
		{"⑥ owner 跨家庭读", s, otherFamRes, false, "data 拒绝（跨家庭）"},
	}
	fmt.Printf("  %-22s %-8s %-8s %-8s %s\n", "场景", "Allow", "Code", "字段级", "拦在哪一层")
	for _, v := range variants {
		dd := Decide(v.sess, v.res, ActRead, fixedNow, v.confirmed)
		stage := "全部通过"
		for _, l := range dd.Trace {
			if strings.Contains(l, "❌") {
				f := strings.Fields(l)
				stage = f[0]
				break
			}
		}
		fmt.Printf("  %-22s %-8s %-8d %-8s %s\n", v.name, yn(dd.Allow), dd.Code, dd.FieldLv, stage)
	}
	fmt.Println()
