	}
	fmt.Println()
	fmt.Println("  **四个拒绝场景的 Code 都是 40402** —— 这就是 W21 d21 要讲的：")
	fmt.Println("  「越权一律返 404 不返 403」。今天的代码已经这么写了，")
	fmt.Println("  d21 会解释为什么，以及如果返 403 会泄露什么。")
	fmt.Println()

	fmt.Println("=== 4. W19 判据自查（机械可判定，真跑）===")
	fmt.Println()
	var checks []Check
	add := func(n string, ok bool, note string) {
		checks = append(checks, Check{n, ok, note})
	}

	// 判据 1：module 的唯一输入是 FamilyModule
	okAsset, _ := checkModule("fam-001", RoleOwner, ModAsset)
	add("module 未启用的面被拒（asset）", !okAsset, "fam-001 里 asset=false → 拒")
	okFin, _ := checkModule("fam-001", RoleOwner, ModFinance)
	add("module 已启用的面放行（finance）", okFin, "finance=true → 放行")
	okNone, _ := checkModule("fam-002", RoleOwner, ModFinance)
	add("module 空家庭表 → 全部拒（fail closed）", !okNone, "fam-002 无任何启用面")

	// 判据 2：data 一定以 family_id 开头
	sess := Session{MemberID: "m-zhangwei", FamilyID: "fam-001", Role: RoleOwner}
	okd, _ := checkData(sess, Resource{FamilyID: "fam-001"})
	bad, _ := checkData(sess, Resource{FamilyID: "fam-002"})
	add("data 同家庭通过", okd, "")
	add("data 跨家庭拒绝", !bad, "跨家庭在 data 层就拦住，不进后续判定")

	// 判据 3：action 从矩阵取，不硬编码
	for _, r := range []Role{RoleOwner, RoleMember} {
		g, _ := checkAction(r, ActRead)
		add(fmt.Sprintf("action %s read = %s", r, string(g)), g == GrantAll, "")
	}
	gw, _ := checkAction(RoleGuest, ActRead)
	add("action guest read = —", gw == GrantNone, "guest 在 action 层就拿不到 read")

	// 判据 4：condition 三类都在，且独立
	notGuest := Session{MemberID: "m", FamilyID: "f", Role: RoleMember}
	okT, _ := checkTimeWindow(notGuest, fixedNow)
	add("cond/time 非访客不拦", okT, "无 Guest 字段 → 无时间窗")
	okT2, _ := checkTimeWindow(notGuest, fixedNow.AddDate(5, 0, 0))
	add("cond/time 非访客 + 5 年后仍不拦", okT2, "时间窗只对 guest 生效")

	lv1, f1, _ := checkField(sess, Resource{IsL3: true}, false)
	lv2, f2, _ := checkField(sess, Resource{IsL3: true}, true)
	add("cond/field L3 未确认 = confirm", lv1 == "confirm" && f1, "owner 未确认")
	add("cond/field L3 已确认 = visible", lv2 == "visible" && f2, "owner 已确认")
	add("cond/field 两种结果不同", lv1 != lv2, "confirm 与 visible 是两态")

	okO, _ := checkOwnership(sess, Resource{AuthorID: "m-zhangwei", IsPriv: true})
	add("cond/own 私密且作者是我 → 通过", okO, "")
	memberSess := Session{MemberID: "m-lina", FamilyID: "fam-001", Role: RoleMember}
	badO, _ := checkOwnership(memberSess, Resource{AuthorID: "m-other", IsPriv: true})
	add("cond/own 私密且作者是他人（非 owner）→ 拒", !badO, "用 member 身份判，不是 owner")
	ownerO, _ := checkOwnership(sess, Resource{AuthorID: "m-other", IsPriv: true})
	add("cond/own owner 例外可读他人私密", ownerO, "财务行给 owner 是 A，例外成立")

	// 判据 5：越权统一 404
	dCross := Decide(sess, Resource{FamilyID: "fam-002", Module: ModFinance}, ActRead, fixedNow, false)
	dOwn := Decide(memberSess, Resource{FamilyID: "fam-001", Module: ModFinance, AuthorID: "m-x", IsPriv: true},
		ActRead, fixedNow, false)
	// 「资源不存在」由**存储层**返回（它带了 family_id 条件，查不到就是 404），
	// Decide 只负责「查到了但没权限」这一侧。两边必须给出同一个 Code，
	// 否则攻击者能靠状态码区分「东西存在但我没权限」和「压根不存在」。
	errNotFoundCode := 40402 // 存储层 ErrNotFound 的统一错误码
	add("越权与不存在的 Code 完全一致", dOwn.Code == errNotFoundCode,
		fmt.Sprintf("越权 %d vs 存储层 ErrNotFound %d", dOwn.Code, errNotFoundCode))
	add("跨家庭越权返 40402", dCross.Code == 40402, fmt.Sprintf("Code=%d", dCross.Code))
	add("非本人私密越权返 40402", dOwn.Code == 40402, fmt.Sprintf("Code=%d", dOwn.Code))
	add("全流程没有任何 403", dCross.Code != 403 && dOwn.Code != 403, "403 会泄露「东西存在」")

	pass, fail := 0, 0
	for _, c := range checks {
		flag := "✅"
		if !c.OK {
			flag = "❌"
		}
		note := c.Note
		if note != "" {
			note = "（" + note + "）"
		}
		fmt.Printf("    %s %-46s %s\n", flag, c.Name, note)
		if c.OK {
			pass++
		} else {
			fail++
		}
	}
	fmt.Println()
	fmt.Printf("  结果：%d 项通过，%d 项失败。\n", pass, fail)
	if fail == 0 {
		fmt.Println("  ✅ W19 的五条判据全部机械可判定地满足。")
	}
	fmt.Println()

	fmt.Println("=== 5. 这个函数怎么被调用（真实链路）===")
	fmt.Println()
	fmt.Println("    func (h *TxnHandler) Get(c *gin.Context) {")
	fmt.Println("      s := authz.SessionFrom(c)      // 中间件解析 token 塞进来")
	fmt.Println("      r := store.Resource{}")
	fmt.Println("      //   ↑ store 方法签名里**没有** familyID 参数，")
	fmt.Println("      //     它自己从 ctx 取 —— 漏传会编译不过")
	fmt.Println("      if err := h.store.Get(r.ID, &tx); err != nil {")
	fmt.Println("        return err   // 404（存储层已带 family_id 条件）")
	fmt.Println("      }")
	fmt.Println("      d := authz.Decide(s, authz.Resource{")
	fmt.Println("        FamilyID: tx.FamilyID, Module: authz.ModFinance,")
	fmt.Println("        AuthorID: tx.MemberID, IsPriv: tx.IsPrivate,")
	fmt.Println("      }, authz.ActRead, h.clock.Now(), false)")
	fmt.Println("      if !d.Allow {")
	fmt.Println("        return ErrNotFound   // ← 与 d21 一致")
	fmt.Println("      }")
	fmt.Println("      return respond(c, d.FieldLv, tx)   // 字段级可见性")
	fmt.Println("    }")
	fmt.Println()
	fmt.Println("  注意两点：")
	fmt.Println("  ① 存储层**已经**用 family_id 过滤了（S3 d18/d19 的纪律），")
	fmt.Println("     所以 authz.Decide 里的 data 层是**第二道**，不是第一道。")
	fmt.Println("     两道都要有：存储层挡住「查错」，authz 挡住「权限错」。")
	fmt.Println("  ② 字段级可见性（d.FieldLv）在**响应组装阶段**生效，")
	fmt.Println("     不是在查询阶段。用查询阶段做字段级会写出两种 SQL，维护不了。")
	fmt.Println()

	fmt.Println("=== 6. W19 六天回顾 ===")
	fmt.Println()
	review := []struct{ day, topic, key string }{
		{"d7", "为什么一维不够", "一维布尔只能答「能不能进页面」，真实需求有四个问题"},
		{"d8", "scope = module", "唯一输入是 FamilyModule；无行即未启用；不能有第二个开关"},
		{"d9", "scope = data", "四档过滤条件；family_id 只能从 token 取；参数里的 member_id 要复验"},
		{"d10", "scope = action", "七个动作分三组（数据/外发/构变）；export 不是 read 的子选项"},
		{"d11", "condition", "时间窗/字段/对象归属；字段级是四态不是布尔；判定顺序按约束强度"},
		{"d12", "收口", "Decide() 唯一入口 + 五条判据自查，全绿"},
	}
	for _, r := range review {
		fmt.Printf("  %-4s %-18s %s\n", r.day, r.topic, r.key)
	}
	fmt.Println()

	fmt.Println("=== 7. 明天 ===")
	fmt.Println("  W20 开始：把 W18/W19 得到的判定，落到 tech-plan §8.4 那张 25 格矩阵上。")
	fmt.Println("  明天先讲矩阵怎么读（角色 × 系统 × 动作），")
	fmt.Println("  后两天逐行逐格推导，最后一天把矩阵写成代码常量 + 逐格断言测试。")
}

