// W20 d18：W20 收口 —— 矩阵落成代码常量 + 逐格断言测试。
//
// 本机没有 Postgres。全部为内存逻辑真跑。
// 产出是 S5 判据 3 的落地形式：「四级角色权限清单与代码判定逐条对得上」。
// 本程序自带一个极简的断言框架（不依赖 testing 包，因为这是 main），
// 但断言写法与 Go 标准 testing 完全一致，可以直接搬进 *_test.go。
// =====================================================================

package main

import "fmt"

// ===================== 极简断言框架 =====================

type Result struct {
	Pass int
	Fail int
}

func (r *Result) Assert(t testing2, desc string) {
	if t.OK {
		r.Pass++
		fmt.Printf("    ✅ %s\n", desc)
	} else {
		r.Fail++
		fmt.Printf("    ❌ %s（期望 %s，实际 %s）\n", desc, t.Want, t.Got)
	}
}

// testing2 是一次断言的结果（期望值 + 实际值 + 是否相等）。
// 结构体而不是裸 bool，因为失败时要把「期望/实际」打进错误信息。
// 这正是 Go testing 的 require.Equal 做的事。
type testing2 struct {
	OK   bool
	Want string
	Got  string
}

func eq(want, got string) testing2 {
	return testing2{OK: want == got, Want: want, Got: got}
}

// truthy 把任意布尔包成断言结果，失败时打印期望/实际。
// 对应 Go testing 里的 require.True / require.False。
func truthy(b bool) testing2 {
	return testing2{OK: b, Want: "true", Got: fmt.Sprintf("%v", b)}
}
func falsy(b bool) testing2 {
	return testing2{OK: !b, Want: "false", Got: fmt.Sprintf("%v", b)}
}

// ===================== 矩阵常量（就是交付物本身）=====================

// TokenRole 是 token 里的 role 取值（只有四个，对应 tech-plan §8.1）
type TokenRole string

const (
	TokenOwner  TokenRole = "owner"
	TokenMember TokenRole = "member"
	TokenWard   TokenRole = "ward" // 有账号/无账号靠 uid 是否为空区分
	TokenGuest  TokenRole = "guest"
)

// Identity 是矩阵的列（五列，比角色多一个 ward 拆分）
type Identity string

const (
	RoleOwner     Identity = "owner"
	RoleMember    Identity = "member"
	RoleWardAcc   Identity = "ward(有账号)"
	RoleWardNoAcc Identity = "ward(无账号)"
	RoleGuest     Identity = "guest"
)

type SystemKey string

const (
	SysMemberPerm SystemKey = "HomeOS(成员/权限/设置)"
	SysModuleCfg  SystemKey = "HomeOS·面配置"
	SysCalendar   SystemKey = "Calendar·时间与到期对象"
	SysCollab     SystemKey = "HomeOS·协作对象"
	SysFinance    SystemKey = "财务"
)

type Cell string

const (
	CellAll  Cell = "A"
	CellMine Cell = "M"
	CellRead Cell = "R"
	CellNone Cell = "—"
)

// Matrix 是**唯一**的矩阵定义。判定只能读它，不能另写一份。
var Matrix = map[SystemKey]map[Identity]Cell{
	SysMemberPerm: {RoleOwner: CellAll, RoleMember: CellMine, RoleWardAcc: CellNone, RoleWardNoAcc: CellNone, RoleGuest: CellNone},
	SysModuleCfg:  {RoleOwner: CellAll, RoleMember: CellRead, RoleWardAcc: CellRead, RoleWardNoAcc: CellNone, RoleGuest: CellRead},
	SysCalendar:   {RoleOwner: CellAll, RoleMember: CellMine, RoleWardAcc: CellMine, RoleWardNoAcc: CellNone, RoleGuest: CellMine},
	SysCollab:     {RoleOwner: CellAll, RoleMember: CellMine, RoleWardAcc: CellMine, RoleWardNoAcc: CellNone, RoleGuest: CellMine},
	SysFinance:    {RoleOwner: CellAll, RoleMember: CellMine, RoleWardAcc: CellNone, RoleWardNoAcc: CellNone, RoleGuest: CellNone},
}

// ProxyMark 标记「监护人代写」的格。与矩阵并列，不混在 Cell 里。
var ProxyMark = map[SystemKey]map[Identity]bool{
	SysMemberPerm: {RoleWardNoAcc: true},
	SysCalendar:   {RoleWardNoAcc: true},
	SysCollab:     {RoleWardNoAcc: true},
	SysModuleCfg:  {RoleWardNoAcc: false},
	SysFinance:    {RoleWardNoAcc: false},
}

var AllRoles = []Identity{RoleOwner, RoleMember, RoleWardAcc, RoleWardNoAcc, RoleGuest}
var AllSystems = []SystemKey{SysMemberPerm, SysModuleCfg, SysCalendar, SysCollab, SysFinance}

// Grant 把 Cell 翻译成「能不能对某个对象做某个动作」。
//
// ⚠ 第三个参数 withinScope 的含义**逐行不同**，这是矩阵最容易被忽略的一点：
//
//	财务行      → withinScope = 「这条流水的 author_id == me」
//	成员/权限行 → withinScope = 「这个被编辑的成员是我的监护对象」
//	Calendar 行 → withinScope = 「这个对象包含我（members 含 me）」
//	协作对象行  → withinScope = 「这个对象的创建者是我」
//
// 同一个 M 字，在四行里对应的判定表达式完全不同。
// 所以调用方必须知道「自己在哪一行」，不能写一个通用的 withinScope 计算。
func Grant(sys SystemKey, col Identity, act string, withinScope bool) (bool, string) {
	row, ok := Matrix[sys]
	if !ok {
		return false, "未知系统，fail closed"
	}
	c, ok := row[col]
	if !ok {
		return false, "未知身份，fail closed"
	}
	switch c {
	case CellNone:
		return false, string(c) + " 无权限"
	case CellRead:
		if act == "read" {
			return true, string(c) + " 只读：允许读"
		}
		return false, string(c) + " 只读：不允许写"
	case CellMine:
		if act == "read" {
			return true, string(c) + "：读允许"
		}
		if withinScope {
			return true, string(c) + "：对象在本行定义的范围内，允许写"
		}
		return false, string(c) + "：对象不在本行定义的范围内，拒绝写"
	case CellAll:
		return true, string(c) + "：全部允许"
	}
	return false, "未知格值，fail closed"
}

// IDOfIdentity 是 token → 矩阵列的唯一转换点。
// 有账号/无账号的区别来自 uid 是否为空（d03 讲的 user_id 可空），
// 不是 token 里的另一个 role 值。
func IDOfIdentity(role TokenRole, hasAccount bool) Identity {
	if role == TokenWard {
		if hasAccount {
			return RoleWardAcc
		}
		return RoleWardNoAcc
	}
	return Identity(role)
}

