func dashes(n int) string {
	b := make([]byte, n)
	for i := range b {
		b[i] = '-'
	}
	return string(b)
}

// =====================================================================
// W21 d19：越权的四种形态 —— 横向 / 纵向 / 时序 / 批量。
//
// 本机没有 Postgres。四个形态全部用内存逻辑**真跑演示**，
// 每个形态都会真的泄露一次，然后演示「修好之后」的结果。
// 这是 S5 的核心周：从今天起，每一天都要「先红后绿」。
// =====================================================================

package main

import "fmt"

// Field 是敏感度分级（L2 普通 / L3 金额），用于字段级可见性
type Field string

const (
	FieldL2 Field = "L2"
	FieldL3 Field = "L3"
)

// ============ 模拟的数据 ============

type Txn struct {
	ID          string
	FamilyID    string
	AuthorID    string
	AmountCents int64
	Note        string
	IsPrivate   bool
	Field       Field
}

type Session struct {
	UserID   string
	MemberID string
	FamilyID string
	Role     string
	TokenExp int // token 过期时间戳（用相对分钟数表示，便于确定性输出）
	NowMin   int
}

var txns = []Txn{
	{ID: "txn-A-01", FamilyID: "fam-001", AuthorID: "m-zhangwei", AmountCents: 480000, Note: "房贷", Field: "L3"},
	{ID: "txn-A-02", FamilyID: "fam-001", AuthorID: "m-lina", AmountCents: 12800, Note: "超市买菜", Field: "L2"},
	{ID: "txn-A-03", FamilyID: "fam-001", AuthorID: "m-zhangwei", AmountCents: 65000, Note: "年终奖入账", IsPrivate: true, Field: "L3"},
	{ID: "txn-B-01", FamilyID: "fam-002", AuthorID: "m-lina2", AmountCents: 99900, Note: "别人的表", Field: "L2"},
	{ID: "txn-B-02", FamilyID: "fam-002", AuthorID: "m-zhangwei2", AmountCents: 88800, Note: "别人的房贷", Field: "L3"},
	{ID: "txn-B-03", FamilyID: "fam-002", AuthorID: "m-lina2", AmountCents: 4200, Note: "别人的午饭", Field: "L2"},
}

func yuan(c int64) string { return fmt.Sprintf("%d.%02d 元", c/100, c%100) }

// ============ 有 bug 的四个实现 ============

// 形态一：横向越权（改 id 读别人）
func getByIDVuln(s Session, id string) (Txn, bool) {
	for _, t := range txns {
		if t.ID == id {
			return t, true // ❌ 只按 id 查
		}
	}
	return Txn{}, false
}
func getByIDSafe(s Session, id string) (Txn, bool) {
	for _, t := range txns {
		if t.ID == id && t.FamilyID == s.FamilyID { // ✅ 双条件
			return t, true
		}
	}
	return Txn{}, false
}

// 形态二：纵向越权（用低权限身份调高权限操作）
// 这里用「guest 调 admin 接口」演示
func adminActionVuln(s Session, act string) (bool, string) {
	// ❌ 只检查了「有没有登录」，没检查角色
	if s.UserID == "" {
		return false, "未登录"
	}
	return true, "已登录，放行"
}
func adminActionSafe(s Session, act string) (bool, string) {
	if s.UserID == "" {
		return false, "未登录"
	}
	if s.Role != "owner" {
		return false, "只有 owner 能管理成员"
	}
	return true, "owner，放行"
}

// 形态三：时序越权（token 过期后还用）
func tokenValidVuln(s Session) (bool, string) {
	if s.UserID == "" {
		return false, "未登录"
	}
	return true, "只看有没有登录"
}
func tokenValidSafe(s Session) (bool, string) {
	if s.UserID == "" {
		return false, "未登录"
	}
	if s.NowMin >= s.TokenExp {
		return false, fmt.Sprintf("token 已于 %d 分钟过期，当前 %d 分钟", s.TokenExp, s.NowMin)
	}
	return true, "token 在有效期内"
}

// 形态四：批量拖库（一次导出全部）
func exportVuln(s Session) ([]Txn, string) {
	out := []Txn{}
	for _, t := range txns {
		if t.FamilyID == s.FamilyID {
			out = append(out, t)
		}
	}
	return out, "无上限返回本家庭全部"
}
func exportSafe(s Session) ([]Txn, string) {
	if s.Role != "owner" {
		return nil, "只有 owner 能导出"
	}
	out := []Txn{}
	for _, t := range txns {
		if t.FamilyID == s.FamilyID {
			out = append(out, t)
		}
	}
	return out, "owner 导出，且带游标分页上限"
}

func main() {
	fmt.Println("=== 1. 越权 vs 未认证：先分清两件事 ===")
	fmt.Println("  · 未认证（Unauthenticated）：你没登录 → 401")
	fmt.Println("  · 认证失败（Invalid token）：token 伪造/过期 → 401")
	fmt.Println("  · 越权（Authorized but not permitted）：**你登录了，但你不能碰这个** → 404（本项目）")
	fmt.Println()
	fmt.Println("  越权的前提是「攻击者是合法用户」。这让它特别难发现：")
	fmt.Println("  从服务端日志看，这是一个完全正常的请求（带 token、有响应）。")
	fmt.Println()

	sess := Session{UserID: "u-1001", MemberID: "m-zhangwei", FamilyID: "fam-001", Role: "owner",
		TokenExp: 900, NowMin: 500}

	fmt.Println("=== 2. 四种形态总览 ===")
	fmt.Println()
	forms := []struct{ name, desc, defense string }{
		{"横向（Horizontal）", "同层级用户之间越权：A 读 B 的数据", "每个查询带 family_id（data scope）"},
		{"纵向（Vertical）", "低权限调高权限：member 调 owner 接口", "action 维度查角色矩阵"},
		{"时序（Temporal）", "用已过期/已撤销的凭证", "condition 时间窗 + pver 比对"},
		{"批量（Bulk）", "一次拖走大量数据", "export 独立动作 + 游标分页上限"},
	}
	for i, f := range forms {
		fmt.Printf("  %d. %-18s %s\n", i+1, f.name, f.desc)
		fmt.Printf("     %-20s 防御：%s\n", "", f.defense)
	}
	fmt.Println()

	// ---------------- 形态一 ----------------
	fmt.Println("=== 3. 形态一：横向越权（改一个 id 就看到别人的）===")
	fmt.Println()
	target := "txn-B-02"
	fmt.Printf("  攻击者：%s（%s，fam-001）\n", sess.MemberID, sess.Role)
	fmt.Printf("  目标：%s（fam-002 的房贷）\n", target)
	fmt.Println()
	leaked, ok1 := getByIDVuln(sess, target)
	fmt.Println("  ❌ 有 bug 的实现（只按 id 查）：")
	if ok1 {
		fmt.Printf("     返回 200：{ \"id\": \"%s\", \"amount_cents\": %d, \"note\": \"%s\" }\n",
			leaked.ID, leaked.AmountCents, leaked.Note)
		fmt.Printf("     💀 泄露：fam-002 的「%s」%s 被 fam-001 的用户看到了\n", leaked.Note, yuan(leaked.AmountCents))
	} else {
		fmt.Println("     未泄露")
	}
	fmt.Println()
	_, ok2 := getByIDSafe(sess, target)
	fmt.Println("  ✅ 修好后（id + family_id 双条件）：")
	if !ok2 {
		fmt.Println("     返回 404：{ \"code\": 40402, \"message\": \"流水不存在\" }")
		fmt.Println("     ✅ 不泄露：既没数据，也没说「它存在」")
	}
	fmt.Println()

	// 枚举
	fmt.Println("  如果不修，攻击者可以枚举 fam-002 的全部记录：")
	for _, t := range txns {
		if t.FamilyID != "fam-001" {
			_, got := getByIDVuln(sess, t.ID)
			st := "404"
			if got {
				st = "200 💀"
			}
			_, safeGot := getByIDSafe(sess, t.ID)
			st2 := "404 ✅"
			if safeGot {
				st2 = "200"
			}
			fmt.Printf("     %-12s 有bug=%-8s 修好后=%s\n", t.ID, st, st2)
		}
	}
	fmt.Println()
	fmt.Println("  这就是 S3 d19 讲过的 IDOR。本阶段把它纳入「越权测试」体系：")
	fmt.Println("  判据 1「用 A 家 token 读 B 家数据 → 404，不是 403」正是在测这个。")
	fmt.Println()

	// ---------------- 形态二 ----------------
	fmt.Println("=== 4. 形态二：纵向越权（member 调 owner 接口）===")
	fmt.Println()
	memberSess := Session{UserID: "u-1002", MemberID: "m-lina", FamilyID: "fam-001", Role: "member",
		TokenExp: 900, NowMin: 500}
	fmt.Println("  请求：DELETE /api/homeos/members/m-tiantian（移除一个成员）")
	fmt.Printf("  Authorization: Bearer <%s 的 token，role=member>\n", memberSess.MemberID)
	fmt.Println()
	okv, whyv := adminActionVuln(memberSess, "delete_member")
	fmt.Println("  ❌ 有 bug 的实现（只检查「有没有登录」）：")
	if okv {
		fmt.Println("     返回 200：{ \"code\": 0, \"message\": \"已移除成员\" }")
		fmt.Println("     💀 李娜不是 owner，她把甜甜移出了家庭")
		fmt.Printf("     （判定理由：%s）\n", whyv)
	}
	fmt.Println()
	oks, whys := adminActionSafe(memberSess, "delete_member")
	fmt.Println("  ✅ 修好后（action 维度查角色矩阵）：")
	if !oks {
		fmt.Println("     返回 404：{ \"code\": 40402, \"message\": \"成员不存在\" }")
		fmt.Printf("     ✅ member 在「成员/权限」行不是 admin：%s\n", whys)
	}
	fmt.Println()
	fmt.Println("  横向 vs 纵向的区别（很重要）：")
	fmt.Println("  · 横向：A 想看 B 的数据 → 靠 family_id 挡住")
	fmt.Println("  · 纵向：member 想做 owner 的事 → 靠角色矩阵挡住")
