	fmt.Println()

	// ---------------- 形态三 ----------------
	fmt.Println("=== 5. 形态三：时序越权（token 过期后还用）===")
	fmt.Println()
	expired := Session{UserID: "u-1001", MemberID: "m-zhangwei", FamilyID: "fam-001", Role: "owner",
		TokenExp: 900, NowMin: 1000}
	fmt.Printf("  token 签发有效期：%d 分钟\n", expired.TokenExp)
	fmt.Printf("  当前时间：%d 分钟（已超过）\n", expired.NowMin)
	fmt.Println()
	okt, whyt := tokenValidVuln(expired)
