		fmt.Printf("     （判定理由：%s）\n", whyt)
	}
	fmt.Println()
	okt2, whyt2 := tokenValidSafe(expired)
	fmt.Println("  ✅ 修好后（校验 exp）：")
	if !okt2 {
		fmt.Println("     返回 401：{ \"code\": 1001, \"message\": \"token 已过期\" }")
		fmt.Printf("     ✅ %s\n", whyt2)
	}
	fmt.Println()
	fmt.Println("  时序越权的三个具体场景：")
	fmt.Println("  ① token 过期后仍可用（access token 应该 15 分钟过期）")
	fmt.Println("  ② 角色降级后旧 token 仍带旧角色（token 里的 role 是快照，d06 讲过）")
	fmt.Println("  ③ 访客撤销后旧 token 仍可用（撤销要立即生效，d04 讲过）")
	fmt.Println()
	fmt.Println("  这三个场景的防御机制不同：")
	fmt.Println("    ① → token exp 校验（基础设施）")
	fmt.Println("    ② → pver 比对（角色改了 pver+1，判定时比对，d28 讲）")
	fmt.Println("    ③ → 条件时间窗（每次判定都查 revoked_at，d11 讲）")
	fmt.Println("  → 所以「时序越权」不是一个 bug，是**三个独立的失效机制**。")
	fmt.Println()

	// ---------------- 形态四 ----------------
	fmt.Println("=== 6. 形态四：批量拖库（一次导出全部）===")
	fmt.Println()
	fmt.Println("  请求：GET /api/finance/transactions?limit=99999")
	fmt.Printf("  Authorization: Bearer <%s 的 token，role=member>\n", memberSess.MemberID)
	fmt.Println()
	vulnOut, whyOut := exportVuln(memberSess)
	fmt.Println("  ❌ 有 bug 的实现（只看 family_id，无上限）：")
	fmt.Printf("     返回 200，共 %d 条（%s）\n", len(vulnOut), whyOut)
	fmt.Println("     内容：")
	for _, t := range vulnOut {
		p := ""
		if t.IsPrivate {
			p = " 🔒私密（owner 的年终奖！）"
		}
		fmt.Printf("       %-12s %-12s %s%s\n", t.ID, yuan(t.AmountCents), t.Note, p)
	}
	fmt.Println("     💀 一次请求拖走全量数据，且包含私密记录")
	fmt.Println("        （私密在 d17 讲的是「行级可见」，这里 export 绕过了它）")
	fmt.Println()
	safeOut, whySafe := exportSafe(memberSess)
	fmt.Println("  ✅ 修好后（export 是独立动作 + 只有 owner 能做）：")
