	fmt.Printf("     返回 %d 条，且带分页游标（next_cursor）\n", len(ownerOut))
	fmt.Println()
	fmt.Println("  批量越权的两个防线：")
	fmt.Println("  ① **动作维度**：export 是独立 action，member 是「—」")
	fmt.Println("  ② **规模维度**：即使 owner 导出，也要游标分页（§6.3「不接受无上限返回」）")
	fmt.Println("  只做①：owner 一次拖走 100 万条 → 数据库被打满")
	fmt.Println("  只做②：member 分 100 次导，每次 20 条 → 一样泄露")
	fmt.Println("  → 两个都要。")
	fmt.Println()

	fmt.Println("=== 7. 四种形态的对照表 ===")
	fmt.Println()
	fmt.Printf("  %-14s %-34s %-28s %s\n", "形态", "特征", "防线", "对应判据")
	fmt.Println("  " + dashes(14+34+28+10))
	rows := []struct{ form, feat, defense, crit string }{
		{"横向", "同家庭不同成员，或跨家庭读别人的", "每个查询带 family_id", "判据 1"},
		{"纵向", "低权限调高权限接口", "action 维度查角色矩阵", "判据 3"},
		{"时序", "用过期/已撤销/已降级的凭证", "token exp + pver + 条件时间窗", "判据 4"},
		{"批量", "一次拖走大量或全部数据", "export 独立动作 + 游标分页上限", "判据 1"},
	}
	for _, r := range rows {
		fmt.Printf("  %-14s %-34s %-28s %s\n", r.form, r.feat, r.defense, r.crit)
	}
	fmt.Println()
	fmt.Println("  判据 4 是「讲清」类的（为什么返 404 不返 403），明天专门讲。")
	fmt.Println()

	fmt.Println("=== 8. 一个容易被忽略的第五种：存在性泄露 ===")
	fmt.Println()
	fmt.Println("  即使数据没泄露，「这个 id 存不存在」也是信息。")
	fmt.Println()
	fmt.Println("  假如我们返 403：")
	fmt.Println("    GET /api/finance/transactions/txn-B-01  → 403「无权限」")
	fmt.Println("    GET /api/finance/transactions/txn-Z-99  → 404「不存在」")
	fmt.Println("  攻击者立刻知道：txn-B-01 是真实存在的记录。")
	fmt.Println()
	fmt.Println("  统一返 404：")
	fmt.Println("    GET /api/finance/transactions/txn-B-01  → 404「不存在」")
	fmt.Println("    GET /api/finance/transactions/txn-Z-99  → 404「不存在」")
	fmt.Println("  攻击者无法区分。")
	fmt.Println()
	fmt.Println("  ⚠ 但要注意：这只在「同一类资源」里成立。")
	fmt.Println("    对**完全不同类型**的资源（流水 vs 成员），404 vs 404 就无法隐藏「类型存在」。")
	fmt.Println("    那种情况要靠不暴露 id 格式（比如不返回「成员 id」，返回「家庭成员」抽象）。")
	fmt.Println("    明天（d21）会详细讲这条的边界。")
	fmt.Println()

	fmt.Println("=== 9. 与 JS / 前端对比 ===")
	fmt.Println("  ① 前端天然容易只防纵向，不防横向：")
	fmt.Println("       if (role === 'owner') showDeleteButton()")
	fmt.Println("     这挡的是纵向。但横向（改 id）前端完全管不了 ——")
	fmt.Println("     请求是用户用 curl / Postman 发的，你的组件一行都不执行。")
	fmt.Println("  ② 水平越权的标准防护在 JS 里也有对应物：")
	fmt.Println("       // Node/Express 里你必须手写：")
	fmt.Println("       app.get('/api/txns/:id', requireAuth, async (req, res) => {")
	fmt.Println("         const txn = await db.findById(req.params.id)")
	fmt.Println("         if (txn.familyId !== req.user.familyId) {")
	fmt.Println("           return res.status(404).json({ message: 'not found' })")
	fmt.Println("         }")
	fmt.Println("       })")
	fmt.Println("       这段代码用 JS 写和用 Go 写**完全一样**——因为这是数据访问的逻辑，")
	fmt.Println("       不是语言特性。Go 的优势是类型系统能让「忘记传 familyID」编译不过。")
	fmt.Println("  ③ 时序越权在 JS 里的对应物：")
	fmt.Println("       // 常见错误：JWT 只 verify 不看 exp")
	fmt.Println("       const payload = jwt.decode(token)   // ❌ decode 不验签！")
	fmt.Println("       const payload = jwt.verify(token, secret)  // ✅ verify 会查 exp")
	fmt.Println("     Go 侧对应：jwt.Parse 会验签并检查 exp，但**如果传了 WithoutClaimsValidation 就关了**。")
	fmt.Println("     这两个都是「函数名相近但语义不同」的坑。")
	fmt.Println("  ④ 批量越权在 JS 里的对应物：")
	fmt.Println("       // 常见错误：无上限返回")
	fmt.Println("       res.json(await db.find({ familyId }))")
	fmt.Println("     Go 侧对应：GORM 的 Find(&[]Txn{}) 不加 Limit 会拉全表。")
	fmt.Println("     铁律 4「列表强制游标分页，不接受无上限返回」就是针对这个。")
	fmt.Println()

	fmt.Println("=== 10. 明天 ===")
	fmt.Println("  今天把四种形态的框架搭好了，明天挑最常见的横向越权做**完整实测**：")
	fmt.Println("  · 完整的攻击 HTTP 请求 + 响应体")
	fmt.Println("  · 正确的 SQL（DryRun 生成）")
