}

func dashes(n int) string {
	b := make([]byte, n)
	for i := range b {
		b[i] = '-'
	}
	return string(b)
}

// =====================================================================
// W21 d22：字段级越权 —— 列表里能不能看到不该看的字段。
//
// 本机没有 Postgres。内存模拟数据 + 真跑的 JSON 组装与裁剪。
// 关键点：字段级越权比行级更难发现，因为它**返回 200**，
// 响应体结构完全正常，只是多了几个字段。
// =====================================================================

package main

import (
	"fmt"
	"strings"
)

type Role string

const (
	RoleOwner  Role = "owner"
	RoleMember Role = "member"
	RoleGuest  Role = "guest"
	RoleWard   Role = "ward"
)

type Session struct {
	MemberID string
	FamilyID string
	Role     Role
}

// 数据源：一条流水的完整字段（数据库里就是这些）
type TxnRecord struct {
	ID           string
	FamilyID     string
	AuthorID     string
	MemberID     string
	AmountCents  int64
	Note         string
	Receipt      string
	IsPrivate    bool
	AccountID    string
	ClientReqID  string
	OnBehalfOf   string
	GeneratedBy  string
	InternalNote string // 仅 owner 可见的内部备注
}

var records = []TxnRecord{
	{ID: "txn-01", FamilyID: "fam-001", AuthorID: "m-zhangwei", MemberID: "m-zhangwei",
		AmountCents: 480000, Note: "房贷 10 月", Receipt: "file-001", IsPrivate: false,
		AccountID: "acc-001", ClientReqID: "cr-001", OnBehalfOf: "", GeneratedBy: "",
		InternalNote: "已与银行核对"},
	{ID: "txn-02", FamilyID: "fam-001", AuthorID: "m-lina", MemberID: "m-lina",
		AmountCents: 12800, Note: "超市买菜", Receipt: "", IsPrivate: false,
		AccountID: "acc-001", ClientReqID: "cr-002", OnBehalfOf: "", GeneratedBy: "",
		InternalNote: ""},
	{ID: "txn-03", FamilyID: "fam-001", AuthorID: "m-zhangwei", MemberID: "m-zhangwei",
		AmountCents: 65000, Note: "年终奖入账", Receipt: "", IsPrivate: true,
		AccountID: "acc-002", ClientReqID: "cr-003", OnBehalfOf: "", GeneratedBy: "",
		InternalNote: "税后实发"},
	{ID: "txn-04", FamilyID: "fam-001", AuthorID: "m-zhangwei", MemberID: "m-xiaoman",
		AmountCents: 240000, Note: "补习班", Receipt: "file-004", IsPrivate: false,
		AccountID: "acc-001", ClientReqID: "cr-004", OnBehalfOf: "m-xiaoman", GeneratedBy: "recurring",
		InternalNote: ""},
