		AmountCents: 300000, Note: "奶奶医药费", Receipt: "", IsPrivate: true,
		AccountID: "acc-001", ClientReqID: "cr-005", OnBehalfOf: "m-wangyi", GeneratedBy: "",
		InternalNote: "长期用药，需复查"},
}

// ❌ BEFORE：直接 json.Marshal 整个结构体
func listBefore(s Session) string {
	rows := []string{}
	for _, r := range records {
		if r.FamilyID != s.FamilyID {
			continue
		}
		if r.IsPrivate && r.AuthorID != s.MemberID && s.Role != RoleOwner {
			continue // 行级过滤（d17 讲的），假设这行是对的
		}
		rows = append(rows, serializeAll(r))
	}
	return wrap(rows)
}

func serializeAll(r TxnRecord) string {
	f := []string{
		fmt.Sprintf(`"id": "%s"`, r.ID),
		fmt.Sprintf(`"author_id": "%s"`, r.AuthorID),
		fmt.Sprintf(`"member_id": "%s"`, r.MemberID),
		fmt.Sprintf(`"amount_cents": %d`, r.AmountCents),
		fmt.Sprintf(`"note": "%s"`, r.Note),
		fmt.Sprintf(`"receipt": "%s"`, r.Receipt),
		fmt.Sprintf(`"is_private": %v`, r.IsPrivate),
		fmt.Sprintf(`"account_id": "%s"`, r.AccountID),
		fmt.Sprintf(`"client_request_id": "%s"`, r.ClientReqID),
		fmt.Sprintf(`"on_behalf_of": "%s"`, r.OnBehalfOf),
		fmt.Sprintf(`"generated_by": "%s"`, r.GeneratedBy),
		fmt.Sprintf(`"internal_note": "%s"`, r.InternalNote),
	}
	return "{" + strings.Join(f, ", ") + "}"
}

// ✅ AFTER：按字段白名单投影
var allFields = []string{"id", "author_id", "member_id", "amount_cents", "note",
	"receipt", "is_private", "account_id", "client_request_id", "on_behalf_of",
	"generated_by", "internal_note"}

func fieldsFor(s Session) []string {
	base := []string{"id", "author_id", "member_id", "amount_cents", "note", "is_private"}
	switch s.Role {
	case RoleOwner:
		// owner 能看到全部（但 internal_note 只有 owner 可见）
		return append(base, "receipt", "account_id", "on_behalf_of", "generated_by", "internal_note")
	case RoleMember:
		// member 看不到 internal_note、client_request_id（幂等键不该暴露）
		return append(base, "receipt", "account_id", "on_behalf_of", "generated_by")
	case RoleGuest:
		// guest 最少：连 author_id 都不给（不需要知道是谁记的）
		return []string{"id", "amount_cents", "note"}
	case RoleWard:
		return []string{"id"}
	}
	return []string{"id"}
}

func fieldValue(r TxnRecord, f string) string {
	switch f {
	case "id":
		return fmt.Sprintf(`"%s"`, r.ID)
	case "author_id":
		return fmt.Sprintf(`"%s"`, r.AuthorID)
	case "member_id":
		return fmt.Sprintf(`"%s"`, r.MemberID)
	case "amount_cents":
		return fmt.Sprintf("%d", r.AmountCents)
	case "note":
		return fmt.Sprintf(`"%s"`, r.Note)
	case "receipt":
		return fmt.Sprintf(`"%s"`, r.Receipt)
	case "is_private":
		return fmt.Sprintf("%v", r.IsPrivate)
	case "account_id":
		return fmt.Sprintf(`"%s"`, r.AccountID)
	case "client_request_id":
		return fmt.Sprintf(`"%s"`, r.ClientReqID)
	case "on_behalf_of":
		return fmt.Sprintf(`"%s"`, r.OnBehalfOf)
	case "generated_by":
		return fmt.Sprintf(`"%s"`, r.GeneratedBy)
	case "internal_note":
		return fmt.Sprintf(`"%s"`, r.InternalNote)
	}
	return "null"
}

func listAfter(s Session) string {
	allow := fieldsFor(s)
	allowSet := map[string]bool{}
	for _, f := range allow {
		allowSet[f] = true
	}
	rows := []string{}
	for _, r := range records {
		if r.FamilyID != s.FamilyID {
			continue
		}
		if r.IsPrivate && r.AuthorID != s.MemberID && s.Role != RoleOwner {
			continue
		}
		parts := []string{}
		for _, f := range allFields {
			if allowSet[f] {
				parts = append(parts, fmt.Sprintf(`"%s": %s`, f, fieldValue(r, f)))
			}
		}
		rows = append(rows, "{"+strings.Join(parts, ", ")+"}")
	}
	return wrap(rows)
}

func wrap(rows []string) string {
	return "{\n      \"code\": 0,\n      \"message\": \"ok\",\n      \"data\": {\n        \"items\": [\n          " +
		strings.Join(rows, ",\n          ") + "\n        ],\n        \"next_cursor\": null\n      },\n      \"request_id\": \"req-1\"\n    }"
}

// fieldsPerRow 数**单行**的字段数：只统计 items 数组里第一个对象的 key。
// 不能用 strings.Count(整个JSON, ":")，那会把外层 envelope
// （code/message/data/next_cursor/request_id）也算进去。
func fieldsPerRow(json string) int {
	start := strings.Index(json, `{"`)
	if start < 0 {
		return 0
	}
	end := strings.Index(json[start:], "}")
	if end < 0 {
		return 0
	}
	row := json[start : start+end+1]
	return strings.Count(row, ":")
}

// 找出不该出现却出现了的字段
func leakedFields(json string, allow []string) []string {
	allowSet := map[string]bool{}
	for _, f := range allow {
		allowSet[f] = true
	}
	leaked := []string{}
	for _, f := range allFields {
		if !allowSet[f] && strings.Contains(json, `"`+f+`"`) {
			leaked = append(leaked, f)
		}
	}
	return leaked
}

func main() {
	member := Session{MemberID: "m-lina", FamilyID: "fam-001", Role: RoleMember}
	guest := Session{MemberID: "m-guest", FamilyID: "fam-001", Role: RoleGuest}
	owner := Session{MemberID: "m-zhangwei", FamilyID: "fam-001", Role: RoleOwner}

	fmt.Println("=== 1. 为什么字段级越权比行级更难发现 ===")
	fmt.Println()
	fmt.Println("  行级越权：返回 403/404 → 状态码异常 → 监控能报警。")
	fmt.Println("  字段级越权：返回 **200**，响应体结构完全正常，")
	fmt.Println("             只是多了几个本该没有的字段。")
	fmt.Println()
	sev := []struct{ kind, detect string }{
		{"多了 internal_note", "最难。要人工审响应体才知道"},
		{"多了 client_request_id", "难。幂等键暴露，攻击者可用它去重放"},
		{"多了 receipt", "中。附件 URL 泄露 = 文件泄露"},
		{"多了 account_id", "中。能看出资产规模"},
		{"多了 author_id", "容易。多家庭 id 泄露（d20 讲过）"},
	}
	fmt.Printf("  %-28s %s\n", "泄露的字段", "发现难度")
	for _, s := range sev {
		fmt.Printf("  %-28s %s\n", s.kind, s.detect)
	}
	fmt.Println()
	fmt.Println("  扫描器基本发现不了字段级越权 —— 因为")
	fmt.Println("  「这个 JSON 格式对不对」是能查的，「这个字段该不该给这个人」查不了。")
	fmt.Println()

	fmt.Println("=== 2. BEFORE：直接序列化整个结构体 ===")
	fmt.Println()
	fmt.Println("  请求：")
	fmt.Println("    GET /api/finance/transactions")
	fmt.Println("    Authorization: Bearer <m-lina 的 token，role=member>")
	fmt.Println()
	before := listBefore(member)
	fmt.Println("  响应 200：")
	for _, l := range strings.Split(before, "\n") {
		fmt.Println("  " + l)
	}
	fmt.Println()
	fmt.Println("  ❌ 问题：m-lina 是 member，她拿到了这些字段：")
	leakedB := leakedFields(before, fieldsFor(member))
	fmt.Printf("    多出来的：%v\n", leakedB)
	for _, f := range leakedB {
		detail := ""
		for _, r := range records {
