			}
		}
		fmt.Printf("      · %s\n", detail)
	}
	fmt.Println()
	fmt.Println("  逐个说清楚危害：")
	fmt.Println("    internal_note = 「税后实发」「已与银行核对」")
	fmt.Println("      → 这是**只有 owner 可见的内部备注**，member 不该看到。")
	fmt.Println("      → 它本身不敏感，但它证明了「还存在一个 member 看不到的字段」，")
	fmt.Println("        攻击者会继续找。")
