	fmt.Println("=== 4. 三个角色的字段白名单（真跑对比）===")
	fmt.Println()
	fmt.Printf("  %-22s %-10s %-8s %-8s %s\n", "身份", "可见行数", "BEFORE", "AFTER", "AFTER 的字段白名单")
