			"最显式；编译期就知道有哪些字段", "角色多了要写很多 DTO；容易漏拷"},
		{"白名单切片 + 手动组装", "var allow []string; 遍历组装 map",
			"一份白名单驱动所有场景", "map 顺序不定（要用有序切片）；无类型检查"},
		{"json tag 控制", "给敏感字段加 `json:\"-\"`",
			"最省事", "❌ **全局生效**，owner 也看不到了 —— 不满足需求"},
	}
	for _, i := range impls {
		fmt.Printf("  方式 %d：%s\n", impls2(impls, i.name), i.name)
		fmt.Printf("      做法：%s\n", i.how)
		fmt.Printf("      优点：%s\n", i.pros)
		fmt.Printf("      缺点：%s\n", i.cons)
	}
	fmt.Println()
	fmt.Println("  重点说第三种（json tag）为什么不行：")
