	fmt.Println("    ② handler 调 authz.FieldSetFor(session, resource) 拿到白名单")
	fmt.Println("    ③ 用一个通用的 Project(record, allowlist) 生成 map，再序列化成 JSON")
	fmt.Println("    ④ 审计：记录这次用了哪个白名单（便于排查「为什么 owner 看不到 X」）")
	fmt.Println()

	fmt.Println("=== 6. 一个更隐蔽的问题：嵌套结构 ===")
	fmt.Println()
	fmt.Println("  上面的例子是平铺字段。真实响应有嵌套：")
	fmt.Println("    {")
	fmt.Println("      \"id\": \"txn-01\",")
	fmt.Println("      \"account\": {")
	fmt.Println("        \"id\": \"acc-001\",")
	fmt.Println("        \"balance_cents\": 1250000,   ← ⚠️ 账户余额！")
	fmt.Println("        \"owner_member_id\": \"m-zhangwei\"")
	fmt.Println("      },")
	fmt.Println("      \"member\": {")
	fmt.Println("        \"name\": \"张伟\",")
	fmt.Println("        \"user_id\": \"u-1001\",       ← ⚠️ 用户 id，不是 member id！")
	fmt.Println("        \"phone\": \"138****8888\"")
	fmt.Println("      },")
	fmt.Println("      \"tags\": [\"fixed\", \"monthly\"]")
	fmt.Println("    }")
	fmt.Println()
	fmt.Println("  三个新问题：")
	fmt.Println("  ① 嵌套对象的字段也要裁。account.balance_cents 是不是该给 guest？")
	fmt.Println("     它不是流水的字段，但**通过嵌套泄露了账户余额**。")
	fmt.Println("  ② user_id 与 member_id 的区别（d03 讲过）在这里暴露了：")
	fmt.Println("     member.user_id 是**登录账号 id**，泄露它意味着")
	fmt.Println("     攻击者能去别的地方（日志、错误信息）找这个账号。")
	fmt.Println("  ③ 数组元素也要裁。tags 数组里每个元素都是字符串，")
	fmt.Println("     但如果换成对象数组（比如 participants），每个元素都要单独裁。")
	fmt.Println()
	fmt.Println("  结论：字段裁剪必须是**递归**的。")
	fmt.Println("  「写一个白名单，遍历顶层的 key」这种实现遇到嵌套就漏。")
	fmt.Println("  → 实践建议：嵌套对象**单独定义响应结构**，不用 map[string]any 递归。")
	fmt.Println("    每个嵌套类型有自己的 DTO，字段可见性在构造时决定。")
	fmt.Println("    虽然啰嗦，但漏不掉。")
	fmt.Println()

	fmt.Println("=== 7. 测试：怎么断言字段级没泄露 ===")
	fmt.Println()
	fmt.Println("  核心断言：**响应里的 key 集合 ⊆ 允许集合**。")
	fmt.Println()
	fmt.Println("  func assertNoLeakedFields(t *testing.T, body []byte, allow []string) {")
	fmt.Println("      var m map[string]any")
	fmt.Println("      require.NoError(t, json.Unmarshal(body, &m))")
	fmt.Println("      items := m[\"data\"].(map[string]any)[\"items\"].([]any)")
	fmt.Println("      allowSet := toSet(allow)")
	fmt.Println("      for i, it := range items {")
	fmt.Println("          row := it.(map[string]any)")
	fmt.Println("          for k := range row {")
	fmt.Println("              if !allowSet[k] {")
	fmt.Println(`                  t.Errorf("泄露字段: item=" + strconv.Itoa(i) + " key=" + k)`)
	fmt.Println("              }")
	fmt.Println("          }")
	fmt.Println("      }")
	fmt.Println("  }")
	fmt.Println()
	fmt.Println("  为什么这个断言比「检查某个值」更强：")
	fmt.Println("  · 检查值：\"internal_note 不等于 \\\"税后实发\\\"\" → 换个数据就漏")
	fmt.Println("  · 检查 key 集合：**任何情况下**出现白名单外的 key 都红")
	fmt.Println()
	fmt.Println("  配套的第二条断言（防止「白名单被改松了」）：")
	fmt.Println("    // 白名单本身也要被断言，否则有人加个字段就悄悄泄露了")
	fmt.Println("    require.Equal(t, []string{...}, authz.FieldSetFor(memberSess, res))")
	fmt.Println("  两条一起才完整：")
	fmt.Println("    ① 响应 ⊆ 白名单（实现正确）")
	fmt.Println("    ② 白名单 ⊆ 预期（设计没被改松）")
	fmt.Println()

	fmt.Println("=== 8. guest 的最严白名单：一个设计决策 ===")
	fmt.Println()
	fmt.Println("  guest 的白名单是 id / amount_cents / note 三项。")
	fmt.Println("  考虑过要不要给 is_private —— 最后决定**不给**：")
	fmt.Println("  · 给了会暴露「这条是私密的」→ 相当于告诉他「张伟有私密记录」")
	fmt.Println("  · 而他看不到私密记录，所以这个信息对他无用")
	fmt.Println("  → **无用且有害的信息一律不给**，这是一条筛选原则")
	fmt.Println()
	fmt.Println("  另一个考虑：amount_cents 要不要也给 masked？")
	fmt.Println("  最后决定**给明文**，理由：")
	fmt.Println("  · guest 的存在意义就是「看看这个月花了多少」")
	fmt.Println("  · 如果金额全 masked，他来了也什么都看不到")
	fmt.Println("  · 访客的时效性（30 天）+ 不可导出限制了风险")
	fmt.Println("  → 这里的取舍是「可用性优先」，因为 guest 是明确的、临时的、")
	fmt.Println("    且 owner 可以随时撤销的合作方，不是敌对势力。")
	fmt.Println("  这与 ward 的「—」形成对比：ward 是家庭成员但**不该**知道钱，")
	fmt.Println("  guest 是外人但**被邀请**知道。性质不同，所以选择不同。")
	fmt.Println()

	fmt.Println("=== 9. 与 JS / 前端对比 ===")
	fmt.Println("  ① 前端做字段裁剪是最常见的错误：")
	fmt.Println("       const rows = data.items.filter(x => !x.isPrivate)")
	fmt.Println("     这**完全没有用** —— isPrivate 这个字段已经传过来了，")
	fmt.Println("     攻击者 curl 一下就看到了全部。")
	fmt.Println("     正确做法：服务端根本不返回不该返回的字段。")
	fmt.Println("  ② 但前端**也要**做一层，理由不同：")
	fmt.Println("     · 避免把敏感数据存进 localStorage / 埋点")
	fmt.Println("     · 避免 React DevTools 里看到不该看的值")
	fmt.Println("     前端这一层是**纵深防御**，服务端那层才是边界。")
	fmt.Println("  ③ TS 的类型在这里帮不上忙（除非配合运行时校验）：")
	fmt.Println("       type TxnResp = { id: string; amountCents: number; /* 没有 internalNote */ }")
	fmt.Println("     但服务端返回什么 TS 管不了。")
	fmt.Println("     → 所以类型定义要**从服务端的实际契约生成**（OpenAPI → types），")
	fmt.Println("       这样白名单变更时前端类型也会变，编译期就能发现不一致。")
	fmt.Println("  ④ Go 侧的零值陷阱又出现了：")
	fmt.Println("     如果用 `map[string]string` 投影，")
	fmt.Println("     不给某字段时是「key 不存在」（正确）；")
	fmt.Println("     但如果先 `out[k] = v` 再 `delete(out, k)`，")
	fmt.Println("     中间状态可能被打进日志。")
	fmt.Println("     → 直接用「白名单驱动组装」，不做「全量后删除」。")
	fmt.Println()

	fmt.Println("=== 10. 明天 ===")
	fmt.Println("  今天讲了「列」的可见性（哪些字段给）。")
	fmt.Println("  明天讲 is_private 的「行」级可见性实测 ——")
	fmt.Println("  「他人私密流水只有作者与管理员能读」这条规则，")
	fmt.Println("  会真跑出 before/after 对比，并落到判据 2 的「落审计」上。")
	fmt.Println("  两天合起来就是完整的「行 + 列」双层可见性。")
}

func countVisible(s Session) int {
	n := 0
	for _, r := range records {
		if r.FamilyID != s.FamilyID {
			continue
		}
		if r.IsPrivate && r.AuthorID != s.MemberID && s.Role != RoleOwner {
			continue
		}
		n++
	}
	return n
}

func fieldHasValue(r TxnRecord, f string) bool {
	switch f {
	case "internal_note":
		return r.InternalNote != ""
	case "receipt":
		return r.Receipt != ""
	case "client_request_id":
		return r.ClientReqID != ""
	case "on_behalf_of":
		return r.OnBehalfOf != ""
	case "generated_by":
		return r.GeneratedBy != ""
	case "account_id":
		return r.AccountID != ""
	case "author_id":
		return r.AuthorID != ""
	}
	return false
}

func impls2(all []struct{ name, how, pros, cons string }, name string) int {
	for i, x := range all {
		if x.name == name {
			return i + 1
		}
	}
	return 0
}

