const (
	RoleOwner  = "owner"
	RoleMember = "member"
	RoleWard   = "ward"
	RoleGuest  = "guest"
)

type Session struct {
	MemberID string
	FamilyID string
	Role     string
}

type Txn struct {
	ID          string
	FamilyID    string
	AuthorID    string
	MemberID    string
	AmountCents int64
	Note        string
	IsPrivate   bool
}

var txns = []Txn{
