}

// ============ BEFORE：只按 id 查 ============
func getBefore(s Session, id string) (Txn, bool) {
	for _, t := range txns {
		if t.ID == id {
			return t, true
		}
	}
	return Txn{}, false
}

// ============ AFTER：矩阵层 AND 行级层 ============
func matrixAllows(s Session) bool {
	// §8.4 财务行：owner=A, member=M, ward/guest=—
	switch s.Role {
	case RoleOwner, RoleMember:
		return true
	case RoleWard, RoleGuest:
		return false
	}
	return false
}

func rowVisible(s Session, t Txn) (bool, string) {
	if !t.IsPrivate {
		return true, "非私密"
	}
	if t.AuthorID == s.MemberID {
		return true, "私密但作者是我"
	}
	if s.Role == RoleOwner {
		return true, "私密，owner 例外"
	}
	return false, "private_not_visible"
}

func getAfter(s Session, id string) (Txn, bool, string) {
	if !matrixAllows(s) {
		return Txn{}, false, "matrix_denied"
	}
	for _, t := range txns {
		if t.ID != id {
			continue
		}
		if t.FamilyID != s.FamilyID {
			return Txn{}, false, "cross_family"
		}
		if ok, why := rowVisible(s, t); !ok {
			return Txn{}, false, why
		}
		return t, true, "ok"
	}
	return Txn{}, false, "not_found"
}

// ============ 审计（真跑落库到内存 slice）============
type AuditEntry struct {
	ActorID    string
	Action     string
	ResourceID string
	Decision   string
	Reason     string
	Seq        int
}

var auditLog []AuditEntry
var auditSeq int

func audit(actorID, action, resourceID, decision, reason string) {
	auditSeq++
	auditLog = append(auditLog, AuditEntry{
		ActorID: actorID, Action: action, ResourceID: resourceID,
		Decision: decision, Reason: reason, Seq: auditSeq,
	})
}

func fixedTime() time.Time { return time.Date(2026, 10, 15, 9, 30, 0, 0, time.UTC) }

func dryDB() *gorm.DB {
	db, err := gorm.Open(postgres.New(postgres.Config{
		DSN: "postgres://svc_finance:dev_password@localhost:5432/homecube?sslmode=disable",
	}), &gorm.Config{
		DryRun: true, DisableAutomaticPing: true,
		NowFunc: func() time.Time { return fixedTime() },
		Logger:  logger.Default.LogMode(logger.Silent),
	})
	if err != nil {
		panic(err)
	}
	return db
}

type TxnRow struct {
	ID          string         `gorm:"column:id;type:uuid;primaryKey"`
	FamilyID    string         `gorm:"column:family_id;type:uuid;not null"`
	AuthorID    string         `gorm:"column:author_id;type:uuid;not null"`
	AmountCents int64          `gorm:"column:amount_cents;not null"`
	Note        string         `gorm:"column:note;type:varchar(200)"`
	IsPrivate   bool           `gorm:"column:is_private;not null;default:false"`
	Version     int            `gorm:"column:version;not null;default:1"`
	DeletedAt   gorm.DeletedAt `gorm:"column:deleted_at;index"`
}

func (TxnRow) TableName() string { return "finance_transaction" }

func flat(s string) string { return strings.Join(strings.Fields(s), " ") }
func yuan(c int64) string  { return fmt.Sprintf("%d.%02d 元", c/100, c%100) }

