	fmt.Println("  判据 5 要求「有一个跑在代码里的越权测试循环，不是手动点几次」——")
	fmt.Println("  明天就交付那个循环。")
}

func countFam(famID string) int {
	n := 0
	for _, t := range txns {
		if t.FamilyID == famID {
			n++
		}
	}
	return n
}

func yn(b bool) string {
	if b {
		return "可见"
	}
	return "不可见"
}

func codeOf(ok bool) string {
	if ok {
		return "200"
	}
	return "404"
}

