// ===================== 被测系统（模拟服务端）=====================

type Role string

const (
	RoleOwner  Role = "owner"
	RoleMember Role = "member"
	RoleWard   Role = "ward"
	RoleGuest  Role = "guest"
)

type Session struct {
	UserID   string
	MemberID string
	FamilyID string
	Role     Role
}

type Txn struct {
	ID          string
	FamilyID    string
	AuthorID    string
	AmountCents int64
	IsPrivate   bool
}

// 三个家庭，12 条流水 —— 覆盖多租户 + 私密 + 跨成员
