// 断言框架
type T struct {
	name   string
	fails  []string
	total  int
	passed int
}

func (t *T) check(ok bool, desc string, detail string) {
	t.total++
	if ok {
		t.passed++
	} else {
		t.fails = append(t.fails, desc+" — "+detail)
	}
}

func (t *T) report() {
	status := "✅"
	if len(t.fails) > 0 {
		status = "❌"
	}
	fmt.Printf("  %s %-38s %d/%d\n", status, t.name, t.passed, t.total)
	for _, f := range t.fails {
		fmt.Printf("      ❌ %s\n", f)
	}
}

// 真实实现（AFTER）
func GetByID(s Session, id string) (Txn, int, string) {
	// 第 1 层：矩阵（scope=action）
	if s.Role == RoleWard || s.Role == RoleGuest {
		return Txn{}, 404, "matrix_denied"
	}
	// 第 2 层 + 第 3 层：租户隔离 + 行级可见
	for _, t := range db {
		if t.ID != id {
			continue
		}
		if t.FamilyID != s.FamilyID {
			return Txn{}, 404, "cross_family"
		}
		if t.IsPrivate && t.AuthorID != s.MemberID && s.Role != RoleOwner {
			return Txn{}, 404, "private_not_visible"
		}
		return t, 200, "ok"
	}
	return Txn{}, 404, "not_found"
}

func ListTxns(s Session, memberFilter string) ([]Txn, string) {
	if s.Role == RoleWard || s.Role == RoleGuest {
		return nil, "matrix_denied"
	}
	out := []Txn{}
	for _, t := range db {
		if t.FamilyID != s.FamilyID {
			continue
		}
		if t.IsPrivate && t.AuthorID != s.MemberID && s.Role != RoleOwner {
			continue
		}
		if memberFilter != "" && t.AuthorID != memberFilter {
			continue
		}
		out = append(out, t)
	}
	return out, "ok"
}

// ---- 有 bug 的实现（BEFORE），用来验证测试有效性 ----
func GetByIDVulnerable(s Session, id string) (Txn, int) {
	for _, t := range db {
		if t.ID == id {
			return t, 200
		}
	}
	return Txn{}, 404
}

