		{"member 读自己的私密", member1, "t-A5", 200, "ok"},
		{"member 读他人的私密 → 404", member1, "t-A3", 404, "private_not_visible"},
		{"member 读他人的非私密 → 200", member1, "t-A1", 200, "ok"},
		{"同家庭另一个 member 读私密 → 404", member1b, "t-A5", 404, "private_not_visible"},
		{"同家庭另一个 member 读私密 → 404", member1b, "t-A3", 404, "private_not_visible"},
		{"**跨家庭**读 → 404", owner1, "t-B1", 404, "cross_family"},
		{"**跨家庭**读私密 → 404", owner1, "t-B4", 404, "cross_family"},
		{"**跨家庭**读另一个家庭的 owner → 404", member1, "t-B1", 404, "cross_family"},
		{"反向：fam-2 读 fam-1 → 404", owner2, "t-A1", 404, "cross_family"},
		{"反向：fam-2 读 fam-1 私密 → 404", owner2, "t-A3", 404, "cross_family"},
		{"ward 读任何财务 → 404", ward1, "t-A1", 404, "matrix_denied"},
		{"ward 读私密 → 404", ward1, "t-A3", 404, "matrix_denied"},
		{"guest 读任何财务 → 404", guest1, "t-A1", 404, "matrix_denied"},
		{"guest 读私密 → 404", guest1, "t-A5", 404, "matrix_denied"},
		{"不存在的 id → 404", owner1, "t-Z9", 404, "not_found"},
	}
	fmt.Printf("    %-40s %-8s %-8s %s\n", "场景", "期望", "实际", "reason")
	for _, c := range cases {
		_, code, why := GetByID(c.sess, c.id)
		okCode := code == c.want
		okWhy := why == c.wantWhy
		m.check(okCode && okWhy, c.desc,
			fmt.Sprintf("期望 %d/%s，实际 %d/%s", c.want, c.wantWhy, code, why))
		fmt.Printf("    %-40s %-8s %-8s %s\n", c.desc, codeOf(c.want), codeOf(code), why)
	}
	m.report()
	fmt.Println()

	// ============ ② 隔离通用断言 ============
	fmt.Println("=== 3. ② 隔离通用断言（返回的每一行都必须属于会话家庭）===")
	fmt.Println()
	iso := &T{name: "② 隔离通用断言"}
	for _, s := range []Session{owner1, member1, member1b, ward1, guest1, owner2} {
