	// ============ ③ 模糊测试（100 次）============
	fmt.Println("=== 4. ③ 模糊测试：100 次伪随机请求 ===")
	fmt.Println()
	fz := &T{name: "③ 模糊测试（100 次）"}
	// 固定种子 → 输出完全可复现。真实项目用 crypto/rand 或 fuzz 引擎。
	rnd := rand.New(rand.NewSource(20261015))

	ids := []string{}
	for _, t := range db {
		ids = append(ids, t.ID)
	}
	// 掺入不存在的 id 和恶意 id 形态
	ids = append(ids, "t-Z1", "t-Z2", "", "../../etc/passwd", "' OR 1=1--",
