		// 断言 1：返回 200 时，这一行必须属于会话家庭
		if code == 200 {
			fz.check(row.FamilyID == s.FamilyID,
				fmt.Sprintf("第%d次 family_id 隔离", i+1),
				fmt.Sprintf("%s 以 %s/%s 读到 %s（family=%s ≠ %s）",
					s.MemberID, s.FamilyID, s.Role, row.ID, row.FamilyID, s.FamilyID))
			// 断言 2：返回 200 时，行级可见必须成立
			visible := !row.IsPrivate || row.AuthorID == s.MemberID || s.Role == RoleOwner
			fz.check(visible,
