					fmt.Sprintf("第%02d次 %s(%s/%s) 读到 %s", i+1, s.MemberID, s.FamilyID, s.Role, row.ID))
			}
		}
		// 断言 3：deny 场景的对外错误码必须是 404，**绝不能是 403**
		if code != 200 {
			fz.check(code == 404,
				fmt.Sprintf("第%d次 越权返 404", i+1),
				fmt.Sprintf("返回了 %d（403 会泄露存在性）", code))
			// 断言 4：deny 时 reason 必须在**对外可见的枚举**内。
			//   ok 是 allow 路径的 reason，不该出现在 deny 上 ——
