func countCrossFamily(cases []struct {
	desc    string
	sess    Session
	id      string
	want    int
	wantWhy string
}) int {
	n := 0
	for _, c := range cases {
		if c.wantWhy == "cross_family" {
			n++
		}
	}
	return n
}

func codeOf(c int) string {
	if c == 200 {
		return "200"
	}
	return "404"
}

// =====================================================================
// W22 d25：权限判定顺序 —— 显式拒绝 > 角色默认矩阵 > 家庭级覆盖 > 对象级 ACL。
//
// 本机没有 Postgres。全部内存逻辑真跑，输出完全确定。
// 核心问题：**顺序错了会怎样**。本程序会真跑出一个「顺序写反」的后果。
// tech-plan §8.2 给的判定顺序：
//   显式拒绝 > 角色默认矩阵 > 家庭级覆盖 > 对象级 ACL
// 注意「>」读作「优先于」，不是「大于」。
// =====================================================================

package main

import (
	"fmt"
	"strings"
)

type Role string

const (
	RoleOwner  Role = "owner"
	RoleMember Role = "member"
	RoleGuest  Role = "guest"
	RoleWard   Role = "ward"
)

type Action string

const (
	ActRead   Action = "read"
	ActWrite  Action = "write"
	ActExport Action = "export"
)

type Subject struct {
	Role     Role
	MemberID string
	FamilyID string
}

// ---- 第 1 层：显式拒绝（deny list）----
type DenyRule struct {
	MemberID string
	Resource string
	Reason   string
}

var denyList = []DenyRule{
	{MemberID: "m-lina", Resource: "ledger:led-salary", Reason: "2026-09-20 owner 手动冻结该账本"},
}

// ---- 第 2 层：角色默认矩阵 ----
type Cell string

const (
	CellAll  Cell = "A"
	CellNone Cell = "—"
)

// knownSystems 是本项目认识的资源前缀。只有这些前缀才可能通过矩阵判定。
var knownSystems = []string{"ledger:", "finance:", "calendar:", "homeos:"}

// systemOf 从 resource 取出系统前缀（tech-plan 铁律 10：七类命名同源，
// 所以资源 id 的前缀必然是系统 code + ":"）
func systemOf(resource string) string {
	for _, sys := range knownSystems {
		if strings.HasPrefix(resource, sys) {
			return strings.TrimSuffix(sys, ":")
		}
	}
	return ""
}

// roleMatrixLookup 返回矩阵档位 + 「这个资源是否属于已知系统」。
// 第二个返回值不能省：漏了它，「不存在的资源」会被当成「有权限」。
func roleMatrixLookup(r Role, a Action, resource string) (Cell, bool) {
	if systemOf(resource) == "" {
		return CellNone, false
	}
	return roleMatrix(r, a, resource), true
}

func roleMatrix(r Role, a Action, resource string) Cell {
	switch r {
	case RoleOwner:
		return CellAll
	case RoleMember:
		if a == ActExport && resource == "ledger:led-salary" {
			return CellAll // member 在普通账本是 M（可导出由 owner 决定），此处示例
		}
		return CellAll
	case RoleGuest, RoleWard:
		return CellNone
	}
	return CellNone
}

// ---- 第 3 层：家庭级覆盖（P1 不实现，但要有位置）----
type FamilyOverride struct {
	FamilyID string
	MemberID string
	Action   Action
	Resource string
	Allow    bool
	Reason   string
}

var overrides = []FamilyOverride{}

// ---- 第 4 层：对象级 ACL（P1 不实现）----
type ObjectACL struct {
	Resource string
	MemberID string
	Allow    bool
}

var objectAcls = []ObjectACL{}

type Decision struct {
	Allow bool
	Stage string
	Why   string
}

// ✅ 正确顺序：显式拒绝 > 角色矩阵 > 家庭覆盖 > 对象 ACL
func decideCorrect(s Subject, a Action, resource string) Decision {
	// ① 显式拒绝最先查 —— 有 deny 就到此为止，不再看后面
	for _, d := range denyList {
		if d.MemberID == s.MemberID && d.Resource == resource {
			return Decision{false, "①显式拒绝", d.Reason}
		}
	}
	// ② 角色默认矩阵
	//    先确认资源本身存在（矩阵是按「系统」查的，不是按任意 resource 字符串）。
	//    这是一个容易漏的点：如果矩阵只按 role 查，
	//    那「不存在的资源」也会被判成「有权限」——
	//    上层必须先确认资源存在（或由 handler 在调用前查过）。
	cell, known := roleMatrixLookup(s.Role, a, resource)
	if !known {
		return Decision{false, "②角色矩阵", "资源不属于任何已知系统（无法判定）"}
	}
	if cell == CellNone {
		return Decision{false, "②角色矩阵", string(s.Role) + " 在此动作上是「—」"}
	}
	// ③ 家庭级覆盖（P1 恒空）
	for _, o := range overrides {
		if o.FamilyID == s.FamilyID && o.MemberID == s.MemberID &&
			o.Action == a && o.Resource == resource {
			if !o.Allow {
				return Decision{false, "③家庭覆盖", o.Reason}
			}
			return Decision{true, "③家庭覆盖", o.Reason}
		}
	}
	// ④ 对象级 ACL（P1 恒空）
	for _, a2 := range objectAcls {
		if a2.Resource == resource && a2.MemberID == s.MemberID {
			if !a2.Allow {
				return Decision{false, "④对象ACL", "对象级显式拒绝"}
			}
			return Decision{true, "④对象ACL", "对象级显式允许"}
		}
	}
	// 都没命中 → 按角色矩阵的默认值
	if cell == CellAll {
		return Decision{true, "②角色矩阵", "矩阵放行，无任何覆盖/ACL 命中"}
	}
	return Decision{false, "②角色矩阵", "矩阵无权限"}
}

// ❌ 错误顺序：把覆盖层/ACL 放在显式拒绝**之前**
func decideWrongOrder(s Subject, a Action, resource string) Decision {
	// ④ 对象级 ACL 先查
	for _, a2 := range objectAcls {
		if a2.Resource == resource && a2.MemberID == s.MemberID && a2.Allow {
			return Decision{true, "④对象ACL(先查)", "对象级允许 —— 但跳过了显式拒绝"}
		}
	}
	// ③ 家庭覆盖先查
	for _, o := range overrides {
		if o.FamilyID == s.FamilyID && o.MemberID == s.MemberID &&
			o.Action == a && o.Resource == resource && o.Allow {
			return Decision{true, "③家庭覆盖(先查)", "家庭允许 —— 但跳过了显式拒绝"}
		}
	}
	// ① 显式拒绝（被放到了最后）
	for _, d := range denyList {
		if d.MemberID == s.MemberID && d.Resource == resource {
			return Decision{false, "①显式拒绝(最后查)", d.Reason}
		}
	}
	if cell, known := roleMatrixLookup(s.Role, a, resource); known && cell == CellAll {
		return Decision{true, "②角色矩阵", "矩阵放行"}
	}
	return Decision{false, "②角色矩阵", "矩阵无权限或资源未知"}
}

// ❌ 另一种错误：所有层取「或」（任一允许就放行）
func decideOrLogic(s Subject, a Action, resource string) Decision {
	denied := false
	for _, d := range denyList {
		if d.MemberID == s.MemberID && d.Resource == resource {
			denied = true
		}
	}
	cell, known := roleMatrixLookup(s.Role, a, resource)
	matrixOK := known && cell == CellAll
	overrideOK := false
	for _, o := range overrides {
		if o.FamilyID == s.FamilyID && o.MemberID == s.MemberID && o.Action == a && o.Allow {
			overrideOK = true
		}
	}
	if matrixOK || overrideOK { // ❌ or 逻辑：显式拒绝被无视
		return Decision{true, "或逻辑", "矩阵或覆盖任一为真就放行（无视 deny）"}
	}
	if denied {
		return Decision{false, "或逻辑", "只有 deny 命中"}
	}
	return Decision{false, "或逻辑", "全部拒绝"}
}

