	fmt.Println("      }")
	fmt.Println("      // ② 角色默认矩阵 —— 默认状态")
	fmt.Println("      cell := Matrix[systemOf(resource)][identityOf(s)]")
	fmt.Println("      if cell == CellNone {")
	fmt.Println("          return Decision{Allow: false, Stage: StageMatrix, Why: \"矩阵无权限\"}")
	fmt.Println("      }")
