	fmt.Println("      if ov := findOverride(s.FamilyID, s.MemberID, a, resource); ov != nil {")
	fmt.Println("          return Decision{Allow: ov.Allow, Stage: StageOverride, Why: ov.Reason}")
	fmt.Println("      }")
	fmt.Println("      // ④ 对象级 ACL —— P1 恒空")
	fmt.Println("      if acl := findObjectACL(resource, s.MemberID); acl != nil {")
