package main

import "fmt"

type Role string

const (
	RoleOwner  Role = "owner"
	RoleMember Role = "member"
	RoleWard   Role = "ward"
	RoleGuest  Role = "guest"
)

type Identity string

const (
	IdOwner     Identity = "owner"
	IdMember    Identity = "member"
	IdWardAcc   Identity = "ward(有账号)"
	IdWardNoAcc Identity = "ward(无账号)"
	IdGuest     Identity = "guest"
)

type SystemKey string

const (
	SysMemberPerm SystemKey = "HomeOS(成员/权限/设置)"
	SysModuleCfg  SystemKey = "HomeOS·面配置"
	SysCalendar   SystemKey = "Calendar·时间与到期对象"
	SysCollab     SystemKey = "HomeOS·协作对象"
	SysFinance    SystemKey = "财务"
)

type Cell string

const (
	CellAll  Cell = "A"
	CellMine Cell = "M"
	CellRead Cell = "R"
	CellNone Cell = "—"
)

// ===== P1 的三层 =====
// 层 1：角色默认矩阵（代码常量）
var matrix = map[SystemKey]map[Identity]Cell{
	SysMemberPerm: {IdOwner: CellAll, IdMember: CellMine, IdWardAcc: CellNone, IdWardNoAcc: CellNone, IdGuest: CellNone},
	SysModuleCfg:  {IdOwner: CellAll, IdMember: CellRead, IdWardAcc: CellRead, IdWardNoAcc: CellNone, IdGuest: CellRead},
	SysCalendar:   {IdOwner: CellAll, IdMember: CellMine, IdWardAcc: CellMine, IdWardNoAcc: CellNone, IdGuest: CellMine},
	SysCollab:     {IdOwner: CellAll, IdMember: CellMine, IdWardAcc: CellMine, IdWardNoAcc: CellNone, IdGuest: CellMine},
	SysFinance:    {IdOwner: CellAll, IdMember: CellMine, IdWardAcc: CellNone, IdWardNoAcc: CellNone, IdGuest: CellNone},
}

// 层 2：scope=module 的面挂载判定（唯一输入 FamilyModule）
var familyModules = map[string]map[SystemKey]bool{
	"fam-1": {SysFinance: true, SysCalendar: true, SysMemberPerm: true, SysCollab: true},
	// SysModuleCfg 无行 = 系统级面，恒可见
}

// 层 3：字段级可见性（含私密流水的行级可见性）
type FieldLevel string

const (
	LvVisible FieldLevel = "visible"
	LvConfirm FieldLevel = "confirm"
	LvMasked  FieldLevel = "masked"
	LvHidden  FieldLevel = "hidden"
)

type Subject struct {
	Identity  Identity
	MemberID  string
	FamilyID  string
	HasUser   bool
	IsOwner   bool // 在资源语境下：是否为 owner 角色
	Confirmed bool // L3 二次确认
}

type Txn struct {
	ID        string
	FamilyID  string
	AuthorID  string
	IsPrivate bool
	IsL3      bool
}

func moduleDecision(s Subject, sys SystemKey) (bool, string) {
	if sys == SysModuleCfg {
		return true, "系统级面：不进 FamilyModule，恒可见"
	}
	m, ok := familyModules[s.FamilyID]
	if !ok {
		return false, "未知家庭（fail closed）"
	}
	if !m[sys] {
		return false, "面未启用（无行）"
	}
	return true, "面已启用"
}

func matrixCell(sys SystemKey, id Identity) Cell {
	row, ok := matrix[sys]
	if !ok {
		return CellNone
	}
	c, ok2 := row[id]
	if !ok2 {
		return CellNone
	}
	return c
}

func fieldLevel(s Subject, t Txn) (FieldLevel, string) {
	// 矩阵层：ward/guest 在财务域是「—」
	if matrixCell(SysFinance, s.Identity) == CellNone {
		return LvHidden, "矩阵层：该身份在财务域无权限"
	}
	if !t.IsPrivate {
		if t.IsL3 && !s.IsOwner {
			return LvMasked, "L3 对非 owner 返回掩码"
		}
		return LvVisible, "非私密"
	}
	// 私密：行级
	if t.AuthorID != s.MemberID && !s.IsOwner {
		return LvHidden, "私密，作者不是我也不是 owner"
	}
	if t.IsL3 && !s.Confirmed && s.IsOwner {
		return LvConfirm, "owner 看 L3 需二次确认"
	}
	return LvVisible, "可见"
}

type Decision struct {
	Allow bool
	Stage string
	Why   string
}

// P1 的完整判定：三层串联
func decideP1(s Subject, sys SystemKey, t *Txn) Decision {
	if ok, why := moduleDecision(s, sys); !ok {
		return Decision{false, "层2 module", why}
	}
	if matrixCell(sys, s.Identity) == CellNone {
		return Decision{false, "层1 矩阵", "矩阵该格是「—」"}
	}
	if t != nil {
		lv, why := fieldLevel(s, *t)
		if lv == LvHidden {
			return Decision{false, "层3 字段/行级", why}
		}
		return Decision{true, "层3 字段/行级", why}
	}
	return Decision{true, "层1 矩阵", "矩阵允许"}
}

// ===== P1 不做的两层：恒空但保留形状 =====
type FamilyOverride struct {
	MemberID string
	Action   string
	Resource string
	Allow    bool
}

type ObjectACL struct {
	Resource string
	MemberID string
	Allow    bool
}

