	fmt.Println("  恒返回 `[]` 而不是 `null` 或干脆不返回，")
	fmt.Println("  以及 Go 的 nil slice 在 JSON 序列化时的那个坑。")
}

func splitLines(s string) []string {
	out := []string{}
	cur := ""
	for _, r := range s {
		if r == '\n' {
			out = append(out, cur)
			cur = ""
			continue
		}
		cur += string(r)
	}
	if cur != "" {
		out = append(out, cur)
	}
	return out
}

func yn(b bool) string {
	if b {
		return "放行"
	}
	return "拒绝"
}

var _ = FamilyOverride{}
