// =====================================================================
// W22 d28：权限缓存 —— TTL 60 秒 + pver 比对 + 事件失效，≤1 秒生效。
//
// 本机没有 Postgres。缓存逻辑真跑，时间用**手动推进的固定时钟**，
// 保证输出完全确定（两次运行 md5 一致）。
// tech-plan §8.6：
//   - 进程内缓存 TTL 60 秒 + 数据库层 `pver` 比对
//   - 收到 `homeos.permission.updated` **立即失效**
//   - **生效时限 ≤1 秒**
// =====================================================================

package main

import "fmt"

// ============ 模拟时钟（手动推进 → 输出确定）============

type Clock interface {
	Now() int // 返回「秒」
	Advance(sec int)
}

type FakeClock struct{ sec int }

func (c *FakeClock) Now() int        { return c.sec }
func (c *FakeClock) Advance(sec int) { c.sec += sec }
func (c *FakeClock) Since(t int) int { return c.sec - t }
func (c *FakeClock) String() string  { return fmt.Sprintf("T+%ds", c.sec) }

// ============ 被缓存的对象 ============

type Snapshot struct {
	Pver    int
	Role    string
	Modules []string
	Loaded  int // 加载时刻（秒）
}

type CacheEntry struct {
	snap    Snapshot
	expires int // 过期时刻
}

// ============ 缓存实现 ============

type PermCache struct {
	clock   *FakeClock
	entries map[string]*CacheEntry // key = familyID + ":" + memberID
	dbPver  int                    // 数据库里的当前 pver（模拟）
	loads   int                    // 真实加载次数（用于验证缓存有效性）
	hits    int
	misses  int
	// 失效事件到达时刻（-1 表示未收到）
	lastInvalidateAt int
	// 策略开关：三种策略必须真的走不同代码路径，否则对比没有意义
	enablePverCheck bool // 是否每次读缓存都比对 pver（需要一次 DB 查询）
	enableEvent     bool // 是否支持事件立即失效
}

func newPermCache(c *FakeClock) *PermCache {
	// 默认是完整方案（pver 比对 + 事件失效）
	return &PermCache{clock: c, entries: map[string]*CacheEntry{}, dbPver: 7,
		lastInvalidateAt: -1, enablePverCheck: true, enableEvent: true}
}

func newPermCacheWith(c *FakeClock, pverCheck, event bool) *PermCache {
	return &PermCache{clock: c, entries: map[string]*CacheEntry{}, dbPver: 7,
		lastInvalidateAt: -1, enablePverCheck: pverCheck, enableEvent: event}
}

// SetDBPver 模拟：owner 修改权限 → 数据库 pver+1
func (c *PermCache) SetDBPver(p int) {
	c.dbPver = p
}

// Invalidate 模拟：收到 homeos.permission.updated 事件
func (c *PermCache) Invalidate() {
	c.lastInvalidateAt = c.clock.Now()
	if !c.enableEvent {
		// 策略 A/B 没有订阅事件 —— 事件到了也没用
		return
	}
	for k := range c.entries {
		delete(c.entries, k)
	}
}

func key(fam, member string) string { return fam + ":" + member }

// Get 是完整的取权限路径：缓存 → pver 比对 → 落库
func (c *PermCache) Get(fam, member string) (Snapshot, string) {
	k := key(fam, member)

	// 第一步：查进程内缓存
	if e, ok := c.entries[k]; ok {
		if c.clock.Now() < e.expires {
			// 缓存还有效。
			// 策略 A「只有 TTL」：直接返回，**不做任何校验** —— 这就是它慢的原因。
			// 策略 B/C：必须再比一次 pver（模拟一次 DB 查询）
			if !c.enablePverCheck {
				c.hits++
				return e.snap, fmt.Sprintf("缓存命中（TTL 未到，**未做 pver 比对**：返回旧的 pver=%d）", e.snap.Pver)
			}
			if e.snap.Pver == c.dbPver {
				c.hits++
				return e.snap, fmt.Sprintf("缓存命中（TTL 未到，且 pver 一致：%d）", e.snap.Pver)
			}
			// pver 变了：缓存里的数据**已过期**，必须重载
			delete(c.entries, k)
			c.misses++
		} else {
			// TTL 到了
			delete(c.entries, k)
			c.misses++
		}
	} else {
		c.misses++
	}

	// 第二步：从数据库加载
	c.loads++
	loadedAt := c.clock.Now()
	snap := Snapshot{
		Pver:    c.dbPver, // 读数据库当前的 pver
		Role:    "member",
		Modules: []string{"finance", "calendar"},
		Loaded:  loadedAt,
	}
	c.entries[k] = &CacheEntry{
		snap:    snap,
		expires: loadedAt + 60, // TTL 60 秒
	}
	return snap, fmt.Sprintf("从数据库加载（pver=%d，缓存有效期到 T+%ds）", snap.Pver, loadedAt+60)
}

// ============ 三种失效机制对比 ============

type Strategy string

const (
	StratTTLOnly     Strategy = "只有 TTL（无 pver 比对、无事件）"
	StratTTLPlusPver Strategy = "TTL + pver 比对（无事件）"
	StratFull        Strategy = "TTL + pver 比对 + 事件失效（本项目方案）"
)

type Result struct {
	strategy     Strategy
	loadedAt     int
	changeAt     int
	noticedAt    int // 什么时候新权限生效了
	effectiveSec int // 从改动到生效的秒数
	meets1Sec    bool
	loads        int
	note         string
}

// 模拟：权限改动在 changeAt 时刻发生
func simulate(s Strategy, clock *FakeClock) Result {
	var c *PermCache
	switch s {
	case StratTTLOnly:
		c = newPermCacheWith(clock, false, false)
	case StratTTLPlusPver:
		c = newPermCacheWith(clock, true, false)
	default:
		c = newPermCacheWith(clock, true, true)
	}
	// 先预热：读一次，建立缓存
	c.Get("fam-1", "m-lina")
	loadedAt := clock.Now()
	loadsBefore := c.loads

	// 10 秒后 owner 改了权限
	clock.Advance(10)
	changeAt := clock.Now()
	c.SetDBPver(8)
	if s == StratFull {
		c.Invalidate() // 事件立即失效
	}

	// 之后每秒轮询一次（模拟下一次请求）
	noticedAt := -1
	for i := 0; i < 130; i++ {
		snap, _ := c.Get("fam-1", "m-lina")
		if snap.Pver == 8 {
			noticedAt = clock.Now()
			break
		}
		clock.Advance(1)
	}

	if noticedAt < 0 {
		noticedAt = clock.Now()
	}
	eff := noticedAt - changeAt
	res := Result{
		strategy:     s,
		loadedAt:     loadedAt,
		changeAt:     changeAt,
		noticedAt:    noticedAt,
		effectiveSec: eff,
		loads:        c.loads - loadsBefore,
	}
	res.meets1Sec = eff <= 1

	note := ""
	switch s {
	case StratTTLOnly:
		note = "权限改动要等**缓存自然过期**才生效 —— 最坏 60 秒"
	case StratTTLPlusPver:
		note = "下一次请求就会比对 pver 并重载 —— 立即生效，但要付一次查询"
	case StratFull:
		note = "事件直接清缓存 —— 立即生效，且不必比对（省一次查询）"
	}
	res.note = note
	return res
}

