package main

import (
	"fmt"
	"strings"
)

// ============ 时钟 ============

type FakeClock struct{ sec int }

func (c *FakeClock) Now() int       { return c.sec }
func (c *FakeClock) Advance(s int)  { c.sec += s }
func (c *FakeClock) String() string { return fmt.Sprintf("T+%ds", c.sec) }

// ============ 被缓存的数据 ============

type FamilyModule struct {
	FamilyID  string
	Code      string
	Enabled   bool
	EnabledBy string
	UpdatedAt int
}

type PermSnapshot struct {
	Pver    int
	Role    string
	Modules []string
}

type Entry struct {
	snap      PermSnapshot
	modules   []FamilyModule
	loadedAt  int
	expiresAt int
}

type Cache struct {
	clock   *FakeClock
	entries map[string]*Entry
	dbPver  int
	// 开关
	enablePverCheck bool
	enableEvent     bool
	// 统计
	loads             int
	loadsFromEvent    int
	pverChecks        int
	invalidations     int
	lastInvalidatedAt int
}

func NewCache(c *FakeClock) *Cache {
	return &Cache{
		clock: c, entries: map[string]*Entry{}, dbPver: 7,
		enablePverCheck: true, enableEvent: true, lastInvalidatedAt: -1,
	}
}

func (c *Cache) Get(fam, member string) (PermSnapshot, string) {
	k := fam + ":" + member
	if e, ok := c.entries[k]; ok {
		if c.clock.Now() < e.expiresAt {
			if !c.enablePverCheck {
				return e.snap, "缓存命中（未做 pver 比对）"
			}
			c.pverChecks++
			if e.snap.Pver == c.dbPver {
				return e.snap, fmt.Sprintf("缓存命中（pver 一致 %d）", e.snap.Pver)
			}
			delete(c.entries, k) // pver 变了 → 作废
		} else {
			delete(c.entries, k) // TTL 到了
		}
	}
	c.loads++
	now := c.clock.Now()
	snap := PermSnapshot{Pver: c.dbPver, Role: "member", Modules: []string{"finance", "calendar"}}
	mods := []FamilyModule{
		{FamilyID: fam, Code: "finance", Enabled: true, UpdatedAt: 100},
		{FamilyID: fam, Code: "calendar", Enabled: true, UpdatedAt: 100},
		{FamilyID: fam, Code: "budget", Enabled: false, UpdatedAt: 120},
	}
	c.entries[k] = &Entry{snap: snap, modules: mods, loadedAt: now, expiresAt: now + 60}
	return snap, fmt.Sprintf("从 DB 加载（pver=%d，TTL 到 T+%ds）", snap.Pver, now+60)
}

// ModulesOf 返回缓存里的 FamilyModule（供 module 判定用）
func (c *Cache) ModulesOf(fam, member string) ([]FamilyModule, bool) {
	if e, ok := c.entries[fam+":"+member]; ok && c.clock.Now() < e.expiresAt {
		return e.modules, true
	}
	return nil, false
}

// InvalidateFamily 清掉某家庭的全部条目（为什么不是单个 member，见失效点 3）
func (c *Cache) InvalidateFamily(fam string) {
	c.invalidations++
	c.lastInvalidatedAt = c.clock.Now()
	for k := range c.entries {
		if strings.HasPrefix(k, fam+":") {
			delete(c.entries, k)
		}
	}
}

func (c *Cache) SetDBPver(p int) { c.dbPver = p }

