// ===================== 被整合的三套判定 =====================

type Identity string

const (
	IdOwner     Identity = "owner"
	IdMember    Identity = "member"
	IdWardAcc   Identity = "ward_acc"
	IdWardNoAcc Identity = "ward_noacc"
	IdGuest     Identity = "guest"
