// ---- 整合后的唯一判定 ----
type Decision struct {
	Code    int    // 0 / 40402
	Stage   string // 在哪一层定的
	Reason  string // 对内 reason
	FieldLv FieldLevel
}

func matrixCell(sys SystemKey, id Identity) Cell {
	row, ok := matrix[sys]
	if !ok {
		return CellNone
	}
	c, ok2 := row[id]
	if !ok2 {
		return CellNone
	}
	return c
}

func moduleOK(s Subject, sys SystemKey) bool {
	if sys == SysModuleCfg {
		return true // 系统级面
	}
	m, ok := familyModules[s.FamilyID]
	if !ok {
		return false
	}
	return m[sys]
}

func fieldLevel(s Subject, t Txn, confirmed bool) FieldLevel {
	if matrixCell(SysFinance, s.Identity) == CellNone {
		return LvHidden
	}
	if t.IsPrivate && t.AuthorID != s.MemberID && s.Identity != IdOwner {
		return LvHidden
	}
	if t.IsL3 && s.Identity != IdOwner {
		return LvMasked
	}
	if t.IsL3 && !confirmed && s.Identity == IdOwner {
		return LvConfirm
	}
	return LvVisible
}

func Authorize(s Subject, sys SystemKey, t *Txn, act string, confirmed bool) Decision {
	if !moduleOK(s, sys) {
		return Decision{40402, "层2 module", "module_disabled", LvHidden}
	}
	if matrixCell(sys, s.Identity) == CellNone {
		return Decision{40402, "层1 矩阵", "matrix_denied", LvHidden}
	}
	if t != nil {
		if t.FamilyID != s.FamilyID {
			return Decision{40402, "层2 data", "cross_family", LvHidden}
		}
		lv := fieldLevel(s, *t, confirmed)
		if lv == LvHidden {
			return Decision{40402, "层3 行级", "private_not_visible", LvHidden}
		}
		return Decision{0, "层3 字段级", "ok", lv}
	}
	return Decision{0, "层1 矩阵", "ok", LvVisible}
}

// ===================== 测试框架 =====================

type Suite struct {
	Name   string
	Total  int
	Passed int
	Fails  []string
}

func (s *Suite) Assert(ok bool, desc, detail string) {
	s.Total++
	if ok {
		s.Passed++
	} else {
		s.Fails = append(s.Fails, desc+" — "+detail)
	}
}

func (s *Suite) Report() {
	mark := "✅"
	if len(s.Fails) > 0 {
		mark = "❌"
	}
	fmt.Printf("  %s %-36s %d/%d\n", mark, s.Name, s.Passed, s.Total)
	for _, f := range s.Fails {
		fmt.Printf("       ❌ %s\n", f)
	}
}

func codeOf(c int) string {
	if c == 0 {
		return "200"
	}
	return "404"
}

