		{"member(fam-1) 读他人私密(另一 member)", member1b, SysFinance, "t-A3"},
		{"ward 读家庭财务", ward1, SysFinance, "t-A1"},
		{"ward 读家庭私密", ward1, SysFinance, "t-A3"},
		{"guest 读家庭财务", guest1, SysFinance, "t-A1"},
		{"guest 读家庭私密", guest1, SysFinance, "t-A5"},
		{"guest 进成员管理域", guest1, SysMemberPerm, ""},
		{"ward 进成员管理域", ward1, SysMemberPerm, ""},
	}
	for _, a := range attacks {
		var t *Txn
		if a.id != "" {
			t = getTxn(a.id)
		}
		d := Authorize(a.s, a.sys, t, "read", false)
		s4.Assert(d.Code == 40402, a.desc,
			fmt.Sprintf("期望 404，实际 %s（%s）", codeOf(d.Code), d.Reason))
		s4.Assert(d.Code != 403, a.desc+" 不返回 403", fmt.Sprintf("Code=%d", d.Code))
		fmt.Printf("  %-40s %-10s %-10s %s\n", a.desc, "404", codeOf(d.Code), d.Reason)
	}
	s4.Report()
	fmt.Println()

	// ===== 套件 5：模糊测试 100 次 =====
	fmt.Println("=== 6. 套件⑤：模糊测试（100 次，判据 5）===")
	fmt.Println()
	s5 := &Suite{Name: "⑤ 模糊测试（100 次）"}
	rnd := rand.New(rand.NewSource(20261015))
	ids := []string{}
	for _, t := range txns {
		ids = append(ids, t.ID)
	}
	ids = append(ids, "t-Z1", "t-Z2", "", "' OR 1=1--", "../../etc/passwd", "t-A1'")
	subs := []Subject{owner1, member1, member1b, ward1, wardNo1, guest1, owner2,
		{IdOwner, "m-x", "fam-9"}}

	leaks := 0
	leakSamples := []string{}
	const rounds = 100
	for i := 0; i < rounds; i++ {
		id := ids[rnd.Intn(len(ids))]
		subj := subs[rnd.Intn(len(subs))]
		var t *Txn
		if tt, ok := byID[id]; ok {
			tt := tt
			t = &tt
		}
		d := Authorize(subj, SysFinance, t, "read", false)

		// 断言 1：放行的行必须属于会话家庭
		if d.Code == 0 && t != nil {
			s5.Assert(t.FamilyID == subj.FamilyID, fmt.Sprintf("第%d次 家庭隔离", i+1),
				fmt.Sprintf("%s(%s) 读到 fam-1 的 %s", subj.MemberID, subj.FamilyID, t.ID))
			if t.FamilyID != subj.FamilyID {
				leaks++
			}
		}
		// 断言 2：放行的行必须满足行级可见
		if d.Code == 0 && t != nil {
			visOK := !t.IsPrivate || t.AuthorID == subj.MemberID || subj.Identity == IdOwner
			s5.Assert(visOK, fmt.Sprintf("第%d次 行级可见", i+1),
				fmt.Sprintf("%s 读到私密 %s", subj.MemberID, t.ID))
			if !visOK {
				leaks++
				if len(leakSamples) < 5 {
					leakSamples = append(leakSamples,
						fmt.Sprintf("%s(%s) → %s", subj.MemberID, subj.Identity, t.ID))
				}
			}
		}
		// 断言 3：拒绝时必须是 404
		if d.Code != 0 {
			s5.Assert(d.Code == 40402, fmt.Sprintf("第%d次 返 404", i+1),
				fmt.Sprintf("实际 Code=%d", d.Code))
		}
	}
	s5.Report()
	fmt.Printf("  %d 次请求，泄露 %d 次。\n", rounds, leaks)
	for _, l := range leakSamples {
		fmt.Printf("    ❌ %s\n", l)
	}
	fmt.Println()

	// ===== 汇总 =====
	fmt.Println("=== 7. 汇总 ===")
	fmt.Println()
	suites := []*Suite{s1, s2, s3, s4, s5}
	total, passed := 0, 0
	for _, s := range suites {
		total += s.Total
		passed += s.Passed
	}
	for _, s := range suites {
		s.Report()
	}
	fmt.Println()
	fmt.Printf("  断言 %d 条，通过 %d，失败 %d。\n", total, passed, total-passed)
	if total == passed {
		fmt.Println("  ✅ 五套全部通过。这是 S5 判据 5 的最终确认：")
		fmt.Println("     「有一个跑在代码里的越权测试循环，不是手动点几次」。")
	}
	fmt.Println()

	fmt.Println("=== 8. 从套件到 CI ===")
	fmt.Println()
	files := []struct{ path, covers string }{
		{"test/authz/matrix_test.go", "25 格矩阵逐格 + 结构 + owner 列全 A"},
		{"test/authz/module_test.go", "面可见性（3 个家庭 × 4 个面 × 3 个身份）"},
		{"test/authz/rowfield_test.go", "行级 + 字段级（判据 2）"},
		{"test/authz/idor_test.go", "越权矩阵，13 个跨家庭/跨成员场景（判据 1）"},
		{"test/authz/fuzz_test.go", "100 次伪随机循环（判据 5）"},
	}
	fmt.Printf("  %-34s %s\n", "文件", "覆盖")
	for _, f := range files {
		fmt.Printf("  %-34s %s\n", f.path, f.covers)
	}
	fmt.Println()
	fmt.Println("  运行：")
	fmt.Println("    go test ./test/authz/...")
	fmt.Println("    go test -fuzz=FuzzAuthorize -fuzztime=30s ./test/authz/")
	fmt.Println()
	fmt.Println("  放进 CI 五道门禁之一（tech-plan §10.2 门禁 4：单测必须绿）。")
	fmt.Println("  注意 fuzz 不进常规 CI（要时间），只进 nightly。")
	fmt.Println()

	fmt.Println("=== 9. 明天 ===")
	fmt.Println("  今天把 S5 的测试整合到一处并全绿。")
	fmt.Println("  明天做 S5 的**阶段判据自测**：写 scripts/s5-check.sh，")
	fmt.Println("  把五条硬判据变成一条命令：")
	fmt.Println("    bash scripts/s5-check.sh")
	fmt.Println("  它的价值在于：**把「我以为做完了」变成「验证过做完了」**。")
	fmt.Println("  这与 go test 是不同层次 —— go test 验证代码，")
	fmt.Println("  s5-check 验证「该存在的东西存在、该不存在的东西不存在」。")
}

