type Result struct {
	Name   string
	OK     bool
	Detail string
}

type Report struct {
	Section string
	Results []Result
}

func (r *Report) Add(name string, ok bool, detail string) {
	r.Results = append(r.Results, Result{name, ok, detail})
}

func (r *Report) Print() (pass, fail int) {
	fmt.Printf("  【%s】\n", r.Section)
	for _, x := range r.Results {
		mark := "✅"
		if !x.OK {
			mark = "❌"
		}
		fmt.Printf("    %s %-46s %s\n", mark, x.Name, x.Detail)
		if x.OK {
			pass++
		} else {
			fail++
		}
	}
	fmt.Println()
	return
}

