// homeos_role.permissions 是它的可查询镜像，两者必须一致。
var matrix = map[SystemKey]map[Identity]Cell{
	SysMemberPerm: {IdOwner: CellAll, IdMember: CellMine, IdWardAcc: CellNone, IdWardNoAcc: CellNone, IdGuest: CellNone},
	SysModuleCfg:  {IdOwner: CellAll, IdMember: CellRead, IdWardAcc: CellRead, IdWardNoAcc: CellNone, IdGuest: CellRead},
	SysCalendar:   {IdOwner: CellAll, IdMember: CellMine, IdWardAcc: CellMine, IdWardNoAcc: CellNone, IdGuest: CellMine},
