// Authorize 是唯一判定入口。
//
// 为什么越权返 404 不返 403：403 会告诉攻击者「这个 id 确实存在」，
// 他可以据此枚举真实存在的资源。404 让「不存在」与「无权限」不可区分。
// 对内通过 audit_log 记录真实 reason，对外统一说「不存在」。
func Authorize(s Subject, a Action, res Resource) Decision {
	// ① 显式拒绝
	if d := findDeny(s.MemberID, res.Key); d != nil {
		return deny(StageDeny, ReasonDenied)
	}
	// ② 角色默认矩阵
	if matrixCell(res.System, identityOf(s)) == CellNone {
		return deny(StageMatrix, ReasonMatrixDenied) // 404，不返 403
	}
	// ③ 家庭级覆盖（P1 恒空，位置留着）
	// ④ 对象级 ACL（P1 恒空，位置留着）
	// 行级：私密流水仅作者与 owner 可见
	if res.IsPrivate && res.AuthorID != s.MemberID && s.Identity != IdOwner {
		audit(s, a, res.Key, "deny", ReasonPrivateNotVisible)
		return deny(StageRowLevel, ReasonPrivateNotVisible)
	}
	return allow()
}

// 对内 reason 常量（写进 audit_log；**绝不出现在对外响应里**）
const (
	ReasonDenied            = "denied"
	ReasonMatrixDenied      = "matrix_denied"
	ReasonPrivateNotVisible = "private_not_visible" // 行级：私密流水仅作者与 owner
)

func deny(stage Stage, reason string) Decision {
	// 40402 = 「资源不存在」。**不要**改成 403。
	// 审计要在拒绝处记，而不是在中间件里猜。
	audit(current(), currentAction(), currentRes(), "deny", reason)
	return Decision{Allow: false, Code: 40402, Stage: stage, Reason: reason}
}`,
