func fileExists(path string) (string, bool) {
	if body, ok := mockFiles[path]; ok {
		return body, true
	}
	return "", false
}

func grepFile(path, pattern string) []string {
	body, ok := fileExists(path)
	if !ok {
		return nil
	}
	re, err := regexp.Compile(pattern)
	if err != nil {
		return nil
	}
	hits := []string{}
	for i, line := range strings.Split(body, "\n") {
		if re.MatchString(line) {
			trimmed := strings.TrimSpace(line)
			if len(trimmed) > 58 {
				trimmed = trimmed[:58] + "…"
			}
			hits = append(hits, fmt.Sprintf("L%d: %s", i+1, trimmed))
		}
	}
	return hits
}

