package main

import (
	"encoding/base64"
	"fmt"
	"strings"
)

// ============ 场景数据 ============

type Session struct {
	UserID   string
	MemberID string
	FamilyID string
	Role     string
}

type Txn struct {
	ID       string
	FamilyID string
	Amount   int64
}

var db = []Txn{
	{"t-A1", "fam-1", 480000},
	{"t-A2", "fam-1", 12800},
	{"t-B1", "fam-2", 99900},
	{"t-B2", "fam-2", 88800},
	{"t-C1", "fam-3", 1200000},
}

var owner1 = Session{"u-1", "m-zhangwei", "fam-1", "owner"}
var member1 = Session{"u-2", "m-lina", "fam-1", "member"}

// =====================================================================
// 手法一：ID 遍历
// =====================================================================

func vulnGetByID(s Session, id string) (Txn, bool) {
	for _, t := range db {
		if t.ID == id {
			return t, true
		}
	}
	return Txn{}, false
}

func safeGetByID(s Session, id string) (Txn, bool) {
	for _, t := range db {
		if t.ID == id && t.FamilyID == s.FamilyID {
			return t, true
		}
	}
	return Txn{}, false
}

func demoIDTraversal() {
	fmt.Println("=== 手法一：ID 遍历（改 id / 枚举）===")
	fmt.Println()
	fmt.Println("  攻击者假设：id 是自增整数或者有规律的编号。")
	fmt.Println("  他依次请求 txn-1、txn-2、txn-3 ……")
	fmt.Println()
	fmt.Printf("  %-12s %-12s %-12s %-12s %s\n", "请求 id", "存在?", "有 bug", "有防御", "泄露内容")
	probes := []string{"t-A1", "t-B1", "t-B2", "t-C1", "t-9", "t-0"}
	leakedV, leakedS := 0, 0
	for _, id := range probes {
		exists := false
		for _, t := range db {
			if t.ID == id {
				exists = true
			}
		}
		_, okV := vulnGetByID(owner1, id)
		rowS, okS := safeGetByID(owner1, id)
		markE := "不存在"
		if exists {
			markE = "存在"
		}
		content := "—"
		if okV {
			content = fmt.Sprintf("%d 元（%s）", rowS.Amount/100, rowS.FamilyID)
			if rowS.FamilyID != owner1.FamilyID {
				leakedV++
			}
		}
		if okS && rowS.FamilyID != owner1.FamilyID {
			leakedS++
		}
		fmt.Printf("  %-12s %-12s %-12s %-12s %s\n", id, markE, codeOf(okV), codeOf(okS), content)
	}
	fmt.Println()
	fmt.Printf("  有 bug：泄露 %d 条他家庭的数据。有防御：泄露 %d 条。\n", leakedV, leakedS)
	fmt.Println()
	fmt.Println("  防御（本项目）：")
	defenses1 := []struct{ item, how string }{
		{"每个查询带 family_id", "S3 d18/d19 的纪律 —— 这是根本防线"},
		{"UUID v4 主键", "**不是**访问控制，只是把枚举成本从零提到高"},
		{"限流", "防暴力枚举，不防「已知 id 的直接访问」"},
		{"异常行为检测", "同一 token 短时间大量 404 → 告警（d23 讲过审计的用途）"},
	}
	fmt.Printf("    %-24s %s\n", "手段", "作用")
	for _, d := range defenses1 {
		fmt.Printf("    %-24s %s\n", d.item, d.how)
	}
