// ❌ 服务端信任前端传来的 family_id / role
func vulnList(s Session, params map[string]string) []Txn {
	famID := params["family_id"]
	if famID == "" {
		famID = s.FamilyID
	}
	out := []Txn{}
	for _, t := range db {
		if t.FamilyID == famID {
			out = append(out, t)
		}
	}
	return out
}

// ✅ family_id 只从会话取，参数里的值被忽略
func safeList(s Session, params map[string]string) []Txn {
	_ = params // 参数被**完全忽略**
	out := []Txn{}
	for _, t := range db {
		if t.FamilyID == s.FamilyID {
			out = append(out, t)
		}
	}
	return out
}

