// ❌ 无上限返回 + 不分页 + 无角色限制
func vulnExport(s Session, limit int) ([]Txn, string) {
	out := []Txn{}
	for _, t := range db {
		if t.FamilyID == s.FamilyID {
			out = append(out, t)
		}
		if len(out) >= limit {
			break
		}
	}
	return out, "无上限"
}

// ✅ export 是独立 action + 游标分页 + 上限
func safeExport(s Session, limit int, cursor string) ([]Txn, string) {
	if s.Role != "owner" {
		return nil, "403 → 404：只有 owner 能导出"
	}
	if limit > 200 {
		return nil, "400：limit 上限 200"
	}
	out := []Txn{}
	started := cursor == ""
	for _, t := range db {
		if t.FamilyID != s.FamilyID {
			continue
		}
		if !started {
			started = true
			continue // 跳过游标指向的那条（简化的游标语义）
		}
		out = append(out, t)
		if len(out) >= limit {
			break
		}
	}
	return out, "游标分页 + 上限 200"
}

