// =====================================================================
// 手法四：JWT 算法混淆
// =====================================================================

// 模拟三种 token 形态
func b64(s string) string { return base64.RawURLEncoding.EncodeToString([]byte(s)) }

func hdr(alg string) string { return b64(`{"alg":"` + alg + `","typ":"JWT"}`) }

func payloadJSON(s Session) string {
	return b64(fmt.Sprintf(`{"uid":%q,"mid":%q,"fam":%q,"role":%q,"pver":"7","typ":"access"}`,
		s.UserID, s.MemberID, s.FamilyID, s.Role))
}

// ❌ 服务端用「token 头里的 alg」决定验签方式
func verifyUsingHeaderAlg(token string, secret []byte) (Session, string) {
	parts := strings.Split(token, ".")
	if len(parts) != 3 {
		return Session{}, "格式错误"
	}
	h, err1 := base64.RawURLEncoding.DecodeString(parts[0])
	if err1 != nil {
		return Session{}, "header 解码失败"
	}
	pl, err2 := base64.RawURLEncoding.DecodeString(parts[1])
	if err2 != nil {
		return Session{}, "payload 解码失败"
	}
	hdrStr := string(h)
	alg := "HS256"
	if strings.Contains(hdrStr, `"alg":"none"`) {
		alg = "none"
	}
	plStr := string(pl)
	_ = secret // 假装有验签逻辑
	return parseSession(plStr), "按 header 的 alg=" + alg + " 决定验签方式"
}

// ✅ 服务端**自己配置**允许的算法，不看 header
func verifyFixedAlg(token string, secret []byte) (Session, string) {
	parts := strings.Split(token, ".")
	if len(parts) != 3 {
		return Session{}, "格式错误"
	}
	h, _ := base64.RawURLEncoding.DecodeString(parts[0])
	pl, _ := base64.RawURLEncoding.DecodeString(parts[1])
	// 关键：算法是**服务端常量**，不读 header
	if !strings.Contains(string(h), `"alg":"HS256"`) {
		return Session{}, "拒绝：只接受 HS256，header 声明的其他算法一律不认"
	}
	_ = secret
	return parseSession(string(pl)), "按服务端固定算法 HS256 验签 ✅"
}

func parseSession(pl string) Session {
	get := func(k string) string {
		marker := `"` + k + `":"`
		i := strings.Index(pl, marker)
		if i < 0 {
			return ""
		}
		rest := pl[i+len(marker):]
		j := strings.Index(rest, `"`)
		if j < 0 {
			return ""
		}
		return rest[:j]
	}
	return Session{get("uid"), get("mid"), get("fam"), get("role")}
}

func demoJWTAlg() {
	fmt.Println("=== 手法四：JWT 算法混淆（alg=none）===")
	fmt.Println()
	fmt.Println("  攻击者不发签名，只改 header 里的 alg：")
	fmt.Println("    正常：  {\"alg\":\"HS256\",\"typ\":\"JWT\"}  + payload + 签名")
	fmt.Println("    攻击：  {\"alg\":\"none\",\"typ\":\"JWT\"}    + payload + 空签名")
	fmt.Println()
	fmt.Println("  JWT 的 header 是 base64，攻击者可以随意改。")
	fmt.Println("  如果服务端「按 header 声明的算法选择验签方式」，")
	fmt.Println("  那 alg=none 就意味着「不验签」。")
	fmt.Println()
	fake := Session{"u-999", "m-attacker", "fam-3", "owner"}
	attacks := []struct{ name, token string }{
		{"alg=none，无签名", hdr("none") + "." + payloadJSON(fake) + "."},
		{"alg=HS256，伪造签名", hdr("HS256") + "." + payloadJSON(fake) + "." + b64("fake-signature")},
		{"alg=None 大写", hdr("None") + "." + payloadJSON(fake) + "."},
	}
	fmt.Printf("  伪造的 token 内容：\n")
	fmt.Printf("    uid=u-999  mid=m-attacker  fam=fam-3  role=owner  ← 声称自己是 fam-3 的 owner\n\n")
	fmt.Printf("  %-26s %-12s %-14s %s\n", "攻击", "有 bug", "有防御", "原因")
	vulnOK, safeOK := 0, 0
	for _, a := range attacks {
		s1, why1 := verifyUsingHeaderAlg(a.token, []byte("secret"))
		s2, why2 := verifyFixedAlg(a.token, []byte("secret"))
		ok1 := s1.MemberID == "m-attacker"
		ok2 := s2.MemberID == "m-attacker"
		if ok1 {
			vulnOK++
		}
		if ok2 {
			safeOK++
		}
		fmt.Printf("  %-26s %-12s %-14s %s\n", a.name, ynRes(ok1), ynRes(ok2), why2)
		_ = why1
	}
	fmt.Println()
	fmt.Printf("  有 bug：%d/3 个攻击成功。有防御：%d/3 个攻击成功。\n", vulnOK, safeOK)
	fmt.Println()
	fmt.Println("  为什么 alg=none 最危险：")
	fmt.Println("    HS256 伪造签名需要知道密钥（做不到）；")
	fmt.Println("    **alg=none 不需要任何密钥** —— 它要求「不验签」。")
	fmt.Println("    所以这个漏洞一旦存在，就是完全绕过认证。")
	fmt.Println()
	fmt.Println("  防御清单（本项目采用）：")
	jwtDef := []struct{ item, detail string }{
		{"算法白名单写死在服务端", "const allowedAlg = \"HS256\"；不读 header.alg"},
		{"必须校验 kid", "kid 指向本地密钥文件路径，禁止读文件系统的任意路径（防路径穿越）"},
		{"密钥不进代码库", "环境变量 / secrets manager，且定期轮换"},
		{"校验 exp / iat / nbf", "时间窗判定，与 d11 的 condition 呼应"},
		{"校验 aud / iss", "防止别的系统的 token 拿来用"},
		{"token 里不放敏感信息", "§8.5：只放 uid/mid/fam/role/pver/typ"},
	}
	for i, d := range jwtDef {
		fmt.Printf("    %d. %-26s %s\n", i+1, d.item, d.detail)
	}
	fmt.Println()
	fmt.Println("  ⚠ kid 注入（另一种手法）：")
	fmt.Println("    如果服务端按 `kid` 去「文件路径」取密钥：")
	fmt.Println("      kid = \"../../etc/passwd\"")
	fmt.Println("    → 密钥文件内容会被读出来当签名密钥。")
	fmt.Println("    防御：kid 只允许匹配一个**正则白名单**（如 `^key-\\d{4}$`），")
	fmt.Println("          且映射到 map 而不是文件路径。")
	fmt.Println()
	fmt.Println("  Go 侧的库选择：golang-jwt/jwt v5 的 Parse 里有 ParseWithClaims +")
	fmt.Println("  `jwt.WithValidMethods([]string{\"HS256\"})` 选项。")
	fmt.Println("  **不传这个选项就是漏洞** —— 库的默认行为会接受 token 声明的算法。")
	fmt.Println("  对应到 JS：jsonwebtoken 的 decode() 不验签，verify() 才验 —— ")
	fmt.Println("  前端常见的错误是在服务端用 decode 代替 verify。")
	fmt.Println()
}

func keysOf(m map[string]bool) []string {
	out := []string{}
	for k := range m {
		out = append(out, k)
	}
	if len(out) == 0 {
		return []string{"（空）"}
	}
	return out
}

func codeOf(ok bool) string {
	if ok {
		return "200"
	}
	return "404"
}

func ynRes(ok bool) string {
	if ok {
		return "成功 💀"
	}
	return "被拒 ✅"
}

