package main

import "fmt"

type Verdict struct {
	Topic   string
	Student string // 学生的话（原话）
	Correct bool
	Fix     string // 学生的理解偏在哪，怎么掰回来
}

// 学生是一个「React/TS 很熟、Go 与后端安全刚接触」的前端。
// 下面是他在 S5 期间说过的 12 句话 —— 逐条判定。
var dialogues = []Verdict{
	{
		Topic:   "四级角色",
		Student: "角色就是一个字符串，后端判断 role == 'owner' 就行了，前端拿到 role 也能判断。",
		Correct: true,
		Fix:     "对。而且前端**确实要判断**（决定按钮显示）。但要注意：前端判断是体验层，服务端必须独立判断一遍 —— curl 不执行你的 React 代码。",
	},
	{
		Topic:   "四级角色",
		Student: "我把 role 写成 TS 的联合类型，就不会有非法值了。",
