	fmt.Println("  下一站是 S6（uni-app 工程化，W24-W25，14 张卡，系数 0.8）。")
	fmt.Println("  难度会明显降下来 —— 因为你已经会前端了。")
	fmt.Println()
	after := []struct{ item, why string }{
		{"S6 uni-app 工程化", "你会 Vue/TS 之后只剩框架差异；坑在 pages.json 不能有 tabBar"},
		{"S7 二级分类", "第一个完整功能域；走「定契约→建表→后端→前端→测试」五步"},
		{"…", "后续每个功能域都会**依赖** S5 的权限判定 —— 所以 S5 是地基"},
	}
	for _, a := range after {
		fmt.Printf("  %-22s %s\n", a.item, a.why)
	}
	fmt.Println()
	fmt.Println("  最后一句提醒：S5 的 34 天里，你搭的是**看不见的地基**。")
	fmt.Println("  它不会出现在界面上，不会被演示，但少了它，")
	fmt.Println("  上面盖的每一层都会漏水。")
	fmt.Println()
	fmt.Println("  这就是为什么 S5 的难度系数是 1.4 —— 全项目最难。")
	fmt.Println()

	fmt.Println("=== 10. 最后一件事：把你的理解写成一句话 ===")
	fmt.Println()
	fmt.Println("  如果你只能留一句话给三个月后的自己，留这句：")
	fmt.Println()
	fmt.Println("      「权限的每一个判定都必须落在服务端的一个函数里，")
	fmt.Println("        那个函数必须能被测试直接调用，")
	fmt.Println("        而且测试必须先红后绿才算数。」")
	fmt.Println()
	fmt.Println("  三句话，三个要素：")
	fmt.Println("    ① 落在服务端的一个函数里  → 不是散落在各处，是一处")
	fmt.Println("    ② 能被测试直接调用       → 不是通过 HTTP 才能测，是纯函数")
	fmt.Println("    ③ 先红后绿               → 测试本身要有效，不是摆设")
	fmt.Println()
	fmt.Println("  这就是 S5 的全部。")
}

func wrap(s string) string {
	lines := []string{}
	cur := ""
	for _, r := range s {
		cur += string(r)
		if len([]rune(cur)) >= 40 {
			lines = append(lines, cur)
			cur = ""
		}
	}
	if cur != "" {
		lines = append(lines, cur)
	}
	out := ""
	for i, l := range lines {
		if i == 0 {
			out += l
		} else {
			out += "\n            " + l
		}
	}
	return out
}
